export default function CommandPalette({ open, onClose, onNavigate, tasks = [] }) {
  const [query, setQuery] = useState('')
  const [selected, setSelected] = useState(0)
  const inputRef = useRef(null)
  const listRef = useRef(null)

  // Esc 交给浮层栈（只由栈顶响应）；输入框内不再单独处理 Esc
  useOverlayStack(onClose, open)

  useEffect(() => {
    if (open) {
      setQuery('')
      setSelected(0)
      setTimeout(() => inputRef.current?.focus(), 50)
    }
  }, [open])

  const results = useMemo(() => {
    const q = query.toLowerCase().trim()
    const items = []

    // Navigation items
    const views = q
      ? VIEWS.filter(v => v.label.toLowerCase().includes(q) || v.id.includes(q))
      : VIEWS
    for (const v of views) {
      items.push({ type: 'view', id: v.id, label: v.label, icon: v.icon })
    }

    // Task search
    if (q && tasks.length > 0) {
      const matched = tasks.filter(t =>
        t.title.toLowerCase().includes(q) ||
        t.id.toLowerCase().includes(q) ||
        (t.project || '').toLowerCase().includes(q)
      ).slice(0, 8)
      for (const t of matched) {
        items.push({
          type: 'task',
          id: t.id,
          label: t.title,
          stage: t.stage,
          state: t.state,
          project: t.project,
        })
      }
    }

    return items
  }, [query, tasks])

  useEffect(() => { setSelected(0) }, [query])

  const execute = useCallback((item) => {
    if (!item) return
    if (item.type === 'view') {
      onNavigate(item.id)
    } else if (item.type === 'task') {
      onNavigate('workflow', item.id)
    }
    onClose()
  }, [onNavigate, onClose])

  const handleKeyDown = useCallback((e) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault()
      setSelected(s => Math.min(s + 1, results.length - 1))
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      setSelected(s => Math.max(s - 1, 0))
    } else if (e.key === 'Enter') {
      e.preventDefault()
      execute(results[selected])
    }
  }, [results, selected, execute, onClose])

  // Scroll selected into view
  useEffect(() => {
    const el = listRef.current?.children[selected]
    el?.scrollIntoView({ block: 'nearest' })
  }, [selected])

  if (!open) return null

  return (
    <div className="cmd-overlay" onClick={onClose}>
      <div className="cmd-palette" onClick={e => e.stopPropagation()} role="dialog" aria-label="命令面板">
        <div className="cmd-input-wrap">
          <span className="cmd-input-icon">⌘</span>
          <input
            ref={inputRef}
            className="cmd-input"
            placeholder="搜索视图、任务…"
            value={query}
            onChange={e => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            role="combobox"
            aria-label="搜索视图或任务"
            aria-autocomplete="list"
            aria-expanded={results.length > 0}
            aria-controls="cmd-listbox"
            aria-activedescendant={results[selected] ? `cmd-opt-${results[selected].type}-${results[selected].id}` : undefined}
          />
          <kbd className="cmd-esc">ESC</kbd>
        </div>
        <div className="cmd-list" ref={listRef} id="cmd-listbox" role="listbox" aria-label="命令与任务结果">
          {results.length === 0 ? (
            <div className="cmd-empty" role="status">无匹配结果</div>
          ) : (
            results.map((item, i) => (
              <div
                key={`${item.type}-${item.id}`}
                id={`cmd-opt-${item.type}-${item.id}`}
                role="option"
                aria-selected={i === selected}
                className={`cmd-item${i === selected ? ' is-selected' : ''}`}
                onClick={() => execute(item)}
                onMouseEnter={() => setSelected(i)}
              >
                {item.type === 'view' ? (
                  <>
                    <span className="cmd-item__icon">{item.icon}</span>
                    <span className="cmd-item__label">{item.label}</span>
                    <kbd className="cmd-item__badge">{VIEWS.findIndex(v => v.id === item.id) + 1}</kbd>
                  </>
                ) : (
                  <>
                    <span className="cmd-item__icon">📌</span>
                    <span className="cmd-item__label">{item.label}</span>
                    <span className="cmd-item__meta mono">{item.stage} · {item.state}</span>
                  </>
                )}
              </div>
            ))
          )}
        </div>
        <div className="cmd-footer">
          <span><kbd>↑↓</kbd> 导航</span>
          <span><kbd>Enter</kbd> 选择</span>
          <span><kbd>ESC</kbd> 关闭</span>
        </div>
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { PRIORITY, parseUtc } from '../constants'
import { api } from '../api'
import { useOverlayStack } from '../lib/overlayStack'

const EMPTY = {
  title: '', description: '', priority: 0, est_duration_min: 30, target_agent_type: '',
  acceptance_criteria: '', due_at: '', labels: '', project: '', workspace: '',
  files: '', deliverables: '',
  schedule_type: 'once',
  cron_expr: '',
  webhook_url: '', webhook_method: 'POST', webhook_body: '',
}

// eslint-disable-next-line complexity, max-lines-per-function
export default function CreateModal({ onClose, onCreate }) {
  const [form, setForm] = useState(EMPTY)
  const [busy, setBusy] = useState(false)
  const [templates, setTemplates] = useState([])
  const [showTpl, setShowTpl] = useState(false)
  const [tplLoading, setTplLoading] = useState(false)
  const [tplFilter, setTplFilter] = useState('')
  const [cronPreview, setCronPreview] = useState([])
  const [cronError, setCronError] = useState('')
  const [submitErr, setSubmitErr] = useState('')   // 浮层内提交错误（不依赖 App 层 ErrorBar）

  // Esc 关弹窗，且只由栈顶响应（Phase 2 C-2）
  useOverlayStack(onClose)

  useEffect(() => {
    if (showTpl) {
      setTplLoading(true)
      api.listTemplates().then(d => { setTemplates(d); setTplLoading(false) }).catch(() => setTplLoading(false))
    }
  }, [showTpl])

  useEffect(() => {
    if (form.schedule_type !== 'cron' || !form.cron_expr.trim()) {
      setCronPreview([])
      setCronError('')
      return
    }
    const timer = setTimeout(() => {
      api.validateCron(form.cron_expr.trim())
        .then(d => { setCronPreview(d.next_runs || []); setCronError('') })
        .catch(e => { setCronPreview([]); setCronError(e.userMessage || e.message) })
    }, 400)
    return () => clearTimeout(timer)
  }, [form.cron_expr, form.schedule_type])

  const applyTemplate = (tpl) => {
    setForm({
      title: tpl.title || '',
      description: tpl.description || '',
      priority: tpl.priority || 0,
      est_duration_min: tpl.est_duration_min || 30,
      target_agent_type: tpl.target_agent_type || '',
      acceptance_criteria: tpl.acceptance_criteria || '',
      due_at: '',
      labels: (tpl.labels || []).join(', '),
      project: '',
      workspace: '',
      files: (tpl.files_template || []).join(', '),
      deliverables: (tpl.deliverables_template || []).join(', '),
    })
    setShowTpl(false)
  }

  const filtered = tplFilter
    ? templates.filter(t => t.title.includes(tplFilter) || t.category.includes(tplFilter) || (t.tags || []).some(x => x.includes(tplFilter)))
    : templates

  // eslint-disable-next-line complexity
  const submit = async (e) => {
    e.preventDefault()
    if (!form.title.trim()) return
    setBusy(true)
    setSubmitErr('')
    try {
      if (form.schedule_type === 'cron' && form.cron_expr.trim()) {
        const isWebhook = form.webhook_url.trim()
        await api.createScheduledJob({
          name: form.title.trim(),
          cron_expr: form.cron_expr.trim(),
          action_type: isWebhook ? 'webhook' : 'create_task',
          action_config: isWebhook
            ? {
                url: form.webhook_url.trim(),
                method: form.webhook_method,
                body: form.webhook_body.trim() ? JSON.parse(form.webhook_body.trim()) : undefined,
              }
            : {
                title: form.title.trim(),
                description: form.description.trim(),
                priority: form.priority,
                target_agent_type: form.target_agent_type.trim() || undefined,
                labels: form.labels ? form.labels.split(',').map(s => s.trim()).filter(Boolean) : [],
                project: form.project.trim(),
                workspace: form.workspace.trim(),
                stage: 'ready',
              },
        })
        onClose()
      } else {
        await onCreate({
          title: form.title.trim(),
          description: form.description.trim(),
          priority: form.priority,
          est_duration_min: Math.max(5, form.est_duration_min || 30),
          target_agent_type: form.target_agent_type.trim() || undefined,
          acceptance_criteria: form.acceptance_criteria.trim(),
          due_at: form.due_at || null,
          labels: form.labels ? form.labels.split(',').map(s => s.trim()).filter(Boolean) : [],
          project: form.project.trim(),
          workspace: form.workspace.trim(),
          files: form.files ? form.files.split(',').map(s => s.trim()).filter(Boolean) : [],
          deliverables: form.deliverables ? form.deliverables.split(',').map(s => s.trim()).filter(Boolean) : [],
        })
      }
    } catch (err) {
      // 创建失败必须显示在浮层内部：App 层的 ErrorBar 会被本浮层的遮罩盖住，
      // 用户看到的是「点了没反应」（Phase 2 C-3）。
      setSubmitErr(err?.userMessage || err?.message || '创建失败，请重试')
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className="overlay" onClick={onClose}>
      <div className="modal" role="dialog" aria-modal="true" aria-label="创建新任务" onClick={e => e.stopPropagation()}>
        <div className="modal__head">
          <h3>创建任务</h3>
          <button className="modal__close" onClick={onClose} aria-label="关闭">×</button>
        </div>

        {submitErr && (
          <p className="modal__err" role="alert">
            <span aria-hidden="true">⚠</span> {submitErr}
          </p>
        )}

        <form onSubmit={submit}>
          <div className="tpl-bar">
            <button type="button" className="btn btn--ghost btn--sm" onClick={() => setShowTpl(s => !s)}>
              📋 从模板创建
            </button>
            {form.title && (
              <span className="tpl-hint">已填写表单（手动）</span>
            )}
          </div>

          {showTpl && (
            <div className="tpl-panel">
              <input
                className="tpl-search"
                placeholder="搜索模板…"
                value={tplFilter}
                onChange={e => setTplFilter(e.target.value)}
                autoFocus
              />
              {tplLoading ? (
                <div className="tpl-loading">加载中…</div>
              ) : filtered.length === 0 ? (
                <div className="tpl-empty">暂无模板，可从任务创建</div>
              ) : (
                <ul className="tpl-list">
                  {filtered.map(t => (
                    <li key={t.id} className="tpl-item" onClick={() => applyTemplate(t)}>
                      <span className="tpl-item__title">{t.title}</span>
                      {t.category && <span className="tpl-item__cat">{t.category}</span>}
                      {t.target_agent_type && <span className="tpl-item__agent">{t.target_agent_type}</span>}
                    </li>
                  ))}
                </ul>
              )}
            </div>
          )}

          <div className="field">
            <label className="field__label">任务标题 <b>*</b></label>
            <input
              autoFocus
              value={form.title}
              onChange={e => setForm({ ...form, title: e.target.value })}
              placeholder="例如：数据清洗脚本"
            />
          </div>

          <div className="field">
            <label className="field__label">描述</label>
            <textarea
              value={form.description}
              onChange={e => setForm({ ...form, description: e.target.value })}
              placeholder="任务详细说明…"
              rows={3}
            />
          </div>

          <div className="field">
            <label className="field__label">定时任务</label>
            <div className="sched-row">
              <button type="button" className={`sched-btn ${form.schedule_type === 'once' ? 'is-on' : ''}`}
                onClick={() => setForm({ ...form, schedule_type: 'once' })}>单次</button>
              <button type="button" className={`sched-btn ${form.schedule_type === 'cron' ? 'is-on' : ''}`}
                onClick={() => setForm({ ...form, schedule_type: 'cron' })}>定时循环</button>
            </div>
          </div>

          {form.schedule_type === 'cron' && (
            <div className="sched-section">
              <div className="field">
                <label className="field__label">Cron 表达式 <b>*</b></label>
                <input
                  value={form.cron_expr}
                  onChange={e => setForm({ ...form, cron_expr: e.target.value })}
                  placeholder="分 时 日 月 周，如 0 9 * * 1-5（工作日 9 点）"
                  className={cronError ? 'field--error' : ''}
                />
                {cronError && <span className="field__err">{cronError}</span>}
                {cronPreview.length > 0 && (
                  <div className="cron-preview">
                    <span className="cron-preview__label">下次执行：</span>
                    {cronPreview.map((t, i) => (
                      <span key={i} className="cron-preview__time">
                        {parseUtc(t).toLocaleString('zh-CN', { month:'numeric', day:'numeric', hour:'2-digit', minute:'2-digit' })}
                      </span>
                    ))}
                  </div>
                )}
              </div>
              <div className="field">
                <label className="field__label">动作类型</label>
                <div className="sched-row">
                  <button type="button" className={`sched-btn ${!form.webhook_url ? 'is-on' : ''}`}
                    onClick={() => setForm({ ...form, webhook_url: '' })}>创建任务</button>
                  <button type="button" className={`sched-btn ${form.webhook_url ? 'is-on' : ''}`}
                    onClick={() => setForm({ ...form, webhook_url: form.webhook_url || 'https://' })}>Webhook</button>
                </div>
              </div>
              {form.webhook_url ? (
                <>
                  <div className="field">
                    <label className="field__label">Webhook URL</label>
                    <input value={form.webhook_url} onChange={e => setForm({ ...form, webhook_url: e.target.value })}
                      placeholder="https://example.com/hook" />
                  </div>
                  <div className="field field--row">
                    <div>
                      <label className="field__label">Method</label>
                      <select value={form.webhook_method} onChange={e => setForm({ ...form, webhook_method: e.target.value })}>
                        <option value="POST">POST</option>
                        <option value="PUT">PUT</option>
                        <option value="GET">GET</option>
                      </select>
                    </div>
                    <div style={{flex:1}}>
                      <label className="field__label">Body (JSON)</label>
                      <input value={form.webhook_body} onChange={e => setForm({ ...form, webhook_body: e.target.value })}
                        placeholder='{"event":"trigger"}' />
                    </div>
                  </div>
                </>
              ) : (
                <p className="sched-hint">定时自动创建一个「就绪」状态的任务，等待 agent 领取。</p>
              )}
            </div>
          )}

          <div className="field field--row">
            <div>
              <label className="field__label">优先级</label>
              <div className="prio">
                {PRIORITY.map(({ p, label, text }) => (
                  <button
                    key={p}
                    type="button"
                    className={form.priority === p ? 'is-on' : ''}
                    onClick={() => setForm({ ...form, priority: p })}
                    title={text}
                  >{label}</button>
                ))}
              </div>
            </div>
            <div>
              <label className="field__label">预估时长（分）</label>
              <input
                type="number"
                min={5}
                step={5}
                value={form.est_duration_min}
                onChange={e => setForm({ ...form, est_duration_min: +e.target.value })}
              />
            </div>
          </div>

          <div className="field">
            <label className="field__label">目标 Agent 类型</label>
            <input
              value={form.target_agent_type}
              onChange={e => setForm({ ...form, target_agent_type: e.target.value })}
              placeholder="留空表示任意 agent 可领取"
            />
          </div>

          <div className="field">
            <label className="field__label">验收标准</label>
            <textarea
              value={form.acceptance_criteria}
              onChange={e => setForm({ ...form, acceptance_criteria: e.target.value })}
              placeholder="完成定义 / 如何验收…"
              rows={2}
            />
          </div>

          <div className="field field--row">
            <div>
              <label className="field__label">截止时间</label>
              <input
                type="datetime-local"
                value={form.due_at}
                onChange={e => setForm({ ...form, due_at: e.target.value })}
              />
            </div>
            <div>
              <label className="field__label">项目</label>
              <input
                value={form.project}
                onChange={e => setForm({ ...form, project: e.target.value })}
                placeholder="例如：数据平台"
              />
            </div>
          </div>

          <div className="field field--row">
            <div>
              <label className="field__label">工作区路径</label>
              <input
                value={form.workspace}
                onChange={e => setForm({ ...form, workspace: e.target.value })}
                placeholder="例如：/repo/agent-dev"
              />
            </div>
            <div>
              <label className="field__label">标签</label>
              <input
                value={form.labels}
                onChange={e => setForm({ ...form, labels: e.target.value })}
                placeholder="blocked,waiting-review"
              />
            </div>
          </div>

          <div className="field">
            <label className="field__label">文件路径</label>
            <input
              value={form.files}
              onChange={e => setForm({ ...form, files: e.target.value })}
              placeholder="src/a.py,src/b.py"
            />
          </div>

          <div className="field">
            <label className="field__label">产出物</label>
            <input
              value={form.deliverables}
              onChange={e => setForm({ ...form, deliverables: e.target.value })}
              placeholder="report.md"
            />
          </div>

          <div className="modal__foot">
            <button type="button" className="btn btn--ghost" onClick={onClose}>取消</button>
            <button type="submit" className="btn btn--accent" disabled={busy}>
              {busy ? '提交中…' : '创建任务'}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

// 决策面板「待我处理」（E7 结论产品化，2026-11-04）
//
// E7 实验结论：用户不是不想决策，是没人告诉他有决策在等他。本组件把
// E7 手工清单固化成常驻入口——三个队列，每条都写明「你要做什么」：
//   A 待决策：依赖阻塞（前置取消/失败，任务卡死）+ open 决策（FR-03）
//   B 待你验收：completed + review 阶段（Run 做完等你采纳）
//   C 失败待处置：重试 / 拆小重做 / 关掉
//
// 时间分层（2026-11-04 二轮，解决「积压淹没新事 + 告警疲劳」）：
//  - 验收/失败队列按 7 天切两段：近 7 天直接展示；更早的折叠成
//    一行「历史积压 N 条」，点开才看——chip 只数近 7 天的活跃数，
//    陈旧积压归并成一个灰色「积压」chip，不再冒充今天的待办。
//  - 决策队列不切时间（决策拖 30 天也还是必须裁决的事）。
//
// 设计约束：
//  - 机器噪声恒过滤（isNoiseTask），不受看板「显示机器任务」开关影响。
//  - 折叠态只是一条 24px 的细条 + chips；不抢注意力。
//  - 任务行点开详情在详情面板处置；决策行点开裁决对话框本组件内闭环。
import { useState, useEffect, useMemo, useCallback } from 'react'
import { api } from '../api'
import { isNoiseTask } from '../noise'
import { fmtAgo } from '../constants'

const MAX_ROWS = 8
const STALE_DAYS = 7
// 依赖阻塞告警文本里的任务 id：「任务「xxx」（d0390a04）依赖阻塞…」
const TID_RE = /（([0-9a-f]{8})）/

function daysAgo(ts) {
  if (!ts) return Infinity
  const t = Date.parse(ts)
  if (Number.isNaN(t)) return Infinity
  return (Date.now() - t) / 86400000
}

// eslint-disable-next-line complexity, max-lines-per-function
export default function DecisionInbox({ allTasks, onOpenTask }) {
  const [open, setOpen] = useState(false)
  const [depAlerts, setDepAlerts] = useState([])
  const [decisions, setDecisions] = useState([])
  const [showStaleReview, setShowStaleReview] = useState(false)
  const [showStaleFailed, setShowStaleFailed] = useState(false)
  // 裁决对话框状态：当前决策 + 提交中/错误
  const [resolving, setResolving] = useState(null) // decision 对象
  const [choice, setChoice] = useState('')
  const [freeChoice, setFreeChoice] = useState('')
  const [rationale, setRationale] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [dlgError, setDlgError] = useState('')

  const loadDecisions = useCallback(() => api.listDecisions('open')
    .then(d => { if (d && Array.isArray(d.items)) setDecisions(d.items) })
    .catch(() => { /* 拉取失败不阻塞主界面 */ })
  , [])

  useEffect(() => {
    let alive = true
    const load = () => api.boardSummary()
      .then(d => { if (alive) setDepAlerts((d && d.alerts) || []) })
      .catch(() => { /* 拉取失败不阻塞主界面 */ })
    load()
    loadDecisions()
    const t = setInterval(() => { load(); loadDecisions() }, 30000)
    return () => { alive = false; clearInterval(t) }
  }, [loadDecisions])

  const biz = useMemo(() => (allTasks || []).filter(t => !isNoiseTask(t)), [allTasks])
  // B：待验收——按 7 天分层，层内最老的排前面
  const reviewSplit = useMemo(() => {
    const all = biz
      .filter(t => t.state === 'completed' && t.stage === 'review')
      .sort((a, b) => (a.created_at || '').localeCompare(b.created_at || ''))
    return {
      fresh: all.filter(t => daysAgo(t.created_at) <= STALE_DAYS),
      stale: all.filter(t => daysAgo(t.created_at) > STALE_DAYS),
    }
  }, [biz])
  // C：失败待处置——按 7 天分层，层内最新的排前面（还有救的先看到）
  const failedSplit = useMemo(() => {
    const all = biz
      .filter(t => t.state === 'failed')
      .sort((a, b) => (b.created_at || '').localeCompare(a.created_at || ''))
    return {
      fresh: all.filter(t => daysAgo(t.created_at) <= STALE_DAYS),
      stale: all.filter(t => daysAgo(t.created_at) > STALE_DAYS),
    }
  }, [biz])
  // open 决策——最老的排前面（拖得最久的先看到）
  const openDecisions = useMemo(
    () => [...decisions].sort((a, b) => (a.created_at || '').localeCompare(b.created_at || '')),
    [decisions])

  const decideCount = depAlerts.length + openDecisions.length
  const freshReview = reviewSplit.fresh.length
  const freshFailed = failedSplit.fresh.length
  const staleCount = reviewSplit.stale.length + failedSplit.stale.length
  const activeTotal = decideCount + freshReview + freshFailed
  const total = activeTotal + staleCount
  if (total === 0) return null

  const openResolve = (d) => {
    setResolving(d)
    setChoice((d.options && d.options[0] && d.options[0].label) || '')
    setFreeChoice('')
    setRationale('')
    setDlgError('')
  }

  const closeResolve = () => { if (!submitting) setResolving(null) }

  const submitResolve = async () => {
    if (!resolving) return
    const finalChoice = (freeChoice || '').trim() || (choice || '').trim()
    if (!finalChoice) { setDlgError('选一个选项或自由作答，才能提交'); return }
    setSubmitting(true)
    setDlgError('')
    try {
      await api.resolveDecision(resolving.id, { choice: finalChoice, rationale: (rationale || '').trim() })
      setResolving(null)
      await loadDecisions()
    } catch (e) {
      setDlgError(e && (e.message || e.userMessage) || '提交失败，请重试')
    } finally {
      setSubmitting(false)
    }
  }

  const Row = ({ id, title, age, hint, onClick, onKeyDown, cls, children }) => (
    <li
      className={`inbox-strip__row${cls ? ' ' + cls : ''}`}
      role={onClick ? 'button' : undefined}
      tabIndex={onClick ? 0 : undefined}
      onClick={onClick || (() => id && onOpenTask({ id }))}
      onKeyDown={onKeyDown || (e => { if ((e.key === 'Enter' || e.key === ' ') && id) { e.preventDefault(); onOpenTask({ id }) } })}
    >
      <span className="inbox-strip__row-id mono">{id || '—'}</span>
      <span className="inbox-strip__row-title">{title}</span>
      {age && <span className="inbox-strip__row-age mono">{age}</span>}
      {hint && <span className="inbox-strip__row-hint">{hint}</span>}
      {children}
    </li>
  )

  // 折叠的陈旧段：一行可点的汇总行 + 展开后的列表
  const StaleGroup = ({ label, items, show, onToggle }) => (
    items.length > 0 && (
      <div className="inbox-strip__stale">
        <button
          className="inbox-strip__stale-toggle"
          onClick={onToggle}
          aria-expanded={show}
        >
          <span className="inbox-strip__chev">{show ? '▾' : '▸'}</span>
          {label} · {items.length} 条（{show ? '收起' : '展开查看'}）
        </button>
        {show && (
          <ul className="inbox-strip__list">
            {items.slice(0, MAX_ROWS).map(t => (
              <Row key={t.id} id={t.id} title={t.title} age={fmtAgo(t.created_at)} hint="打开详情处置" />
            ))}
            {items.length > MAX_ROWS && <li className="inbox-strip__more">…另 {items.length - MAX_ROWS} 项</li>}
          </ul>
        )}
      </div>
    )
  )

  return (
    <section className={`inbox-strip${open ? ' is-open' : ''}`} aria-label="待我处理">
      <button className="inbox-strip__bar" onClick={() => setOpen(v => !v)} aria-expanded={open}>
        <span className="inbox-strip__dot" aria-hidden="true" />
        <strong className="inbox-strip__title">待我处理</strong>
        <span className="inbox-strip__chips">
          {decideCount > 0 && <span className="inbox-strip__chip is-block">决策 {decideCount}</span>}
          {freshReview > 0 && <span className="inbox-strip__chip is-review">验收 {freshReview}</span>}
          {freshFailed > 0 && <span className="inbox-strip__chip is-failed">失败 {freshFailed}</span>}
          {staleCount > 0 && <span className="inbox-strip__chip is-stale">积压 {staleCount}</span>}
        </span>
        <span className="inbox-strip__chev">{open ? '▴' : '▾'}</span>
      </button>

      {open && (
        <>
          <div className="inbox-drawer__backdrop" onClick={() => setOpen(false)} />
          <div className="inbox-strip__panel" role="dialog" aria-label="待我处理">
            <div className="inbox-drawer__head">
              <span className="inbox-strip__dot" aria-hidden="true" />
              <span className="inbox-drawer__title">待我处理</span>
              <span className="inbox-strip__chips">
                {decideCount > 0 && <span className="inbox-strip__chip is-block">决策 {decideCount}</span>}
                {freshReview > 0 && <span className="inbox-strip__chip is-review">验收 {freshReview}</span>}
                {freshFailed > 0 && <span className="inbox-strip__chip is-failed">失败 {freshFailed}</span>}
                {staleCount > 0 && <span className="inbox-strip__chip is-stale">积压 {staleCount}</span>}
              </span>
              <button className="inbox-drawer__close" onClick={() => setOpen(false)} aria-label="关闭">×</button>
            </div>
            <div className="inbox-drawer__body">
              {decideCount > 0 && (
                <div className="inbox-strip__sec">
                  <div className="inbox-strip__sec-title">
                    待决策 · {decideCount}（最老的在前；解开才动得了）
                  </div>
                  <ul className="inbox-strip__list">
                    {openDecisions.slice(0, MAX_ROWS).map(d => (
                      <Row
                        key={d.id}
                        cls="is-decision"
                        id={(d.task_id || d.id).slice(0, 8)}
                        title={d.question}
                        age={fmtAgo(d.created_at)}
                        onClick={() => openResolve(d)}
                        onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openResolve(d) } }}
                      >
                        <span className="inbox-strip__row-badge">裁决</span>
                      </Row>
                    ))}
                    {depAlerts.slice(0, MAX_ROWS).map((a, i) => {
                      const m = TID_RE.exec(a.message || '')
                      const title = (a.message || '').replace(/^任务「/, '').split('」')[0] || (a.message || '').slice(0, 60)
                      return <Row key={`dep${i}`} id={m ? m[1] : ''} title={title} hint="重开前置 / 换前置 / 砍后置" />
                    })}
                    {decideCount > MAX_ROWS && <li className="inbox-strip__more">…另 {decideCount - MAX_ROWS} 项</li>}
                  </ul>
                </div>
              )}

              {freshReview > 0 && (
                <div className="inbox-strip__sec">
                  <div className="inbox-strip__sec-title">待你验收 · {freshReview}（近 7 天，最老的在前）</div>
                  <ul className="inbox-strip__list">
                    {reviewSplit.fresh.slice(0, MAX_ROWS).map(t => (
                      <Row key={t.id} id={t.id} title={t.title} age={fmtAgo(t.created_at)} hint="打开详情验收" />
                    ))}
                    {freshReview > MAX_ROWS && <li className="inbox-strip__more">…另 {freshReview - MAX_ROWS} 项</li>}
                  </ul>
                </div>
              )}

              <StaleGroup
                label="更早的待验收"
                items={reviewSplit.stale}
                show={showStaleReview}
                onToggle={() => setShowStaleReview(v => !v)}
              />

              {freshFailed > 0 && (
                <div className="inbox-strip__sec">
                  <div className="inbox-strip__sec-title">失败待处置 · {freshFailed}（近 7 天，最新的在前）</div>
                  <ul className="inbox-strip__list">
                    {failedSplit.fresh.slice(0, MAX_ROWS).map(t => (
                      <Row key={t.id} id={t.id} title={t.title} age={fmtAgo(t.created_at)} hint="打开详情处置" />
                    ))}
                    {freshFailed > MAX_ROWS && <li className="inbox-strip__more">…另 {freshFailed - MAX_ROWS} 项</li>}
                  </ul>
                </div>
              )}

              <StaleGroup
                label="更早的失败任务"
                items={failedSplit.stale}
                show={showStaleFailed}
                onToggle={() => setShowStaleFailed(v => !v)}
              />
            </div>
          </div>
        </>
      )}

      {resolving && (
        <div className="inbox-dlg__overlay" role="presentation" onClick={e => { if (e.target === e.currentTarget) closeResolve() }}>
          <div className="inbox-dlg" role="dialog" aria-modal="true" aria-label="裁决决策">
            <div className="inbox-dlg__head">
              <strong>待你决策</strong>
              {resolving.source && <span>· 来自 {resolving.source}</span>}
              <button className="inbox-dlg__close" onClick={closeResolve} disabled={submitting} aria-label="关闭">×</button>
            </div>
            <div className="inbox-dlg__q">{resolving.question}</div>
            {resolving.context && (
              <>
                <div className="inbox-dlg__label">背景</div>
                <div className="inbox-dlg__ctx">{resolving.context}</div>
              </>
            )}
            {resolving.recommendation && (
              <div className="inbox-dlg__rec">建议：{resolving.recommendation}</div>
            )}
            {resolving.deadline && (
              <div className="inbox-dlg__label">截止：{resolving.deadline}</div>
            )}
            {(resolving.options || []).length > 0 && (
              <>
                <div className="inbox-dlg__label">选一个方案</div>
                <div className="inbox-dlg__opts">
                  {(resolving.options || []).map((o, i) => (
                    <label key={i} className={`inbox-dlg__opt${choice === o.label ? ' is-on' : ''}`}>
                      <span className="inbox-dlg__opt-row">
                        <input
                          type="radio"
                          name="dlg-choice"
                          value={o.label}
                          checked={choice === o.label}
                          onChange={() => { setChoice(o.label); setFreeChoice('') }}
                        />
                        <span className="inbox-dlg__opt-label">{o.label}</span>
                      </span>
                      {o.note && <span className="inbox-dlg__opt-note">{o.note}</span>}
                    </label>
                  ))}
                </div>
              </>
            )}
            <input
              className="inbox-dlg__free"
              placeholder="其他决定？直接写在这里（选了上方选项则忽略）"
              value={freeChoice}
              onChange={e => { setFreeChoice(e.target.value); if (e.target.value) setChoice('') }}
              maxLength={512}
            />
            <textarea
              className="inbox-dlg__why"
              placeholder="为什么这么决定？（一句话即可，留档审计，可空）"
              value={rationale}
              onChange={e => setRationale(e.target.value)}
              rows={2}
              maxLength={2048}
            />
            {dlgError && <div className="inbox-dlg__err">{dlgError}</div>}
            <div className="inbox-dlg__foot">
              <button
                className="inbox-dlg__ghost"
                onClick={async () => {
                  if (submitting) return
                  setSubmitting(true)
                  try {
                    await api.supersedeDecision(resolving.id)
                    setResolving(null)
                    await loadDecisions()
                  } catch (e) {
                    setDlgError(e && (e.message || e.userMessage) || '作废失败')
                  } finally {
                    setSubmitting(false)
                  }
                }}
                disabled={submitting}
              >作废</button>
              <button
                className="inbox-dlg__ok"
                onClick={submitResolve}
                disabled={submitting}
              >{submitting ? '提交中…' : '落裁决'}</button>
            </div>
          </div>
        </div>
      )}
    </section>
  )
}

import { useMemo, useState } from 'react'
import { prio } from '../constants'

const NODE_W = 148
const NODE_H = 46
const H_GAP = 18
const V_GAP = 36
const PAD = 16

function collectAncestors(task, byId) {
  const out = new Set()
  const stack = [...(task.depends_on || [])]
  const seen = new Set()
  while (stack.length) {
    const cur = stack.pop()
    if (seen.has(cur)) continue
    seen.add(cur)
    if (!byId[cur]) continue
    out.add(cur)
    const t = byId[cur]
    ;(t.depends_on || []).forEach(d => { if (!seen.has(d)) stack.push(d) })
  }
  return out
}

function collectDescendants(taskId, tasks, byId) {
  // reverse adjacency
  const succ = {}
  tasks.forEach(t => {
    ;(t.depends_on || []).forEach(d => {
      if (!byId[d]) return
      if (!succ[d]) succ[d] = []
      succ[d].push(t.id)
    })
  })
  const out = new Set()
  const stack = [...(succ[taskId] || [])]
  const seen = new Set()
  while (stack.length) {
    const cur = stack.pop()
    if (seen.has(cur)) continue
    seen.add(cur)
    if (!byId[cur]) continue
    out.add(cur)
    ;(succ[cur] || []).forEach(n => { if (!seen.has(n)) stack.push(n) })
  }
  return out
}

function kahnLayers(nodeIds, byId) {
  const idSet = new Set(nodeIds)
  const succ = {}
  const indeg = {}
  nodeIds.forEach(id => { succ[id] = []; indeg[id] = 0 })
  nodeIds.forEach(id => {
    const t = byId[id]
    if (!t) return
    ;(t.depends_on || []).forEach(d => {
      if (!idSet.has(d)) return
      indeg[id] += 1
      succ[d].push(id)
    })
  })
  const depth = {}
  let frontier = nodeIds.filter(id => indeg[id] === 0)
  let d = 0
  const layerMap = {}
  while (frontier.length) {
    const next = []
    frontier.forEach(id => {
      depth[id] = d
      if (!layerMap[d]) layerMap[d] = []
      layerMap[d].push(id)
      ;(succ[id] || []).forEach(ch => {
        indeg[ch] -= 1
        if (indeg[ch] === 0) next.push(ch)
      })
    })
    frontier = next
    d += 1
  }
  // nodes in cycles (indeg>0) get deepest layer+1
  const leftover = nodeIds.filter(id => depth[id] === undefined)
  if (leftover.length) {
    const maxD = Math.max(...Object.keys(layerMap).map(Number), -1)
    leftover.forEach(id => {
      depth[id] = maxD + 1
      if (!layerMap[maxD + 1]) layerMap[maxD + 1] = []
      layerMap[maxD + 1].push(id)
    })
  }
  const layers = Object.keys(layerMap).sort((a, b) => +a - +b).map(k => layerMap[k])
  return { layers, depth }
}

// eslint-disable-next-line max-lines-per-function
export default function DependencyGraph({ task, tasks, onOpen }) {
  const [hovered, setHovered] = useState(null)
  const [selected, setSelected] = useState(null)
  const activeId = hovered || selected || task.id

  const byId = useMemo(() => Object.fromEntries((tasks || []).map(t => [t.id, t])), [tasks])

  const ancestors = useMemo(() => collectAncestors(task, byId), [task, byId])
  const descendants = useMemo(() => collectDescendants(task.id, tasks || [], byId), [task, tasks, byId])

  const missing = useMemo(() => (task.depends_on || []).filter(id => !byId[id]), [task, byId])

  // detect cycle locally (simple DFS on full graph)
  const cycleInfo = useMemo(() => {
    const allIds = (tasks || []).map(t => t.id)
    const WHITE = 0, GRAY = 1, BLACK = 2
    const color = Object.fromEntries(allIds.map(id => [id, WHITE]))
    const stack = []
    let cyc = null
    const dfs = (u) => {
      color[u] = GRAY
      stack.push(u)
      const deps = (byId[u]?.depends_on || [])
      for (const v of deps) {
        if (!byId[v]) continue
        if (color[v] === GRAY) {
          const idx = stack.indexOf(v)
          cyc = [...stack.slice(idx), v]
          return true
        }
        if (color[v] === WHITE && dfs(v)) return true
      }
      stack.pop()
      color[u] = BLACK
      return false
    }
    for (const id of allIds) {
      if (color[id] === WHITE && dfs(id)) break
    }
    return cyc
  }, [tasks, byId])

  const subIds = useMemo(() => {
    const s = new Set([...ancestors, task.id, ...descendants])
    return [...s].filter(id => byId[id])
  }, [ancestors, descendants, task, byId])

  const { layers } = useMemo(() => kahnLayers(subIds, byId), [subIds, byId])

  // missing placeholders are shown as extra top layer
  const hasMissing = missing.length > 0

  // layout positions
  const positions = useMemo(() => {
    const pos = {}
    // missing nodes share a virtual top layer
    if (hasMissing) {
      missing.forEach((mid, i) => {
        pos[mid] = {
          x: PAD + i * (NODE_W + H_GAP),
          y: PAD,
          isMissing: true,
        }
      })
    }
    const yOffset = hasMissing ? (NODE_H + V_GAP + PAD) : PAD
    layers.forEach((layer, li) => {
      const w = layer.length * NODE_W + (layer.length - 1) * H_GAP
      const totalW = Math.max(w, hasMissing ? missing.length * NODE_W + (missing.length - 1) * H_GAP : 0)
      // center each layer
      const startX = PAD + Math.max(0, (totalW - w) / 2)
      const y = yOffset + li * (NODE_H + V_GAP)
      layer.forEach((id, idx) => {
        pos[id] = { x: startX + idx * (NODE_W + H_GAP), y, isMissing: false }
      })
    })
    return pos
  }, [layers, missing, hasMissing])

  const edges = useMemo(() => {
    const out = []
    subIds.forEach(id => {
      const t = byId[id]
      if (!t) return
      ;(t.depends_on || []).forEach(dep => {
        if (positions[dep] && positions[id]) {
          out.push({ from: dep, to: id })
        }
      })
    })
    // edges from missing placeholders
    missing.forEach(mid => {
      if (positions[mid] && positions[task.id]) {
        // already covered if task depends on missing
      }
    })
    return out
  }, [subIds, byId, positions, missing, task])

  const svgW = useMemo(() => {
    let mx = 0
    Object.values(positions).forEach(p => { mx = Math.max(mx, p.x + NODE_W) })
    return Math.max(mx + PAD, 360)
  }, [positions])
  const svgH = useMemo(() => {
    let my = 0
    Object.values(positions).forEach(p => { my = Math.max(my, p.y + NODE_H) })
    return Math.max(my + PAD, 120)
  }, [positions])

  const isAncestor = (id) => ancestors.has(id)
  const isDescendant = (id) => descendants.has(id)

  const connOf = (id) => {
    if (!id) return new Set()
    const s = new Set()
    const t = byId[id]
    if (t) (t.depends_on || []).forEach(d => { if (byId[d] || missing.includes(d)) s.add(d) })
    // downstream
    subIds.forEach(other => {
      if ((byId[other]?.depends_on || []).includes(id)) s.add(other)
    })
    return s
  }
  const connected = activeId ? connOf(activeId) : new Set()

  const nodeClass = (id) => {
    if (id === task.id) return 'is-current'
    if (isAncestor(id)) return 'is-ancestor'
    if (isDescendant(id)) return 'is-descendant'
    return ''
  }

  if (subIds.length === 0 && missing.length === 0) {
    return (
      <div className="dep-graph dep-graph--empty">
        <p className="detail-muted">无依赖关系</p>
      </div>
    )
  }

  return (
    <div className="dep-graph">
      {cycleInfo && (
        <div className="dep-graph__alert dep-graph__alert--cycle" role="alert">
          <b>⚠ 循环依赖</b> {cycleInfo.join(' → ')}
        </div>
      )}
      {missing.length > 0 && (
        <div className="dep-graph__alert dep-graph__alert--missing" role="alert">
          <b>⚠ 依赖缺失</b> {missing.join(', ')} — 这些任务不存在，创建/更新时将被拒绝
        </div>
      )}
      <div className="dep-graph__legend">
        <span className="dep-legend dep-legend--current">当前</span>
        <span className="dep-legend dep-legend--ancestor">前置</span>
        <span className="dep-legend dep-legend--descendant">后置</span>
        {missing.length > 0 && <span className="dep-legend dep-legend--missing">缺失</span>}
        <span className="dep-graph__hint">点击节点跳转 · 悬停高亮上下游</span>
      </div>
      <div className="dep-graph__canvas-wrap">
        <svg width={svgW} height={svgH} viewBox={`0 0 ${svgW} ${svgH}`} className="dep-graph__svg" role="img" aria-label="任务依赖图">
          <defs>
            <marker id="dep-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto">
              <path d="M 0 0 L 10 5 L 0 10 z" fill="var(--ink-faint)" />
            </marker>
            <marker id="dep-arrow-active" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto">
              <path d="M 0 0 L 10 5 L 0 10 z" fill="var(--accent)" />
            </marker>
          </defs>
          {edges.map(e => {
            const a = positions[e.from]
            const b = positions[e.to]
            if (!a || !b) return null
            const x1 = a.x + NODE_W / 2
            const y1 = a.y + NODE_H
            const x2 = b.x + NODE_W / 2
            const y2 = b.y
            const active = activeId && (e.from === activeId || e.to === activeId || connected.has(e.from) || connected.has(e.to))
            // direct line or stepped?
            const mx = (y2 - y1) > V_GAP * 1.5
            if (mx) {
              const midY = (y1 + y2) / 2
              return (
                <path
                  key={`${e.from}->${e.to}`}
                  d={`M ${x1} ${y1} C ${x1} ${midY}, ${x2} ${midY}, ${x2} ${y2}`}
                  className={`dep-edge${active ? ' is-active' : ''}`}
                  markerEnd={active ? 'url(#dep-arrow-active)' : 'url(#dep-arrow)'}
                  fill="none"
                />
              )
            }
            return (
              <line
                key={`${e.from}->${e.to}`}
                x1={x1} y1={y1} x2={x2} y2={y2}
                className={`dep-edge${active ? ' is-active' : ''}`}
                markerEnd={active ? 'url(#dep-arrow-active)' : 'url(#dep-arrow)'}
              />
            )
          })}
          {/* eslint-disable-next-line complexity */}
          {Object.entries(positions).map(([id, p]) => {
            const isMissingNode = p.isMissing
            const t = byId[id]
            const title = isMissingNode ? id : (t?.title || id)
            const pr = t ? prio(t.priority) : null
            const hl = activeId === id || connected.has(id)
            return (
              <g
                key={id}
                transform={`translate(${p.x},${p.y})`}
                className={`dep-node ${nodeClass(id)}${hl ? ' is-highlight' : ''}${isMissingNode ? ' is-missing' : ''}`}
                onMouseEnter={() => setHovered(id)}
                onMouseLeave={() => setHovered(null)}
                onClick={() => {
                  if (isMissingNode) return
                  setSelected(id)
                  if (onOpen && t) onOpen(t)
                }}
                role={isMissingNode ? 'img' : 'button'}
                tabIndex={isMissingNode ? -1 : 0}
                aria-label={isMissingNode ? `缺失任务 ${id}` : `任务 ${title}`}
                onKeyDown={e => { if (e.key === 'Enter' && !isMissingNode && onOpen && t) onOpen(t) }}
                style={{ cursor: isMissingNode ? 'not-allowed' : 'pointer' }}
              >
                <rect width={NODE_W} height={NODE_H} rx="10" ry="10" />
                <text x="10" y="18" className="dep-node__title">{title.length > 18 ? title.slice(0, 18) + '…' : title}</text>
                <text x="10" y="32" className="dep-node__meta">
                  {isMissingNode ? '缺失' : `${t?.stage || ''} · ${pr?.label || ''}`}
                </text>
                {!isMissingNode && (
                  <text x={NODE_W - 8} y="32" textAnchor="end" className="dep-node__id">{id}</text>
                )}
              </g>
            )
          })}
        </svg>
      </div>
      <div className="dep-graph__stats">
        <span>前置 {ancestors.size}</span>
        <span>后置 {descendants.size}</span>
        <span>层数 {layers.length + (hasMissing ? 1 : 0)}</span>
        <span>边 {edges.length}</span>
      </div>
    </div>
  )
}

import { useEffect, useState, useRef, useCallback, useMemo } from 'react'
import { api } from '../api'
import { docStateLabel, docStateTone, stateOfDoc, stateOfStatus, lifecycleTrack } from '../docLifecycle'
import { marked } from 'marked'
import DOMPurify from 'dompurify'
// 只按需注册文档里真实出现的语言，避免把 highlight.js 全量 190+ 语言（≈950KB）打进包里。
// 未注册的语言不会报错，只是不高亮——对代码块以外的内容无影响。
import hljs from 'highlight.js/lib/core'
import bash from 'highlight.js/lib/languages/bash'
import css from 'highlight.js/lib/languages/css'
import javascript from 'highlight.js/lib/languages/javascript'
import json from 'highlight.js/lib/languages/json'
import markdown from 'highlight.js/lib/languages/markdown'
import python from 'highlight.js/lib/languages/python'
import sql from 'highlight.js/lib/languages/sql'
import typescript from 'highlight.js/lib/languages/typescript'
import xml from 'highlight.js/lib/languages/xml'
import yaml from 'highlight.js/lib/languages/yaml'
import 'highlight.js/styles/github-dark.css'
import { useOverlayStack } from '../lib/overlayStack'

;[['bash', bash], ['css', css], ['javascript', javascript], ['json', json], ['markdown', markdown],
  ['python', python], ['sql', sql], ['typescript', typescript], ['xml', xml], ['yaml', yaml]]
  .forEach(([name, lang]) => hljs.registerLanguage(name, lang))

marked.setOptions({ gfm: true, breaks: false, headerIds: false, mangle: false })
marked.use({ renderer: { heading(token) { const level = token.depth ?? token.level; const id = 'mdh-' + Math.random().toString(36).slice(2, 8); return `<h${level} id="${id}">${token.text}</h${level}>` } } })

const fmtSize = (n) => n == null ? '' : n < 1024 ? `${n} B` : n < 1048576 ? `${(n/1024).toFixed(1)} KB` : `${(n/1048576).toFixed(1)} MB`
const sourceLabel = (s) =>
  s === 'field' ? '字段关联' :
  s === 'deliverable' ? '交付物' :
  s === 'file' ? '相关文件' :
  s === 'navigated' ? '文内跳转' : '相关'

const KIND_META = {
  spec:          { label: 'SPEC', group: 'Spec 设计文档', order: 0 },
  plan:          { label: 'PLAN', group: 'Plan 实现计划', order: 1 },
  review:        { label: '审查', group: 'Review 审查报告', order: 2 },
  requirement:   { label: '需求', group: 'Requirement 需求文档', order: 3 },
  test:          { label: '测试', group: 'Test 测试计划', order: 4 },
  architecture:  { label: '架构', group: 'Architecture 架构文档', order: 5 },
  api:           { label: 'API', group: 'API 接口文档', order: 6 },
  readme:        { label: 'README', group: 'README 说明', order: 7 },
  changelog:     { label: '变更', group: 'Changelog 变更记录', order: 8 },
  // ── 扩展文档类型（与 DOC_KINDS 保持一致，2026-09-17）──
  decision:      { label: '决策', group: 'Decision 决策记录', order: 9 },
  risk:          { label: '风险', group: 'Risk 风险登记', order: 10 },
  setup:         { label: '环境', group: 'Setup 环境搭建', order: 11 },
  runbook:       { label: '运维', group: 'Runbook 部署运维', order: 12 },
  glossary:      { label: '术语', group: 'Glossary 术语表', order: 13 },
  userguide:     { label: '手册', group: 'UserGuide 用户手册', order: 14 },
  research:      { label: '预研', group: 'Research 技术预研', order: 15 },
  retro:         { label: '复盘', group: 'Retro 复盘', order: 16 },
  milestone:     { label: '里程碑', group: 'Milestone 里程碑', order: 17 },
  'data-model':  { label: '数据', group: 'DataModel 数据模型', order: 18 },
  security:      { label: '安全', group: 'Security 安全', order: 19 },
  troubleshooting: { label: '排查', group: 'Troubleshooting 故障排查', order: 20 },
  incident:      { label: '事故', group: 'Incident 事故记录', order: 21 },
  // 非文档类的挂载项（来自 task.deliverables / task.files）
  deliverable:   { label: '交付物', group: 'Deliverables 交付物', order: 22 },
  file:          { label: '文件', group: 'Files 相关文件', order: 23 },
}
const kindMeta = (k) => KIND_META[k] || { label: k.toUpperCase(), group: k, order: 9 }

// 一级分区：链内权威文档 / 交付物 / 参考文件（后端每条带 category，缺省按 source 推断）
const CATEGORY_META = {
  doc:         { label: '链内文档', order: 0, hint: '已登记（doc_paths）的权威文档' },
  deliverable: { label: '交付物', order: 1, hint: 'task.deliverables' },
  reference:   { label: '参考文件', order: 2, hint: '扫描发现 / 相关文件，非权威' },
}
const categoryOf = (d) =>
  d.category || (d.source === 'deliverable' ? 'deliverable'
    : d.source === 'field' ? 'doc' : 'reference')

// 文档内相对资源（图片）解析：workspace 相对目录 + 引用路径
const ABS_SRC_RE = /^(?:[a-z][a-z0-9+.-]*:|\/\/|\/)/i
const decodeMaybe = (s) => { try { return decodeURIComponent(s) } catch { return s } }
const dirOf = (p) => { const s = (p || '').replace(/\\/g, '/'); return s.includes('/') ? s.slice(0, s.lastIndexOf('/')) : '' }
function joinRel(dir, src) {
  const out = (dir || '').split('/').filter(Boolean)
  for (const part of src.split('/')) {
    if (!part || part === '.') continue
    if (part === '..') out.pop()
    else out.push(part)
  }
  return out.join('/')
}

const RISK_RE = /(风险|隐患|注意|警告|⚠️?|❗|‼|危险|禁止|必须|关键点|坑|caveat|risk|warning|caution|danger|important)/i
const RISK_TAGS = ['strong', 'em', 'li', 'p', 'blockquote', 'td']

// eslint-disable-next-line complexity
function markRisks(root) {
  if (!root) return 0
  let count = 0
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT)
  const hits = []
  while (walker.nextNode()) {
    const n = walker.currentNode
    if (!n.nodeValue || !n.nodeValue.trim()) continue
    if (n.parentElement?.closest('pre, code, .md-risk')) continue
    if (RISK_RE.test(n.nodeValue)) hits.push(n)
  }
  for (const node of hits) {
    const el = node.parentElement
    if (!el || RISK_TAGS.includes(el.tagName.toLowerCase()) === false) {
      el?.classList?.add('md-risk')
      count++
      continue
    }
    el.classList.add('md-risk')
    count++
  }
  return count
}

function wordCount(text) {
  if (!text) return 0
  const ascii = (text.match(/[a-zA-Z0-9]+/g) || []).length
  const cjk = (text.match(/[\u4e00-\u9fff\u3400-\u4dbf\uf900-\ufaff]/g) || []).length
  return ascii + cjk
}

function readingTime(wc) {
  const min = Math.ceil(wc / 300)
  return min < 1 ? '< 1 分钟' : `~${min} 分钟`
}

// eslint-disable-next-line complexity, max-lines-per-function
export default function DocPanel({ task, onClose }) {
  const [docs, setDocs] = useState(null)
  const [selected, setSelected] = useState(null)
  const [html, setHtml] = useState('')
  const [rawContent, setRawContent] = useState('')
  const [loading, setLoading] = useState(false)
  const [err, setErr] = useState(null)
  const [truncated, setTruncated] = useState(false)
  const [missing, setMissing] = useState(false)
  const [query, setQuery] = useState('')
  const [activeKind, setActiveKind] = useState(null)
  const [toc, setToc] = useState([])
  const [riskCount, setRiskCount] = useState(0)
  const [findQ, setFindQ] = useState('')
  const [findHits, setFindHits] = useState(0)
  const [progress, setProgress] = useState(0)
  const [lightbox, setLightbox] = useState(null)
  // 文档生命周期总览（kind -> {state, states, allowed_next, ...}），缺失不阻塞文档浏览
  const [statusMap, setStatusMap] = useState({})
  // 状态推进：按钮落 POST /doc/{kind}/status，成功后刷新总览与清单
  const [advBusy, setAdvBusy] = useState(false)
  const [advErr, setAdvErr] = useState(null)
  const viewRef = useRef(null)
  // S-4：启用鉴权时 /raw 的图片与链接改走 blob URL，这里统一登记，组件卸载时回收。
  // 不在单次 effect cleanup 里 revoke —— 灯箱直接引用 img.src，提前回收会让放大图失效。
  const rawBlobUrls = useRef([])
  useEffect(() => () => {
    rawBlobUrls.current.forEach(u => { try { URL.revokeObjectURL(u) } catch { /* ignore */ } })
    rawBlobUrls.current = []
  }, [])

  // Esc 归属：只有栈顶浮层响应（Phase 2 D1/C-2）。
  // 图片灯箱是本面板内部的子层，先关灯箱，再关面板。
  const lightboxRef = useRef(lightbox)
  lightboxRef.current = lightbox
  useOverlayStack(() => {
    if (lightboxRef.current) { setLightbox(null); return }
    onClose()
  })

  const select = useCallback((doc) => {
    setSelected(doc); setLoading(true); setErr(null); setHtml(''); setRawContent(''); setToc([]); setFindQ(''); setFindHits(0); setProgress(0)
    const p = doc.source === 'field'
      ? api.getTaskDoc(task.id, doc.kind)
      : api.getTaskFile(task.id, doc.rel_path)
    p.then(r => {
        if (r.binary) {
          // 交付物 / 相关文件可能是二进制（PDF、图片…），不能按文本渲染
          setTruncated(false); setMissing(false); setRawContent('')
          setHtml(`<p class="docpanel__notice">二进制文件（${fmtSize(r.size ?? 0)}），无法按文本预览。</p>`)
          return
        }
        const content = r.content || ''
        setTruncated(!!r.truncated); setMissing(!!r.missing)
        setRawContent(content)
        setHtml(DOMPurify.sanitize(marked.parse(content), { ADD_ATTR: ['target'] }))
      })
      .catch(e => { setErr(e.stack || e.message); setTruncated(false); setMissing(false) })
      .finally(() => setLoading(false))
  }, [task.id])

  useEffect(() => {
    let alive = true
    api.getTaskDocuments(task.id).then(r => { if (!alive) return; const list = r.documents || []; setDocs(list); if (list.length) select(list[0]) })
      .catch(e => { if (alive) { setDocs([]); setErr(e.message) } })
    // 生命周期总览：拿 states 全序列 + 合法后继，用于状态徽标与推进条
    api.getDocStatuses(task.id)
      .then(r => { if (alive) setStatusMap(r.statuses || {}) })
      .catch(() => { if (alive) setStatusMap({}) })
    return () => { alive = false }
  }, [task.id, select])

  useEffect(() => {
    const root = viewRef.current
    if (!root || !html) return
    // S-4 通道 ④：启用鉴权时标签请求带不上 Authorization，/raw 改走 fetch + blob URL。
    // 未启用鉴权时 authed=false，下面两条分支完全保持原行为。
    const authed = api.hasToken()
    root.querySelectorAll('pre code').forEach(b => { try { hljs.highlightElement(b) } catch { /* 高亮失败不阻塞 */ } })
    root.querySelectorAll('a[href]').forEach(a => {
      a.target = '_blank'
      a.rel = 'noopener noreferrer'
      const rawHref = a.getAttribute('href') || ''
      // 相对链接指向 workspace 内文件 → 改写到 /raw，否则浏览器会请求前端静态路径 → 404
      if (rawHref && !rawHref.startsWith('#') && !rawHref.includes('?') && !ABS_SRC_RE.test(rawHref)) {
        const baseDir = selected && selected.dir != null ? selected.dir : dirOf(selected && selected.rel_path)
        const resolved = joinRel(baseDir, decodeMaybe(rawHref))
        a.href = api.rawFileUrl(task.id, resolved)
        if (authed) {
          // href 保留 /raw 作为兜底；异步换成 blob URL，点击时浏览器按原语义打开
          api.rawFileBlobUrl(task.id, resolved)
            .then(u => { rawBlobUrls.current.push(u); if (a.isConnected) a.href = u })
            .catch(() => { /* 保留 /raw 兜底 */ })
        }
        // 相对 .md 链接在面板内直接打开目标文档（拦截点击；href 保留 /raw 作为兜底）
        if (/\.(md|markdown)$/i.test(resolved)) {
          a.addEventListener('click', (e) => {
            e.preventDefault(); e.stopPropagation()
            select({
              name: resolved.split('/').pop() || resolved,
              rel_path: resolved,
              kind: 'file', source: 'navigated', dir: dirOf(resolved),
            })
          })
        }
      }
    })
    root.querySelectorAll('img').forEach(img => {
      // 相对引用的图片指向 workspace 内的原始文件，否则浏览器会请求前端静态路径 → 404
      const rawSrc = img.getAttribute('src') || ''
      if (rawSrc && !ABS_SRC_RE.test(rawSrc)) {
        const baseDir = selected && selected.dir != null ? selected.dir : dirOf(selected && selected.rel_path)
        const rel = joinRel(baseDir, decodeMaybe(rawSrc))
        if (authed) {
          api.rawFileBlobUrl(task.id, rel)
            .then(u => { rawBlobUrls.current.push(u); if (img.isConnected) img.src = u })
            .catch(() => { /* 保留原始 src 作为失败提示 */ })
        } else {
          img.src = api.rawFileUrl(task.id, rel)
        }
      }
      img.loading = 'lazy'; img.style.maxWidth = '100%'; img.style.height = 'auto'
      img.style.cursor = 'zoom-in'
      img.addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); setLightbox(img.src) })
    })
    root.querySelectorAll('table').forEach(t => { if (!t.parentElement.classList.contains('md-table-wrap')) { const w = document.createElement('div'); w.className = 'md-table-wrap'; t.before(w); w.appendChild(t) } })
    const rc = markRisks(root)
    setRiskCount(rc)
    const hs = [...root.querySelectorAll('h1,h2,h3')]
    setToc(hs.map((h, i) => { if (!h.id) h.id = 'mdh-' + i; return { id: h.id, text: h.textContent, level: Number(h.tagName[1]) } }))
  }, [html, selected, task.id, select])

  useEffect(() => {
    const root = viewRef.current
    if (!root) return
    root.querySelectorAll('mark.md-find').forEach(m => { const p = m.parentNode; p.replaceChild(document.createTextNode(m.textContent), m); p.normalize() })
    if (!findQ.trim()) { setFindHits(0); return }
    const needle = findQ.toLowerCase()
    let hits = 0
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT)
    const targets = []
    while (walker.nextNode()) {
      const n = walker.currentNode
      if (n.nodeValue && n.nodeValue.toLowerCase().includes(needle) && !n.parentElement.closest('.md-find')) targets.push(n)
    }
    for (const node of targets) {
      const text = node.nodeValue
      const lower = text.toLowerCase()
      const frag = document.createDocumentFragment()
      let idx = 0
      while (true) {
        const at = lower.indexOf(needle, idx)
        if (at === -1) break
        frag.appendChild(document.createTextNode(text.slice(idx, at)))
        const mk = document.createElement('mark')
        mk.className = 'md-find'
        mk.textContent = text.slice(at, at + findQ.length)
        frag.appendChild(mk)
        idx = at + findQ.length
        hits++
        if (hits > 500) break
      }
      frag.appendChild(document.createTextNode(text.slice(idx)))
      node.parentNode.replaceChild(frag, node)
    }
    setFindHits(hits)
  }, [findQ, html])

  useEffect(() => {
    const el = viewRef.current
    if (!el) return
    const onScroll = () => {
      const total = el.scrollHeight - el.clientHeight
      setProgress(total > 0 ? Math.min(100, Math.round(el.scrollTop / total * 100)) : 0)
    }
    el.addEventListener('scroll', onScroll, { passive: true })
    return () => el.removeEventListener('scroll', onScroll)
  }, [])

  const goTo = (id) => { const el = document.getElementById(id); if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' }) }

  const jumpFind = (dir) => {
    const marks = [...(viewRef.current?.querySelectorAll('mark.md-find') || [])]
    if (!marks.length) return
    const cur = marks.findIndex(m => m.classList.contains('is-cur'))
    const next = dir > 0 ? Math.min(cur + 1, marks.length - 1) : Math.max(cur - 1, 0)
    marks.forEach(m => m.classList.remove('is-cur'))
    marks[next]?.classList.add('is-cur')
    marks[next]?.scrollIntoView({ behavior: 'smooth', block: 'center' })
  }

  const printDoc = () => {
    const content = viewRef.current?.querySelector('.md')?.innerHTML
    if (!content) return
    const w = window.open('', '_blank')
    w.document.write(`<!DOCTYPE html><html><head><title>${selected?.name || '文档'}</title>
      <style>body{font-family:system-ui,sans-serif;max-width:800px;margin:40px auto;padding:0 20px;line-height:1.7;color:#222}
      pre{background:#f5f5f5;padding:12px;border-radius:6px;overflow-x:auto}
      code{font-size:0.9em}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ddd;padding:6px 10px}
      img{max-width:100%}blockquote{border-left:3px solid #ccc;margin:0;padding-left:16px;color:#555}
      @media print{body{margin:0}pre{white-space:pre-wrap}}</style></head><body>`)
    w.document.write(content)
    w.document.close()
    w.print()
  }

  const all = docs || []
  const q = query.trim().toLowerCase()
  const filtered = q ? all.filter(d => d.name.toLowerCase().includes(q) || d.rel_path.toLowerCase().includes(q)) : all

  // 顶部「切换类型」标签：列出清单里实际存在的文档类型（按 KIND_META 顺序）
  const kindsPresent = useMemo(() => {
    const counts = {}
    for (const d of all) counts[d.kind] = (counts[d.kind] || 0) + 1
    return Object.keys(counts)
      .sort((a, b) => kindMeta(a).order - kindMeta(b).order)
      .map(k => ({ kind: k, label: kindMeta(k).label, count: counts[k] }))
  }, [all])

  // 两级分组：category（链内文档 / 交付物 / 参考文件）→ kind（受顶部类型筛选影响）
  const catBuckets = {}
  for (const d of filtered) {
    if (activeKind && d.kind !== activeKind) continue
    const ck = categoryOf(d)
    if (!catBuckets[ck]) catBuckets[ck] = { key: ck, meta: CATEGORY_META[ck] || { label: ck, order: 9 }, kinds: {} }
    const kg = catBuckets[ck].kinds
    if (!kg[d.kind]) kg[d.kind] = { meta: kindMeta(d.kind), items: [] }
    kg[d.kind].items.push(d)
  }
  const sortedCategories = Object.values(catBuckets)
    .sort((a, b) => a.meta.order - b.meta.order)
    .map(c => {
      const kindGroups = Object.values(c.kinds).sort((a, b) => a.meta.order - b.meta.order)
      return { ...c, kindGroups, count: kindGroups.reduce((n, g) => n + g.items.length, 0) }
    })

  const catCounts = useMemo(() => {
    const c = { doc: 0, deliverable: 0, reference: 0 }
    for (const d of all) { const k = categoryOf(d); c[k] = (c[k] || 0) + 1 }
    return c
  }, [all])

  const switchKind = (kind) => {
    setActiveKind(kind)
    if (kind) {
      const first = all.find(d => d.kind === kind)
      if (first) select(first)
    }
  }

  const wc = wordCount(rawContent)

  // 选中文档的生命周期：状态以清单条目为准（回退总览），赛道全序列来自总览接口
  const selStatus = selected ? (stateOfDoc(selected) || stateOfStatus(statusMap[selected.kind])) : null
  const selTrack = selected ? lifecycleTrack((statusMap[selected.kind] || {}).states, selStatus) : []

  // 状态推进：合法后继来自总览接口 allowed_next（与后端 doc_lifecycle 同源）。
  // 只有链内文档（source=field）且该 kind 有生命周期才可推进；未登记（无落盘文件）时禁用。
  const selEntry = selected ? statusMap[selected.kind] : null
  const allowedNext = (selEntry && selEntry.allowed_next) || []
  const canAdvance = !!(selected && selected.source === 'field' && selEntry)
  const advDisabled = advBusy || canAdvance === false || selEntry?.has_doc === false

  const advanceDoc = async (target) => {
    if (!selected || advBusy) return
    setAdvBusy(true); setAdvErr(null)
    try {
      await api.setDocStatus(task.id, selected.kind, { state: target })
      const [st, docsR] = await Promise.all([
        api.getDocStatuses(task.id),
        api.getTaskDocuments(task.id),
      ])
      setStatusMap(st.statuses || {})
      const list = docsR.documents || []
      setDocs(list)
      const cur = list.find(d => d.rel_path === selected.rel_path)
      if (cur) setSelected(cur)
    } catch (e) {
      // 质量门 422 的 detail 是 {message, quality}，优先取人话 message
      const d = e && e.detail
      setAdvErr((d && d.message) || e.message)
    } finally {
      setAdvBusy(false)
    }
  }

  return (
    <div className="overlay docpanel-overlay" onClick={onClose}>
      <div className="docpanel" role="dialog" aria-modal="true" aria-label="文档浏览" onClick={e => e.stopPropagation()}>
        <header className="docpanel__head">
          <span className="docpanel__eyebrow">文档浏览</span>
          <h2 className="docpanel__title">{task.title}</h2>
          <span className="docpanel__sub docpanel__ws">{task.workspace ? task.workspace : '无工作区'}</span>
          <div className="docpanel__head-actions">
            {selected && <button className="btn btn--ghost btn--xs" onClick={printDoc} title="打印 / 导出 PDF">🖨 打印</button>}
            <button className="modal__close" onClick={onClose} aria-label="关闭">×</button>
          </div>
        </header>
        <div className="docpanel__toolbar">
          <input className="docpanel__search-input" placeholder="搜索文档名 / 路径" value={query} onChange={e => setQuery(e.target.value)} />
          <input className="docpanel__search-input docpanel__find-input" placeholder="全文查找…" value={findQ} onChange={e => setFindQ(e.target.value)}
                 onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); jumpFind(e.shiftKey ? -1 : 1) } }} />
          {findQ && <span className="docpanel__find-count">{findHits} 处命中（Enter ↴ / Shift+Enter ↰）</span>}
          <div className="docpanel__kinds">
            <button className={`docpanel__kindtab${activeKind ? '' : ' is-active'}`} onClick={() => switchKind(null)}>全部<span>{all.length}</span></button>
            {kindsPresent.map(k => (
              <button key={k.kind} className={`docpanel__kindtab${activeKind === k.kind ? ' is-active' : ''}`} onClick={() => switchKind(k.kind)}>
                {k.label}<span>{k.count}</span>
              </button>
            ))}
          </div>
          <span className="docpanel__count">{docs ? `${docs.length} 篇 · 文档 ${catCounts.doc} / 交付物 ${catCounts.deliverable} / 参考 ${catCounts.reference}` : '加载中…'}{riskCount > 0 && ` · ${riskCount} 处风险标记`}</span>
        </div>
        <div className="docpanel__body">
          <nav className="docpanel__list">
            {docs === null && <p className="detail-muted">加载中…</p>}
            {docs && docs.length === 0 && <p className="detail-muted">该任务无关联文档</p>}
            {sortedCategories.map(cat => (
              <div key={cat.key} className="docpanel__cat">
                <div className="docpanel__cat-title">
                  {cat.meta.label}<span className="docpanel__cat-count">{cat.count}</span>
                  {cat.meta.hint && <span className="docpanel__cat-hint">{cat.meta.hint}</span>}
                </div>
                {cat.kindGroups.map(g => (
                  <div key={g.meta.group} className="docpanel__group">
                    <div className="docpanel__group-title">{g.meta.group}</div>
                    {g.items.map(d => {
                      const km = kindMeta(d.kind)
                      const st = stateOfDoc(d)
                      return (
                        <button key={d.rel_path} className={`docpanel__item${selected?.rel_path === d.rel_path ? ' is-active' : ''}`} onClick={() => select(d)}>
                          <span className={`docpanel__kind docpanel__kind--${d.kind}`}>{km.label}</span>
                          <span className="docpanel__name">
                            {d.name}
                            {st && <span className={`docpanel__docstate docpanel__docstate--${docStateTone(st)}`}
                                         title={`生命周期状态：${docStateLabel(st)}`}>{docStateLabel(st)}</span>}
                          </span>
                          {d.exists === false && <span className="docpanel__missing" title="路径已登记但文件不存在">缺失</span>}
                          <span className="docpanel__src">{sourceLabel(d.source)}</span>
                          <span className="docpanel__sub mono">{d.rel_path}{d.size != null ? ` · ${fmtSize(d.size)}` : ''}</span>
                        </button>
                      )
                    })}
                  </div>
                ))}
              </div>
            ))}
            {docs && docs.length > 0 && filtered.length === 0 && <p className="detail-muted">无匹配「{query}」</p>}
          </nav>
          <aside className="docpanel__toc">
            <div className="docpanel__group-title">目录</div>
            {toc.length === 0 && <p className="detail-muted">无标题</p>}
            {toc.map(t => (
              <button key={t.id} className={`docpanel__toc-item lv${t.level}`} onClick={() => goTo(t.id)} title={t.text}>{t.text}</button>
            ))}
          </aside>
          <article className={`docpanel__view${progress > 0 ? ' has-progress' : ''}`} ref={viewRef}>
            {selected && (
              <div className="docpanel__meta-bar">
                {rawContent && <span>{wc} 字 · {readingTime(wc)}</span>}
                {selStatus && (
                  <span className={`docpanel__docstate docpanel__docstate--${docStateTone(selStatus)}`}
                        title={`生命周期状态：${docStateLabel(selStatus)}`}>
                    生命周期：{docStateLabel(selStatus)}
                  </span>
                )}
                {/* 该 kind 有生命周期就显示赛道：未落状态的文档全节点为「待推进」，
                    这样 8 类生命周期在 UI 上都可见，而不是只有已落状态的那几个。 */}
                {selTrack.length > 1 && (
                  <span className="docpanel__flow">
                    {selTrack.map((n, i) => (
                      <span key={n.state} className="docpanel__flow-node">
                        {i > 0 && <span className="docpanel__flow-arrow">→</span>}
                        <span className={`docpanel__flow-label is-${n.phase} tone-${n.tone}`}
                              title={`${n.label}${n.phase === 'current' ? '（当前）' : ''}`}>
                          {n.label}
                        </span>
                      </span>
                    ))}
                  </span>
                )}
                {canAdvance && allowedNext.length > 0 && (
                  <span className="docpanel__advance">
                    {allowedNext.map(st => (
                      <button key={st} className="btn btn--ghost btn--xs" disabled={advDisabled}
                              title={selEntry?.has_doc === false
                                ? '文档未登记（没有落盘文件），先登记路径或写入文档后再推进'
                                : `把「${kindMeta(selected.kind).label}」状态推进到「${docStateLabel(st)}」`}
                              onClick={() => advanceDoc(st)}>
                        {advBusy ? '…' : `→ ${docStateLabel(st)}`}
                      </button>
                    ))}
                  </span>
                )}
                {truncated && <span className="docpanel__meta-warn">内容已截断</span>}
              </div>
            )}
            {advErr && <div className="docpanel__notice docpanel__notice--err">推进失败：{advErr}</div>}
            {loading && <div className="docpanel__loading"><span className="spinner" /> 渲染中…</div>}
            {err && <div className="docpanel__notice docpanel__notice--err">{err}</div>}
            {!loading && !err && missing && <div className="docpanel__notice docpanel__notice--warn">文档缺失：{selected && selected.rel_path}</div>}
            {!loading && !err && !missing && truncated && <div className="docpanel__notice docpanel__notice--warn">内容已截断（超过 20 万字符），仅显示前部分。</div>}
            {!loading && !err && !missing && html && <div className="md" dangerouslySetInnerHTML={{ __html: html }} />}
            {!loading && !err && !missing && !html && docs && <p className="detail-muted">请选择左侧文档。</p>}
            {!loading && html && progress > 3 && (
              <button className="docpanel__backtop" onClick={() => viewRef.current?.scrollTo({ top: 0, behavior: 'smooth' })} aria-label="返回顶部">↑ 顶部 · {progress}%</button>
            )}
          </article>
        </div>
      </div>
      {lightbox && (
        <div className="lightbox-overlay" onClick={() => setLightbox(null)}>
          <img src={lightbox} alt="preview" className="lightbox-img" />
          <button className="lightbox-close" onClick={() => setLightbox(null)}>×</button>
        </div>
      )}
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { api } from '../api'
import { wsUrl } from '../auth'
import { STATE_META, STAGE_META, prio, compositeLabel } from '../constants'
import FlowView from './FlowView'

const STAGE_FLOW = ['brainstorming', 'design', 'planning', 'ready', 'implementing', 'review', 'done']

// eslint-disable-next-line complexity
export default function EmbedView() {
  const [tasks, setTasks] = useState([])
  const [err, setErr] = useState(null)
  const [updated, setUpdated] = useState(null)
  const [sel, setSel] = useState(null)

  const load = useCallback(() => {
    api.listTasks()
      .then(d => { setTasks(d); setErr(null); setUpdated(new Date()) })
      .catch(e => setErr('加载失败: ' + e.message))
  }, [])

  useEffect(() => {
    load()
    let s = null
    let closed = false
    const connect = () => {
      if (closed) return
      try { s = new WebSocket(wsUrl('/ws')) } catch { setTimeout(connect, 3000); return }
      s.onmessage = () => load()
      s.onclose = () => { if (!closed) setTimeout(connect, 3000) }
      s.onerror = () => { try { s.close() } catch { /* ignore */ } }
    }
    connect()
    // 轮询改 30s（任务 613bc0ca · FR-5）：本视图**已有 WebSocket**
    // （onmessage → load()），5s 轮询纯属冗余——WS 一有事件就会重新拉全量任务列表。
    const t = setInterval(load, 30000)
    return () => { closed = true; if (s) s.close(); clearInterval(t) }
  }, [load])

  const openTask = useCallback(async (t) => {
    try { setSel(await api.getTask(t.id)) } catch (e) { setErr('加载详情失败: ' + e.message) }
  }, [])

  const advance = useCallback(async (id, body) => {
    try { await api.advanceStage(id, body); load() }
    catch (e) { setErr('推进失败: ' + e.message) }
  }, [load])

  const cancel = useCallback(async (id) => {
    try { await api.advanceStage(id, { target_stage: 'cancelled' }); load() }
    catch (e) { setErr('取消失败: ' + e.message) }
  }, [load])

  const closeSel = useCallback(() => setSel(null), [])

  const ready = tasks.filter(t => t.stage === 'ready').length
  const running = tasks.filter(t => t.stage === 'implementing').length

  const stageIdx = sel ? STAGE_FLOW.indexOf(sel.stage) : -1
  const stagePct = stageIdx >= 0 ? Math.round((stageIdx + 1) / STAGE_FLOW.length * 100) : 0
  const stageMeta = sel?.stage ? STAGE_META[sel.stage] : null
  const stateMeta = sel?.state ? STATE_META[sel.state] : null
  const prioMeta = sel ? prio(sel.priority) : null
  const compLabel = sel ? compositeLabel(sel.state, sel.stage || 'ready') : null
  const accLines = sel?.acceptance_criteria
    ? sel.acceptance_criteria.split(/\n+/).map(s => s.trim()).filter(Boolean)
    : []

  return (
    <div className="embed">
      <header className="embed__bar">
        <span className="embed__title">mio-taskhub · 流程看板</span>
        <span className="embed__stats">
          <b>待执行 {ready}</b>
          <b>执行中 {running}</b>
          <b>共 {tasks.length}</b>
        </span>
        {err
          ? <span className="embed__err">▲ {err}</span>
          : updated
            ? <span className="embed__ts">更新于 {updated.toLocaleTimeString()}</span>
            : null}
      </header>

      {tasks.length === 0 && !err ? (
        <div className="embed__empty">
          <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
            <path d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2" />
            <rect x="9" y="3" width="6" height="4" rx="1" />
            <path d="M9 14h6M9 18h4" />
          </svg>
          <p>暂无任务</p>
          <span>在任务中心创建任务后，这里会实时显示进度</span>
        </div>
      ) : (
        <FlowView tasks={tasks} onOpen={openTask} onAdvance={advance} onCancel={cancel} />
      )}

      {sel && (
        <div className="embed__detail" role="dialog" aria-label="任务详情">
          <div className="embed__detail-head">
            <h3>{sel.title}</h3>
            <button className="btn btn--ghost" onClick={closeSel}>×</button>
          </div>

          <div className="embed__detail-meta">
            {stateMeta && (
              <span className={`state-chip is-${stateMeta.tone}`}>
                <i></i>{stateMeta.label}
              </span>
            )}
            {stageMeta && (
              <span className={`chip chip--${stageMeta.tone}`}>{stageMeta.label}</span>
            )}
            {prioMeta && (
              <span className={`np-row__prio np-row__prio--p${prioMeta.p}`}>{prioMeta.label} · {prioMeta.text}</span>
            )}
            {compLabel && (
              <span className={`chip chip--composite chip--${compLabel.tone}`}>{compLabel.label}</span>
            )}
            {sel.target_agent_type && <span className="chip chip--agent">执行: {sel.target_agent_type}</span>}
          </div>

          {sel.stage && (
            <div className="stage-bar embed__stage-bar" title={`${stageIdx + 1}/${STAGE_FLOW.length} · ${stagePct}% · ${stageMeta?.label || sel.stage}`}>
              <div className="stage-bar__fill" style={{ width: stagePct + '%' }} />
            </div>
          )}

          {sel.description && (
            <div className="embed__card">
              <div className="embed__card-title">📋 描述</div>
              <p className="embed__detail-desc">{sel.description}</p>
            </div>
          )}

          {sel.acceptance_criteria && (
            <div className="embed__card">
              <div className="embed__card-title">✅ 验收标准</div>
              {accLines.length > 1 ? (
                <ol className="embed__acc-list">
                  {accLines.map((line, i) => <li key={i}>{line}</li>)}
                </ol>
              ) : (
                <p className="embed__detail-desc">{sel.acceptance_criteria}</p>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  )
}

/**
 * 全局错误提示条：区分错误类型 + 重试按钮 + hint 提示。
 * - errorType: 'network' / 'api' / 'user' / 'unknown'
 * - onRetry: 重试回调（可选）
 * - error: ApiError 实例（可选，优先于 message/errorType）
 */
// eslint-disable-next-line complexity
export default function ErrorBar({ message, errorType = 'unknown', onRetry, onDismiss, error }) {
  // 从 ApiError 提取信息
  const displayMsg = error?.userMessage || message
  const hint = error?.hint
  const errorCode = error?.error_code
  const status = error?.status

  const icon = errorType === 'network' ? '⚠' : errorType === 'api' ? '⛔' : '▲'

  return (
    <div className={`errorbar errorbar--${errorType}`} role="alert">
      <span className="errorbar__icon">{icon}</span>
      <span className="errorbar__msg">
        {displayMsg}
        {status && <span className="errorbar__status mono"> ({status})</span>}
        {errorCode && <span className="errorbar__code mono"> [{errorCode}]</span>}
      </span>
      {hint && <span className="errorbar__hint">{hint}</span>}
      {onRetry && (
        <button className="errorbar__retry" onClick={onRetry} aria-label="重试">重试</button>
      )}
      {onDismiss && (
        <button className="errorbar__close" onClick={onDismiss} aria-label="关闭">×</button>
      )}
    </div>
  )
}

import { useState, useEffect, useRef, useCallback, useMemo } from 'react'
import { prio, fmtDur, agMono, agColor } from '../constants'

const STAGES = [
  { id: 'brainstorming', label: '需求理解', en: 'BRAINSTORM' },
  { id: 'design',        label: '设计',     en: 'DESIGN' },
  { id: 'planning',      label: '计划',     en: 'PLANNING' },
  { id: 'ready',         label: '待执行',   en: 'READY' },
  { id: 'implementing',  label: '执行中',   en: 'IMPL' },
  { id: 'review',        label: '审查',     en: 'REVIEW' },
  { id: 'done',          label: '完成',     en: 'DONE' },
]

const BACKTRACKS = [
  { from: 'design',       to: 'brainstorming', note: '设计时需求不明' },
  { from: 'planning',     to: 'design',        note: '计划时发现设计不足' },
  { from: 'review',       to: 'planning',      note: '审查不过需改计划' },
  { from: 'review',       to: 'design',        note: '审查不过需改设计' },
  { from: 'review',       to: 'ready',         note: '审查不过直接重做' },
]

const labelOf = (id) => STAGES.find(s => s.id === id)?.label || id
const nodeScale = (n) => Math.min(1 + n * 0.06, 1.5)

const depState = (t, tasks) => {
  const deps = t.depends_on || []
  if (!deps.length) return null
  const map = Object.fromEntries(tasks.map(x => [x.id, x]))
  const blocked = deps.some(d => {
    const p = map[d]
    return p && (p.state === 'cancelled' || p.state === 'failed')
  })
  const done = deps.every(d => {
    const p = map[d]
    return p && (p.state === 'completed' || p.stage === 'done')
  })
  return { count: deps.length, done, blocked }
}

/**
 * 依赖图视图。
 *
 * 推进（R2 C-4）：本组件**不再自带任何推进 UI / 输入**。
 * 拖拽落点与卡片上的「→ 下一阶段」按钮都只做一件事 —— 回调 `onAdvanceTask(task, targetStage)`，
 * 由 App.advanceTaskStage 决定：需要产出物的阶段弹统一的 StageAdvanceDialog 收集，
 * 不需要的直接推进并给成功 toast。原先这里的 `window.prompt` + 3 处 `alert()`
 * 是原生阻塞式弹窗（无法键盘 Esc 仲裁、无法显示在浮层内、样式与产品脱节），已全部删除；
 * 错误由 advanceStage 的返回值 / 对话框内错误条承接。
 */
// eslint-disable-next-line max-lines-per-function
export default function FlowView({ tasks, onOpen, onCancel, onAdvanceTask }) {
  const [expanded, setExpanded] = useState(STAGES[0].id)
  const [draggingId, setDraggingId] = useState(null)
  const [hoveredId, setHoveredId] = useState(null)
  const [edges, setEdges] = useState([])
  const [globalEdges, setGlobalEdges] = useState([])
  const panelRef = useRef(null)
  const canvasRef = useRef(null)

  const onCardDragStart = (e, id) => {
    setDraggingId(id)
    e.dataTransfer.setData('text/plain', id)
    e.dataTransfer.effectAllowed = 'move'
  }

  const onColumnDrop = (stageId) => {
    if (!draggingId) return
    const task = tasks.find(t => t.id === draggingId)
    setDraggingId(null)
    if (!task || task.stage === stageId) return
    if (onAdvanceTask) onAdvanceTask(task, stageId)
  }

  const flowTasks = useMemo(() => tasks.filter(t => t.stage !== 'cancelled'), [tasks])
  const byStage = useMemo(
    () => Object.fromEntries(STAGES.map(s => [s.id, flowTasks.filter(t => t.stage === s.id)])),
    [flowTasks]
  )
  const stage = STAGES.find(s => s.id === expanded)
  const activeTasks = useMemo(() => (stage ? byStage[stage.id] : []), [stage, byStage])

  const computeEdges = useCallback(() => {
    if (!panelRef.current || expanded === null) { setEdges([]); return }
    const panel = panelRef.current
    const cards = panel.querySelectorAll('.flow-card')
    const rects = {}
    cards.forEach(c => {
      const id = c.getAttribute('data-task-id')
      if (id) rects[id] = c.getBoundingClientRect()
    })
    const panelRect = panel.getBoundingClientRect()
    const out = []
    activeTasks.forEach(t => {
      ;(t.depends_on || []).forEach(depId => {
        if (!rects[t.id] || !rects[depId]) return
        const a = rects[t.id]
        const b = rects[depId]
        out.push({
          id: `${depId}->${t.id}`,
          from: depId,
          to: t.id,
          x1: b.right - panelRect.left, y1: b.top + b.height / 2 - panelRect.top,
          x2: a.left - panelRect.left, y2: a.top + a.height / 2 - panelRect.top,
        })
      })
    })
    setEdges(out)
  }, [activeTasks, expanded])

  useEffect(() => {
    computeEdges()
    if (!panelRef.current) return
    const ro = new ResizeObserver(() => requestAnimationFrame(computeEdges))
    ro.observe(panelRef.current)
    const mo = new MutationObserver(() => requestAnimationFrame(computeEdges))
    mo.observe(panelRef.current, { childList: true, subtree: true })
    return () => { ro.disconnect(); mo.disconnect() }
  }, [computeEdges, expanded])

  const computeGlobalEdges = useCallback(() => {
    if (expanded === null || !canvasRef.current) { setGlobalEdges([]); return }
    const container = canvasRef.current
    const containerRect = container.getBoundingClientRect()
    const steps = container.querySelectorAll('.flow__step')
    const colCenters = {}
    steps.forEach(st => {
      const colId = st.getAttribute('data-col')
      if (!colId) return
      const r = st.querySelector('.flow-node')?.getBoundingClientRect()
      if (r) colCenters[colId] = {
        x: r.left - containerRect.left + container.scrollLeft + r.width / 2,
        y: r.top - containerRect.top + container.scrollTop + r.height / 2,
      }
    })
    const edges = []
    flowTasks.forEach(t => {
      ;(t.depends_on || []).forEach(depId => {
        const dep = flowTasks.find(x => x.id === depId)
        if (!dep || dep.stage === t.stage) return  // 只画跨列
        const from = colCenters[dep.stage]
        const to = colCenters[t.stage]
        if (!from || !to) return
        const touchesExpanded = t.stage === expanded || dep.stage === expanded
        if (!touchesExpanded) return  // 只画与当前展开列相关的跨列边
        edges.push({ id: `${depId}->${t.id}`, from, to })
      })
    })
    setGlobalEdges(edges)
  }, [flowTasks, expanded])

  useEffect(() => {
    computeGlobalEdges()
    if (!canvasRef.current) return
    const ro = new ResizeObserver(() => requestAnimationFrame(computeGlobalEdges))
    ro.observe(canvasRef.current)
    const mo = new MutationObserver(() => requestAnimationFrame(computeGlobalEdges))
    mo.observe(canvasRef.current, { childList: true, subtree: true })
    return () => { ro.disconnect(); mo.disconnect() }
  }, [computeGlobalEdges, expanded])

  const nextStage = (stage) => {
    const i = STAGES.findIndex(s => s.id === stage)
    return i >= 0 && i < STAGES.length - 1 ? STAGES[i + 1].id : null
  }

  return (
    <div className="flow" ref={canvasRef}>
      <div className="flow__canvas">
        <svg className="flow__global-edges" aria-hidden="true">
          {globalEdges.map(e => {
            const active = hoveredId && (e.id.startsWith(hoveredId + '->') || e.id.endsWith('->' + hoveredId))
            return (
              <line key={e.id} x1={e.from.x} y1={e.from.y} x2={e.to.x} y2={e.to.y}
                    className={`flow__global-edge${active ? ' is-active' : ''}`} />
            )
          })}
        </svg>
        <div className="flow__nodes">
          {STAGES.map((s, i) => (
            <div key={s.id} data-col={s.id} className="flow__step"
              onDragOver={e => { e.preventDefault(); e.dataTransfer.dropEffect = 'move' }}
              onDragEnter={e => { e.currentTarget.classList.add('is-dragover') }}
              onDragLeave={e => { e.currentTarget.classList.remove('is-dragover') }}
              onDrop={e => { e.preventDefault(); e.currentTarget.classList.remove('is-dragover'); onColumnDrop(s.id) }}
            >
              {i > 0 && (
                <div className="flow__arrow" aria-hidden="true"><span>→</span></div>
              )}
              <button
                type="button"
                className={`flow-node${expanded === s.id ? ' is-open' : ''}`}
                style={{ '--s': nodeScale(byStage[s.id].length) }}
                onClick={() => setExpanded(expanded === s.id ? null : s.id)}
                aria-expanded={expanded === s.id}
                aria-label={`阶段 ${s.label}，${byStage[s.id].length} 个任务`}
              >
                <span className="flow-node__en">{s.en}</span>
                <span className="flow-node__label">{s.label}</span>
                <span className="flow-node__count">{byStage[s.id].length}</span>
              </button>
            </div>
          ))}
        </div>

        {stage && (
          <div className="flow__panel" ref={panelRef}>
            <div className="flow__panel-head">
              <span className="flow__panel-title">{stage.label}</span>
              <span className="flow__panel-count">{activeTasks.length} 个任务</span>
            </div>
            <svg className="flow__edges" aria-hidden="true">
              {edges.map(e => {
                const active = hoveredId && (e.from === hoveredId || e.to === hoveredId)
                return (
                  <line key={e.id} x1={e.x1} y1={e.y1} x2={e.x2} y2={e.y2}
                        className={`flow__edge${active ? ' is-active' : ''}`} />
                )
              })}
            </svg>
            {activeTasks.map(t => {
              const p = prio(t.priority)
              const ac = t.target_agent_type && agColor(t.target_agent_type)
              const next = nextStage(t.stage)
              return (
                <div key={t.id} className="flow-card" data-task-id={t.id} role="button" tabIndex={0}
                  draggable
                  onMouseEnter={() => setHoveredId(t.id)}
                  onMouseLeave={() => setHoveredId(null)}
                  onDragStart={e => onCardDragStart(e, t.id)}
                  aria-label={`任务 ${t.title}，阶段 ${stage.label}。回车查看详情`}
                  onClick={() => onOpen && onOpen(t)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault()
                      if (onOpen) onOpen(t)
                    }
                  }}>
                  <div className="flow-card__top">
                    <h4>{t.title}</h4>
                    <span className="flow-card__chev">›</span>
                  </div>
                  <div className="flow-card__meta">
                    <span className={`chip${p.p >= 3 ? ' chip--p3' : ''}${p.p === 2 ? ' chip--p2' : ''}`}>{p.label}</span>
                    {(() => {
                      const ds = depState(t, tasks)
                      if (!ds) return null
                      return (
                        <span
                          className={`chip dep-chip${ds.done ? ' dep-chip--ok' : ''}${ds.blocked ? ' dep-chip--blocked' : ''}`}
                          title={ds.blocked ? '前置任务已取消/失败，无法放行' : (ds.done ? '前置任务已完成' : '等待前置任务')}
                        >⛓ {ds.count}</span>
                      )
                    })()}
                    {t.target_agent_type && (
                      <span className="task__agent">
                        <span className="agent-mono" style={{ background: ac.bg, borderColor: ac.fg, color: ac.fg }}>{agMono(t.target_agent_type)}</span>
                      </span>
                    )}
                  </div>
                  <div className="flow-card__foot">
                    <span>{fmtDur(t.est_duration_min)}</span>
                    {next && (
                      <button className="btn btn--ghost flow-card__adv" onClick={e => { e.stopPropagation(); if (onAdvanceTask) onAdvanceTask(t, next) }}>
                        → {labelOf(next)}
                      </button>
                    )}
                    {['brainstorming','design','planning'].includes(t.stage) && (
                      <button className="btn btn--ghost btn--danger flow-card__cancel" onClick={e => { e.stopPropagation(); onCancel(t.id) }}>×</button>
                    )}
                  </div>
                </div>
              )
            })}
            {activeTasks.length === 0 && <div className="flow__empty">—</div>}
          </div>
        )}

        <div className="flow__legend">
          <span className="flow__legend-title">回溯</span>
          {BACKTRACKS.map((b, i) => (
            <span key={i} className="flow__legend-item">
              <b>{labelOf(b.from)}</b>
              <span className="flow__legend-arrow">↶</span>
              <b>{labelOf(b.to)}</b>
              <i>{b.note}</i>
            </span>
          ))}
        </div>
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { api } from '../api'

const LEVEL_META = {
  ok:        { label: '正常', tone: 'ok',    color: '#22c55e' },
  degraded:  { label: '降级', tone: 'warn',  color: '#f59e0b' },
  critical:  { label: '严重', tone: 'danger', color: '#ef4444' },
  unknown:   { label: '未知', tone: 'dim',   color: '#6b7280' },
}

// eslint-disable-next-line complexity
export default function GateStatusCard({ onForceGenerate }) {
  const [status, setStatus] = useState(null)
  const [loading, setLoading] = useState(true)
  const [err, setErr] = useState(null)
  const [forceLoading, setForceLoading] = useState(false)
  const [forceErr, setForceErr] = useState('')

  const load = async () => {
    setLoading(true)
    try {
      const res = await api.gateStatus()
      setStatus(res)
      setErr(null)
    } catch (e) {
      setErr(e.message || '加载失败')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    load()
    const t = setInterval(load, 30000) // 30s 轮询
    return () => clearInterval(t)
  }, [])

  const handleForceGenerate = async () => {
    if (!confirm('强制触发每日灵感生成（绕过闸门，留痕审计）。确定？', { title: '强制生成', danger: true })) return
    setForceLoading(true)
    setForceErr('')
    try {
      await api.forceGenerate('1271eac5', '面板手动触发')
      await load()
    } catch (e) {
      // 就近错误条（R2 附加）：这个按钮就在闸门卡里，alert 会盖住卡片本身的状态色
      setForceErr('强制生成失败：' + (e.userMessage || e.message))
    } finally {
      setForceLoading(false)
    }
  }

  if (loading && !status) {
    return (
      <div className="gate-status skeleton">
        <div className="gate-status__head-skel"></div>
        <div className="gate-status__bars-skel">
          <div className="skel-bar"></div>
          <div className="skel-bar"></div>
          <div className="skel-bar"></div>
          <div className="skel-bar"></div>
        </div>
      </div>
    )
  }

  if (err && !status) {
    return (
      <div className="gate-status gate-status--error" role="alert">
        <span className="gate-status__err">▲ 加载失败：{err}</span>
        <button className="btn btn--ghost btn--sm" onClick={load}>重试</button>
      </div>
    )
  }

  const meta = status ? (LEVEL_META[status.level] || LEVEL_META.unknown) : LEVEL_META.unknown

  return (
    <div className={`gate-status gate-status--${status?.level || 'unknown'}`} role="region" aria-label="生产闸门状态">
      <div className="gate-status__head">
        <div className="gate-status__level">
          <span className="gate-status__dot" style={{ background: meta.color }} />
          <span className="gate-status__label">生产闸门</span>
          <span className={`badge badge--${meta.tone}`}>{meta.label}</span>
        </div>
        {onForceGenerate && (
          <button className="btn btn--ghost btn--sm gate-status__force"
                  onClick={handleForceGenerate}
                  disabled={forceLoading}
                  title="强制触发生成（绕过闸门，留痕审计）">
            {forceLoading ? '生成中…' : '⚡ 强制生成'}
          </button>
        )}
      </div>

      {forceErr && (
        <div className="modal__err gate-status__err-bar" role="alert">
          <span>▲</span><span>{forceErr}</span>
          <button type="button" className="sjv__err-x" onClick={() => setForceErr('')} aria-label="关闭错误提示">×</button>
        </div>
      )}

      <div className="gate-status__metrics">
        <div className="gate-status__metric">
          <span className="gate-status__metric-label">加权总分</span>
          <span className="gate-status__metric-value mono">{status?.total_weight ?? '—'}</span>
        </div>
        <div className="gate-status__metric">
          <span className="gate-status__metric-label">INBOX</span>
          <span className="gate-status__metric-value mono">{status?.inbox_count ?? '—'}</span>
        </div>
        <div className="gate-status__metric">
          <span className="gate-status__metric-label">NEW</span>
          <span className="gate-status__metric-value mono">{status?.new_count ?? '—'}</span>
        </div>
        <div className="gate-status__metric">
          <span className="gate-status__metric-label">评审带宽</span>
          <span className="gate-status__metric-value mono">{status?.capacity_available ?? '—'} 槽</span>
        </div>
      </div>

      <div className="gate-status__thresholds">
        <span className="gate-status__thresh">软阈值 ≥ {status?.config?.soft_threshold ?? 500} → weekly</span>
        <span className="gate-status__thresh">硬阈值 ≥ {status?.config?.hard_threshold ?? 800} → 告警</span>
      </div>

      {status?.throughput_per_day != null && (
        <div className="gate-status__throughput">
          <span className="gate-status__metric-label">吞吐</span>
          <span className="gate-status__metric-value mono">{status.throughput_per_day} 评审/天</span>
        </div>
      )}
    </div>
  )
}

// 确认弹窗（复用 api.js 的 confirm 风格）
function confirm(message, { title = '确认', danger = false, okText = '确定' } = {}) {
  return new Promise((resolve) => {
    const overlay = document.createElement('div')
    overlay.className = 'confirm-overlay'
    overlay.innerHTML = `
      <div class="confirm-box${danger ? ' confirm-box--danger' : ''}">
        <h4>${title}</h4>
        <p>${message}</p>
        <div class="confirm-actions">
          <button class="btn btn--ghost" data-action="cancel">取消</button>
          <button class="btn btn--primary${danger ? ' btn--danger' : ''}" data-action="ok">${okText}</button>
        </div>
      </div>
    `
    document.body.appendChild(overlay)
    const clean = (v) => {
      overlay.remove()
      resolve(v)
    }
    overlay.querySelector('[data-action="ok"]').onclick = () => clean(true)
    overlay.querySelector('[data-action="cancel"]').onclick = () => clean(false)
    overlay.onclick = (e) => { if (e.target === overlay) clean(false) }
  })
}

// Enhanced Idea Search Component with Filters and Scoring
import { useState, useEffect, useCallback, useMemo } from 'react'
import { api } from '../api'
import { parseUtc } from '../constants'

// eslint-disable-next-line complexity, max-lines-per-function
function IdeaSearch({ ideas: initialIdeas, onSelect, onRefresh: _onRefresh }) {
  const [query, setQuery] = useState('')
  const [filters, setFilters] = useState({
    status: [],
    idea_type: '',
    category: '',
    project: '',
    labels: [],
    date_from: '',
    date_to: '',
    min_score: 0,
  })
  const [sortBy, setSortBy] = useState('updated_at')
  const [sortOrder, setSortOrder] = useState('desc')
  const [page, setPage] = useState(1)
  const [pageSize] = useState(20)
  const [results, setResults] = useState({ ideas: [], count: 0, total_pages: 1 })
  const [loading, setLoading] = useState(false)
  const [showFilters, setShowFilters] = useState(false)
  const [showScores, setShowScores] = useState(false)
  const [scores, setScores] = useState({})
  const [error, setError] = useState(null)

  // Debounced search
  const _debouncedSearch = useMemo(
    () => {
      let timeoutId
      return (fn) => {
        clearTimeout(timeoutId)
        timeoutId = setTimeout(fn, 300)
      }
    },
    []
  )

  // eslint-disable-next-line complexity
  const performSearch = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const payload = {
        query: query.trim() || null,
        status: filters.status.length ? filters.status : null,
        idea_type: filters.idea_type || null,
        category: filters.category || null,
        project: filters.project || null,
        labels: filters.labels.length ? filters.labels : null,
        date_from: filters.date_from || null,
        date_to: filters.date_to || null,
        min_score: filters.min_score || null,
        sort_by: sortBy,
        sort_order: sortOrder,
        page,
        page_size: pageSize,
      }
      const res = await api.post('/api/v1/ideas/search', payload)
      setResults(res)
      if (res.ideas?.length > 0) {
        // Fetch scores for results
        try {
          const scoresRes = await api.post('/api/v1/ideas/scores', {
            idea_ids: res.ideas.map(i => i.id),
          })
          setScores(scoresRes.scores || {})
        } catch (e) {
          console.warn('Failed to fetch scores', e)
        }
      }
    } catch (e) {
      setError(e.message || '搜索失败')
    } finally {
      setLoading(false)
    }
  }, [query, filters, sortBy, sortOrder, page, pageSize])

  useEffect(() => {
    performSearch()
  }, [performSearch])

  // Also load scores for initial ideas if no search
  useEffect(() => {
    if (!query && initialIdeas?.length) {
      const load = async () => {
        try {
          const res = await api.post('/api/v1/ideas/scores', {
            idea_ids: initialIdeas.map(i => i.id),
          })
          setScores(res.scores || {})
        } catch (e) {
          console.warn('Failed to fetch initial scores', e)
        }
      }
      load()
    }
  }, [initialIdeas])

  const toggleFilter = (key, value) => {
    setFilters(prev => {
      const arr = prev[key] || []
      const idx = arr.indexOf(value)
      if (idx >= 0) {
        return { ...prev, [key]: arr.filter(v => v !== value) }
      }
      return { ...prev, [key]: [...arr, value] }
    })
  }

  const clearFilters = () => {
    setFilters({
      status: [],
      idea_type: '',
      category: '',
      project: '',
      labels: [],
      date_from: '',
      date_to: '',
      min_score: 0,
    })
    setPage(1)
  }

  const getScoreInfo = (ideaId) => {
    return scores[ideaId] || { score: 0, factors: {}, recommendation: 'unknown' }
  }

  const getScoreColor = (score) => {
    if (score >= 8) return 'ok'
    if (score >= 4) return 'live'
    if (score >= 2) return 'warning'
    return 'dim'
  }

  return (
    <div className="idea-search">
      <div className="idea-search__header">
        <h3>🔍 想法搜索与评分</h3>
        <div className="idea-search__header-actions">
          <label className="checkbox-inline">
            <input
              type="checkbox"
              checked={showScores}
              onChange={e => setShowScores(e.target.checked)}
            />
            显示优先级评分
          </label>
          <label className="checkbox-inline">
            <input
              type="checkbox"
              checked={showFilters}
              onChange={e => setShowFilters(e.target.checked)}
            />
            高级筛选
          </label>
        </div>

        {/* Search Bar */}
        <div className="idea-search__bar">
          <input
            type="text"
            className="inp inp--lg"
            placeholder="搜索标题、描述... (回车搜索)"
            value={query}
            onChange={e => setQuery(e.target.value)}
            onKeyDown={e => { if (e.key === 'Enter') performSearch() }}
          />
          <button className="btn btn--primary" onClick={performSearch} disabled={loading}>
            {loading ? '搜索中…' : '搜索'}
          </button>
          {filters.status.length || filters.idea_type || filters.labels.length || filters.min_score > 0 ? (
            <button className="btn btn--ghost" onClick={clearFilters}>清除筛选</button>
          ) : null}
        </div>

        {/* Advanced Filters */}
        {showFilters && (
          <div className="idea-search__filters">
            <div className="filter-row">
              <div className="filter-group">
                <label>状态</label>
                <div className="filter-chips">
                  {['new', 'fermenting', 'formed', 'broken_down', 'archived', 'cancelled'].map(s => (
                    <button
                      key={s}
                      className={`filter-chip${filters.status.includes(s) ? ' is-on' : ''}`}
                      onClick={() => toggleFilter('status', s)}
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>

              <div className="filter-group">
                <label>类型</label>
                <select className="inp" value={filters.idea_type} onChange={e => setFilters(p => ({ ...p, idea_type: e.target.value }))}>
                  <option value="">全部</option>
                  <option value="idea">想法</option>
                  <option value="adr">ADR</option>
                </select>
              </div>

              <div className="filter-group">
                <label>项目</label>
                <input
                  className="inp"
                  placeholder="项目名"
                  value={filters.project}
                  onChange={e => setFilters(p => ({ ...p, project: e.target.value }))}
                />
              </div>

              <div className="filter-group">
                <label>标签</label>
                <input
                  className="inp"
                  placeholder="标签 (逗号分隔)"
                  value={filters.labels.join(', ')}
                  onChange={e => setFilters(p => ({ ...p, labels: e.target.value.split(',').map(s => s.trim()).filter(Boolean) }))}
                />
              </div>

              <div className="filter-group">
                <label>最低评分</label>
                <input
                  type="number"
                  className="inp"
                  step="0.1"
                  min="0"
                  max="20"
                  value={filters.min_score}
                  onChange={e => setFilters(p => ({ ...p, min_score: parseFloat(e.target.value) || 0 }))}
                />
              </div>

              <div className="filter-group">
                <label>日期范围</label>
                <div className="filter-date-range">
                  <input
                    type="date"
                    className="inp"
                    value={filters.date_from}
                    onChange={e => setFilters(p => ({ ...p, date_from: e.target.value }))}
                    placeholder="开始"
                  />
                  <span>至</span>
                  <input
                    type="date"
                    className="inp"
                    value={filters.date_to}
                    onChange={e => setFilters(p => ({ ...p, date_to: e.target.value }))}
                    placeholder="结束"
                  />
                </div>
              </div>

              <div className="filter-group">
                <label>排序</label>
                <div className="filter-sort">
                  <select className="inp inp--sm" value={sortBy} onChange={e => setSortBy(e.target.value)}>
                    <option value="updated_at">更新时间</option>
                    <option value="created_at">创建时间</option>
                    <option value="title">标题</option>
                    <option value="status">状态</option>
                  </select>
                  <select className="inp inp--sm" value={sortOrder} onChange={e => setSortOrder(e.target.value)}>
                    <option value="desc">降序</option>
                    <option value="asc">升序</option>
                  </select>
                </div>
              </div>
            </div>
          </div>
        )}

        {error && <div className="errorbar" role="alert"><span>▲</span><span>{error}</span><button onClick={() => setError(null)}>×</button></div>}

        {/* Results */}
        <div className="idea-search__results">
          {loading && <div className="search-loading">搜索中…</div>}

          {!loading && (!results.ideas || results.ideas.length === 0) && (
            <div className="search-empty">
              没有找到匹配的想法。尝试调整筛选条件或搜索关键词。
            </div>
          )}

          <div className="idea-search__list">
            {/* eslint-disable-next-line complexity */}
            {(results.ideas || []).map(idea => {
              const scoreInfo = getScoreInfo(idea.id)
              return (
                <div key={idea.id} className={`idea-search__item${onSelect ? ' clickable' : ''}`} onClick={() => onSelect?.(idea)}>
                  <div className="idea-search__item-main">
                    <div className="idea-search__item-title">
                      <span className={`badge badge--${(idea.idea_type === 'adr' ? { proposed: 'live', accepted: 'ok', rejected: 'dim', deprecated: 'dim', superseded: 'dim' }[idea.adr_status] || 'live' : { new: 'dim', fermenting: 'live', formed: 'ok', broken_down: 'ok', archived: 'dim', cancelled: 'danger' }[idea.status] || 'dim')}`}>
                        {idea.idea_type === 'adr' ? (idea.adr_status === 'proposed' ? 'ADR提议' : idea.adr_status === 'accepted' ? 'ADR接受' : idea.adr_status === 'rejected' ? 'ADR拒绝' : idea.adr_status === 'deprecated' ? 'ADR废弃' : 'ADR取代') : ({ new: '记录中', fermenting: '发酵中', formed: '已成形', broken_down: '已拆解', archived: '已归档', cancelled: '已取消' }[idea.status] || idea.status)}
                      </span>
                      <span className="idea-search__item-title-text">{idea.title}</span>
                      {showScores && scoreInfo.score > 0 && (
                        <span className={`score-badge score-badge--${getScoreColor(scoreInfo.score)}`}>
                          {scoreInfo.score.toFixed(1)}
                        </span>
                      )}
                    </div>
                    <div className="idea-search__item-meta">
                      {idea.project && <span className="tag tag--project">{idea.project}</span>}
                      {idea.labels?.map(l => <span key={l} className="tag">{l}</span>)}
                      <span className="mono">{parseUtc(idea.updated_at).toLocaleDateString()}</span>
                    </div>
                    {showScores && scoreInfo.factors && (
                      <div className="score-breakdown">
                        <span className="score-factor">触达: {scoreInfo.factors.reach}</span>
                        <span className="score-factor">影响: {scoreInfo.factors.impact}</span>
                        <span className="score-factor">置信: {scoreInfo.factors.confidence}</span>
                        <span className="score-factor">工作量: {scoreInfo.factors.effort}</span>
                        <span className={`score-recommendation score-recommendation--${scoreInfo.recommendation}`}>
                          {scoreInfo.recommendation}
                        </span>
                      </div>
                    )}
                  </div>
                </div>
              )
            })}
          </div>

          {/* Pagination */}
          {results.total_pages > 1 && (
            <div className="search-pagination">
              <button className="btn btn--ghost btn--sm" onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page <= 1}>
                上一页
              </button>
              <span className="pagination-info">
                第 {page} / {results.total_pages} 页，共 {results.count} 条
              </span>
              <button className="btn btn--ghost btn--sm" onClick={() => setPage(p => Math.min(results.total_pages, p + 1))} disabled={page >= results.total_pages}>
                下一页
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

