              </>
            ) : (
              <div className="cockpit-empty">Mio 暂无 active 假设（或 Mio 不可用——稍后重试）</div>
            )}
            <div className="modal__foot">
              <button className="btn btn--ghost" disabled={hypImport.saving} onClick={() => setHypImport(null)}>
                取消
              </button>
              <button className="btn btn--primary" disabled={hypImport.saving || !hypImport.selected.length}
                      onClick={doImportHyp}>
                {hypImport.saving ? '导入中…' : `导入 ${hypImport.selected.length} 条`}
              </button>
            </div>
          </div>
</div>
      )} 
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { api } from '../api'
import { fmtAgo } from '../constants'
import { confirm } from '../confirm'

const STATUS_META = {
  inbox:        { label: '收集箱', tone: 'dim' },
  new:          { label: '记录中', tone: 'dim' },
  fermenting:   { label: '发酵中', tone: 'live' },
  formed:       { label: '已成形', tone: 'ok' },
  broken_down:  { label: '已拆解', tone: 'ok' },
  archived:     { label: '已归档', tone: 'dim' },
  cancelled:    { label: '已取消', tone: 'danger' },
}

// eslint-disable-next-line complexity
export default function InboxView({ onClose }) {
  const [items, setItems] = useState([])
  const [loading, setLoading] = useState(true)
  const [err, setErr] = useState(null)
  const [page, setPage] = useState(0)
  const [pageSize] = useState(50)
  const [total, setTotal] = useState(0)
  const [actioning, setActioning] = useState({})
  const [selected, setSelected] = useState(new Set())

  const load = useCallback(async () => {
    setLoading(true)
    try {
      const res = await api.listInbox({ offset: page * pageSize, limit: pageSize })
      setItems(res.ideas || [])
      setTotal(res.total || 0)
      setErr(null)
    } catch (e) {
      setErr(e.message || '加载失败')
    } finally {
      setLoading(false)
    }
  }, [page, pageSize])

  useEffect(() => { load() }, [load])

  const doAction = async (action) => {
    const ids = selected.size ? Array.from(selected) : (items.map(i => i.id))
    if (!ids.length) return
    const word = action === 'promote' ? '晋升到 NEW' : action === 'archive' ? '归档' : '暂留 INBOX'
    if (!confirm(`对 ${ids.length} 条想法执行「${word}」？`, { title: '批量初筛' })) return

    setActioning(prev => ({ ...prev, [action]: true }))
    try {
      if (selected.size) {
        await api.batchTriage(ids, action)
      } else {
        for (const id of ids) {
          await api.triageIdea(id, action)
        }
      }
      setSelected(new Set())
      await load()
    } catch (e) {
      setErr(e.message)
    } finally {
      setActioning(prev => ({ ...prev, [action]: false }))
    }
  }

  const toggleSel = (id) => setSelected(s => {
    const ns = new Set(s)
    ns.has(id) ? ns.delete(id) : ns.add(id)
    return ns
  })
  const toggleAll = () => setSelected(s => s.size === items.length ? new Set() : new Set(items.map(i => i.id)))

  if (loading && !items.length) {
    return (
      <div className="inbox-view skeleton">
        <div className="inbox-view__head-skel"></div>
        <div className="inbox-view__list-skel">
          {[...Array(5)].map((_, i) => <div key={i} className="inbox-row-skel" />)}
        </div>
      </div>
    )
  }

  return (
    <div className="inbox-view">
      {err && <div className="errorbar" role="alert"><span>▲</span><span>{err}</span><button onClick={() => setErr(null)} aria-label="关闭">×</button></div>}

      <div className="inbox-view__head">
        <h2 className="inbox-view__title">收集箱 INBOX</h2>
        <span className="inbox-view__count">{total} 条</span>
        {onClose && <button className="btn btn--ghost btn--sm" onClick={onClose}>返回想法</button>}
      </div>

      {items.length === 0 && !loading && (
        <div className="inbox-view__empty">
          收集箱为空 —— 新生成的想法会自动落入这里，经初筛后晋升到 NEW。
        </div>
      )}

      <div className="inbox-view__toolbar">
        <div className="inbox-view__sel">
          {selected.size > 0 && (
            <span className="inbox-view__sel-count">{selected.size} / {items.length} 已选</span>
          )}
          <button className="btn btn--ghost btn--sm" onClick={toggleAll}>
            {selected.size === items.length && items.length ? '取消全选' : '全选'}
          </button>
        </div>
        <div className="inbox-view__actions">
          <button className="btn btn--primary" onClick={() => doAction('promote')} disabled={actioning.promote}>
            {actioning.promote ? '晋升中…' : '⬆ 晋升到 NEW'}
          </button>
          <button className="btn btn--ghost" onClick={() => doAction('archive')} disabled={actioning.archive}>
            {actioning.archive ? '归档中…' : '📦 归档'}
          </button>
          <button className="btn btn--ghost" onClick={() => doAction('defer')} disabled={actioning.defer}>
            {actioning.defer ? '暂留中…' : '⏸ 暂留 INBOX'}
          </button>
        </div>
      </div>

      <div className="inbox-view__list" role="list">
        {items.map(item => {
          const meta = STATUS_META[item.status] || STATUS_META.inbox
          return (
            <article key={item.id} className={`inbox-row${selected.has(item.id) ? ' is-selected' : ''}`} role="listitem">
              <label className="inbox-row__chk">
                <input type="checkbox" checked={selected.has(item.id)} onChange={() => toggleSel(item.id)} />
                <span className="inbox-row__chk-box" />
              </label>
              <div className="inbox-row__main" onClick={() => toggleSel(item.id)}>
                <div className="inbox-row__title-row">
                  <h4 className="inbox-row__title">{item.title}</h4>
                  <span className={`badge badge--${meta.tone}`}>{meta.label}</span>
                </div>
                {item.description && <p className="inbox-row__desc">{item.description.slice(0, 200)}{item.description.length > 200 ? '…' : ''}</p>}
                <div className="inbox-row__meta mono">
                  <span>ID: {item.id}</span>
                  <span>{fmtAgo(item.created_at)}</span>
                  {item.novelty != null && <span>N{item.novelty} F{item.feasibility} I{item.impact}</span>}
                </div>
              </div>
              <div className="inbox-row__actions">
                <button className="btn btn--ghost btn--sm" onClick={e => { e.stopPropagation(); api.triageIdea(item.id, 'promote').then(load).catch(setErr) }} disabled={actioning.promote} title="晋升到 NEW">⬆ 晋升</button>
                <button className="btn btn--ghost btn--sm" onClick={e => { e.stopPropagation(); api.triageIdea(item.id, 'archive').then(load).catch(setErr) }} disabled={actioning.archive} title="归档">📦 归档</button>
                <button className="btn btn--ghost btn--sm" onClick={e => { e.stopPropagation(); api.triageIdea(item.id, 'defer').then(load).catch(setErr) }} disabled={actioning.defer} title="暂留 INBOX">⏸ 暂留</button>
              </div>
            </article>
          )
        })}
      </div>

      {total > pageSize && (
        <div className="inbox-view__pager">
          <button className="btn btn--ghost btn--sm" onClick={() => setPage(p => Math.max(0, p - 1))} disabled={page === 0}>上一页</button>
          <span className="inbox-view__page-info">第 {page + 1} 页 / 共 {Math.ceil(total / pageSize)} 页</span>
          <button className="btn btn--ghost btn--sm" onClick={() => setPage(p => Math.min(Math.ceil(total / pageSize) - 1, p + 1))} disabled={page >= Math.ceil(total / pageSize) - 1}>下一页</button>
        </div>
      )}
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { api } from '../api'

/** 素材面板 v2 · 日刊流（task 164e9081，2026-10-12 设计稿确认）。
 *
 * 主用途=日常巡检产出：按日期分节（最新在前），每天一节回答
 * 「今天产出了什么」——选题行（污染 token 前端过滤并标注）、洞察卡
 * （默认折叠，点开读 sections 全文；空产出只给红标行不渲染空卡）、
 * 来源计数行 + 折叠原始素材抽屉（消防栓不铺开）。
 * 价值发现实验收进页底折叠区，顶栏按钮直达，主视图不再见表单。
 * 数据来自 /mio/material-panel（后端 task 164e9081 增量 sections 全文，
 * preview/classification_note 等旧字段保留兼容）。
 */

const pad = (n) => String(n).padStart(2, '0')
const dt = (iso) => iso ? String(iso).replace('T', ' ').slice(0, 16) : '—'
/** 本地时区的日期（YYYY-MM-DD）：选题/洞察按本地日归组，与 observations 的日期口径一致。 */
const localDay = (iso) => {
  if (!iso) return null
  const d = new Date(iso)
  if (Number.isNaN(d.getTime())) return String(iso).slice(0, 10)
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}
const weekdayOf = (day) => {
  const d = new Date(`${day}T00:00:00`)
  return Number.isNaN(d.getTime()) ? '' : d.toLocaleDateString('zh-CN', { weekday: 'short' })
}

/** 选题污染 token 过滤（前端口径，已知问题：选题池被标题前缀 token 污染）。 */
const isJunkTopic = (t) => {
  const s = String(t ?? '').trim()
  if (!s) return true
  if (/^(show hn|ask hn|hn)\b/i.test(s)) return true          // Show HN: / HN: 前缀
  if (s.startsWith('【') && s.endsWith('】')) return true       // 【GitHub】类标题前缀
  if (/[:：]$/.test(s)) return true                            // 冒号结尾 token
  if (s.length <= 3) return true                               // 过短碎片
  return false
}
const splitTopics = (topics) => {
  const valid = [], junk = []
  for (const t of topics || []) (isJunkTopic(t.topic) ? junk : valid).push(t)
  return { valid, junk }
}

const DEFAULT_ISSUES = `- mio-taskhub 文档链门控在 UI 无法操作（DocPanel 只读、422 detail 被裸 JSON.stringify）
- observer 洞察的输入抽样窗口偏娱乐源，github-trending 抓取标题带 HTML 垃圾
- observer 的选题池被标题前缀 token 污染（【GitHub】/Show HN: 被当成语义主题）
- 每日创意 job 已暂停：产出全是「缺失/空集」变体，价值提取机制失败
- mio-taskhub 抢单模式（grab mode）A 批 9 项设计完成，代码未实施
- hub 前端 1.4MB 单 chunk 未做代码分割`

// eslint-disable-next-line complexity
function ValueDiscoverySection({ obsDates }) {
  const [date, setDate] = useState(obsDates[0] || '')
  const [issues, setIssues] = useState(DEFAULT_ISSUES)
  const [label, setLabel] = useState('')
  const [running, setRunning] = useState(false)
  const [last, setLast] = useState(null)
  const [err, setErr] = useState(null)
  const [history, setHistory] = useState(null)

  const loadHistory = () => api.valueDiscoveryList().then(setHistory).catch(e => setErr(e?.message || String(e)))
  useEffect(() => { loadHistory() }, [])

  async function run() {
    if (!date) return
    setRunning(true); setErr(null)
    try {
      const result = await api.valueDiscoveryRun(date, issues.split('\n').map(s => s.trim()).filter(Boolean), label || null)
      setLast(result)
      await loadHistory()
    } catch (e) {
      setErr(e?.message || String(e))
    } finally {
      setRunning(false)
    }
  }

  const p = v => v == null ? '—' : `${(v * 100).toFixed(0)}%`
  const s = history?.stats

  return (
    <div>
      <p className="detail-muted" style={{ fontSize: 12, margin: '4px 0 8px' }}>
        人工触发：素材（GitHub Trending + Hacker News 原文）+ 内部问题 → LLM 价值评估，每个机会必须引用素材证据；
        <b>允许 0 个结果</b>，结果只入实验存档（MIO_HOME/value-discovery/）。
      </p>
      <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap', marginBottom: 6 }}>
        <select value={date} onChange={e => setDate(e.target.value)} style={{ fontSize: 13 }}>
          {obsDates.map(d => <option key={d} value={d}>{d}</option>)}
        </select>
        <input value={label} onChange={e => setLabel(e.target.value)} placeholder="批次标签（可选）"
               style={{ fontSize: 13, width: 140 }} />
        <button onClick={run} disabled={running || !date} style={{ fontSize: 13, padding: '4px 12px' }}>
          {running ? '评估中…（约 30-60s）' : '跑价值评估（调 LLM）'}
        </button>
      </div>
      <textarea value={issues} onChange={e => setIssues(e.target.value)} rows={6}
                style={{ width: '100%', fontSize: 12, fontFamily: 'inherit' }} />
      {err && <p style={{ color: '#c62828', fontSize: 12 }}>失败（显式透传，不伪装）：{err}</p>}
      {last && (
        <div style={{ border: '1px solid var(--border, #ddd)', borderRadius: 8, padding: 10, marginTop: 8 }}>
          <b style={{ fontSize: 13 }}>{last.date}{last.label ? ` · ${last.label}` : ''}</b>
          <span className="detail-muted" style={{ fontSize: 12 }}> {last.opportunities.length} 个机会 · {last.duration_s}s</span>
          {last.opportunities.length === 0 && (
            <p style={{ fontSize: 12 }}>本轮 0 个机会（合法结果）。verdict：{last.verdict}</p>
          )}
          {last.opportunities.map((o, i) => (
            <div key={i} style={{ borderTop: '1px solid var(--border, #eee)', paddingTop: 6, marginTop: 6 }}>
              <b style={{ fontSize: 13 }}>{i + 1}. {o.title}</b>
              <span style={{ fontSize: 11, marginLeft: 6, padding: '1px 6px', borderRadius: 8,
                             background: o.origin === 'external' ? '#e8f5e9' : '#fff3e0' }}>
                {o.origin === 'external' ? '外部素材触发' : '内部问题触发'}
              </span>
              <div style={{ fontSize: 12, marginTop: 4 }}><b>证据：</b>{(o.evidence || []).join('；')}</div>
              <div style={{ fontSize: 12 }}><b>发现：</b>{o.what}</div>
              <div style={{ fontSize: 12 }}><b>内部关联：</b>{o.internal_link}</div>
              <div style={{ fontSize: 12 }}><b>为何现在：</b>{o.why_now}</div>
              <div style={{ fontSize: 12 }}><b>一周实验：</b>{o.one_week_experiment}</div>
            </div>
          ))}
          {last.opportunities.length > 0 && <p style={{ fontSize: 12, marginTop: 6 }}><b>verdict：</b>{last.verdict}</p>}
        </div>
      )}
      {history && history.runs.length > 0 && (
        <table style={{ borderCollapse: 'collapse', marginTop: 10 }}>
          <thead><tr>
            <th style={th}>批次</th><th style={th}>日期</th><th style={th}>机会数</th><th style={th}>外部触发占比</th>
          </tr></thead>
          <tbody>
            {history.runs.map(r => (
              <tr key={r.id}>
                <td style={td}>{r.label || r.id}</td>
                <td style={td}>{r.date}</td>
                <td style={td}>{(r.opportunities || []).length}</td>
                <td style={td}>{
                  (() => { const ops = r.opportunities || []
                    return ops.length ? `${ops.filter(o => o.origin === 'external').length}/${ops.length}` : '—' })()
                }</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
      {s && s.batches > 0 && (
        <p className="detail-muted" style={{ fontSize: 12, marginTop: 6 }}>
          累计 {s.batches} 批 / {s.opportunities_total} 个机会 · 零机会批次 {s.zero_batches} ·
          证据覆盖 {p(s.evidence_coverage)} · 内部关联 {p(s.internal_relevance)} · 可行动 {p(s.actionability)}（人工接受率需逐批人工判定）
        </p>
      )}
    </div>
  )
}

/** 洞察卡：正常=可折叠全文卡；LLM 失败=一行红标（不渲染空卡）。 */
function SupportBadge({ insight }) {
  const s = insight.topic_support
  if (s == null) return null
  if (s === 0) {
    return (
      <span title="近 3 日素材中没有任何条目提到本选题，洞察内容多为「未找到相关内容」"
            style={{ fontSize: 11, color: '#c62828', fontWeight: 600, border: '1px solid #c62828',
                     borderRadius: 4, padding: '0 5px', whiteSpace: 'nowrap' }}>
        选题无素材支撑
      </span>
    )
  }
  if (s <= 2) {
    return (
      <span title="近 3 日素材中仅有少量条目提及本选题，洞察依据偏弱"
            style={{ fontSize: 11, color: '#b26a00', border: '1px solid #b26a00',
                     borderRadius: 4, padding: '0 5px', whiteSpace: 'nowrap' }}>
        支撑弱·{s} 条
      </span>
    )
  }
  if (insight.topic_cited === false && !insight.llm_failed) {
    return (
      <span title="近 3 日素材中有较多条目提及本选题，但洞察正文没有引用任何素材——research 阶段疑似漏检"
            style={{ fontSize: 11, color: '#c62828', fontWeight: 600, border: '1px solid #c62828',
                     borderRadius: 4, padding: '0 5px', whiteSpace: 'nowrap' }}>
        有素材但洞察未引用
      </span>
    )
  }
  return null
}

function InsightCard({ insight }) {
  const [open, setOpen] = useState(false)
  const secs = (insight.sections || []).filter(s => s && (s.title || s.content))
  const time = dt(insight.generatedAt)

  if (insight.llm_failed || secs.length === 0) {
    return (
      <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, padding: '4px 0',
                    borderBottom: '1px solid var(--border, #eee)' }}>
        <span style={{ fontSize: 12, color: '#c62828', fontWeight: 600 }}>LLM 失败（空产出）</span>
        <b style={{ fontSize: 13 }}>{insight.topic || '（无主题）'}</b>
        <SupportBadge insight={insight} />
        <span className="detail-muted" style={{ fontSize: 11, marginLeft: 'auto' }}>{time}</span>
      </div>
    )
  }
  return (
    <div style={{ border: '1px solid var(--border, #ddd)', borderRadius: 8, marginTop: 6, background: 'var(--bg, #fff)' }}>
      <button onClick={() => setOpen(o => !o)}
              style={{ display: 'flex', alignItems: 'baseline', gap: 8, width: '100%', textAlign: 'left',
                       background: 'none', border: 'none', cursor: 'pointer', padding: '8px 10px', fontSize: 13 }}>
        <span className="detail-muted">{open ? '▾' : '▸'}</span>
        <b>{insight.topic || '（无主题）'}</b>
        <SupportBadge insight={insight} />
        <span className="detail-muted" style={{ fontSize: 11, marginLeft: 'auto' }}>{time}</span>
      </button>
      {open && (
        <div style={{ padding: '0 12px 10px' }}>
          {secs.map((s, i) => (
            <div key={i} style={{ marginTop: 8 }}>
              <div style={{ fontSize: 13, fontWeight: 600 }}>{s.title}</div>
              <div style={{ fontSize: 12, whiteSpace: 'pre-wrap', lineHeight: 1.7 }}>{s.content}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

/** 单日素材抽屉：来源计数 + 每源前 3 条标题（折叠，默认不铺开）。 */
function ObservationsDrawer({ obs }) {
  const [open, setOpen] = useState(false)
  if (!obs) return <div className="detail-muted" style={{ fontSize: 12, marginTop: 6 }}>今日无原始抓取</div>
  const counts = (obs.sources || []).map(s => `${s.source} ${s.count}`).join(' · ')
  return (
    <div style={{ marginTop: 6 }}>
      <div style={{ display: 'flex', alignItems: 'baseline', gap: 10 }}>
        <span className="detail-muted" style={{ fontSize: 12 }}>来源：{counts || '—'}</span>
        <button onClick={() => setOpen(o => !o)}
                style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 0,
                         fontSize: 12, color: 'var(--link, #1976d2)' }}>
          {open ? '收起原始素材 ▴' : `原始素材 ${obs.total} 条 ▾`}
        </button>
      </div>
      {open && (
        <table style={{ borderCollapse: 'collapse', marginTop: 6 }}>
          <thead><tr><th style={th}>来源</th><th style={th}>条数</th><th style={th}>样本标题（前 3 条）</th></tr></thead>
          <tbody>
            {(obs.sources || []).map(s => (
              <tr key={s.source}>
                <td style={td}>{s.source}</td>
                <td style={td}>{s.count}</td>
                <td style={td}>{(s.samples || []).map((t, i) => <div key={i}>{t}</div>)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  )
}

/** 一天一节：选题行 + 洞察卡 + 来源抽屉。 */
function DaySection({ day }) {
  const { valid, junk } = splitTopics(day.topics)
  return (
    <section style={{ border: '1px solid var(--border, #ddd)', borderRadius: 10,
                      padding: '12px 14px', marginTop: 14 }}>
      <div style={{ display: 'flex', alignItems: 'baseline', gap: 10 }}>
        <h3 style={{ margin: 0, fontSize: 15 }}>{day.date}</h3>
        <span className="detail-muted" style={{ fontSize: 12 }}>{weekdayOf(day.date)}</span>
        {day.insights.length > 0 &&
          <span className="detail-muted" style={{ fontSize: 12 }}>洞察 {day.insights.length} 条</span>}
        <span className="detail-muted" style={{ fontSize: 12, marginLeft: 'auto' }}>
          {day.obs ? `抓取 ${day.obs.total} 条` : ''}
        </span>
      </div>

      {/* 选题行 */}
      <div style={{ fontSize: 13, marginTop: 8 }}>
        {day.topics.length === 0
          ? <span className="detail-muted">今日无选题</span>
          : (<>
              <b>今日选题：</b>
              {valid.length > 0 ? valid.map(t => t.topic).join(' / ')
                                : <span className="detail-muted">（无有效选题）</span>}
              {junk.length > 0 &&
                <span className="detail-muted" style={{ fontSize: 11, marginLeft: 8 }}>
                  已过滤 {junk.length} 条无效 token 选题
                </span>}
            </>)}
      </div>

      {/* 洞察卡列表 */}
      <div style={{ marginTop: 8 }}>
        {day.insights.length === 0
          ? <div className="detail-muted" style={{ fontSize: 13 }}>今日无洞察产出</div>
          : day.insights
              .slice()
              .sort((a, b) => String(a.generatedAt).localeCompare(String(b.generatedAt)))
              .map(i => <InsightCard key={i.id} insight={i} />)}
      </div>

      <ObservationsDrawer obs={day.obs} />
    </section>
  )
}

function Section({ title, children, defaultOpen = false, open: openProp, onToggle }) {
  const [inner, setInner] = useState(defaultOpen)
  const open = openProp !== undefined ? openProp : inner
  const toggle = () => { if (onToggle) onToggle(!open); else setInner(o => !o) }
  return (
    <div style={{ marginTop: 14 }}>
      <button onClick={toggle}
              style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 0,
                       fontWeight: 600, fontSize: 14, textAlign: 'left' }}>
        {open ? '▾' : '▸'} {title}
      </button>
      {open && <div style={{ marginTop: 8 }}>{children}</div>}
    </div>
  )
}

const th = { textAlign: 'left', borderBottom: '1px solid var(--border, #ddd)', padding: '4px 8px', fontSize: 12 }
const td = { borderBottom: '1px solid var(--border, #eee)', padding: '4px 8px', fontSize: 12, verticalAlign: 'top' }

export default function MaterialPanelView() {
  const [data, setData] = useState(null)
  const [err, setErr] = useState(null)
  const [days, setDays] = useState(7)
  const [vdOpen, setVdOpen] = useState(false)

  async function load(d = days) {
    try {
      setData(await api.mioMaterialPanel(d))
      setErr(null)
    } catch (e) {
      setErr(e?.message || String(e))
    }
  }
  useEffect(() => { load(days) }, [days])

  const dayList = useMemo(() => {
    if (!data) return []
    const map = new Map()
    const ensure = (d) => {
      if (!map.has(d)) map.set(d, { date: d, insights: [], topics: [], obs: null })
      return map.get(d)
    }
    for (const i of data.insights || []) { const d = localDay(i.generatedAt); if (d) ensure(d).insights.push(i) }
    for (const t of data.topics || []) { const d = localDay(t.selectedAt); if (d) ensure(d).topics.push(t) }
    for (const o of data.observations || []) { const d = o.date; if (d) ensure(d).obs = o }
    return [...map.values()].sort((a, b) => b.date.localeCompare(a.date))
  }, [data])

  if (err) return <div className="mio-view"><p className="detail-muted">加载失败：{err}</p></div>
  if (!data) return <div className="mio-view"><p className="detail-muted">加载中…</p></div>

  return (
    <div className="mio-view" style={{ padding: '0 4px', overflowY: 'auto', maxHeight: 'calc(100vh - 90px)' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
        <h2 style={{ margin: '10px 0' }}>素材面板</h2>
        <select value={days} onChange={e => setDays(Number(e.target.value))} style={{ fontSize: 13 }}>
          {[3, 7, 14, 30].map(d => <option key={d} value={d}>最近 {d} 天</option>)}
        </select>
        <span style={{ flex: 1 }} />
        <button onClick={() => setVdOpen(o => !o)}
                style={{ fontSize: 13, padding: '4px 12px', cursor: 'pointer' }}>
          {vdOpen ? '收起价值发现 ▴' : '▶ 跑价值发现'}
        </button>
      </div>

      {/* 日刊流：一天一节，最新在前 */}
      {dayList.length === 0 && (
        <p className="detail-muted" style={{ marginTop: 20 }}>窗口内无任何素材/产出</p>
      )}
      {dayList.map(day => <DaySection key={day.date} day={day} />)}

      {/* 价值发现实验：页底折叠区，顶栏按钮直达 */}
      <Section title="价值发现实验（人工触发 · 烧 LLM · 允许 0 结果）"
               open={vdOpen} onToggle={setVdOpen}>
        <ValueDiscoverySection obsDates={(data.observations || []).map(o => o.date)} />
      </Section>
    </div>
  )
}

import { useEffect, useMemo, useRef, useState } from 'react'
import { authFetch } from '../auth'
import { buildAdjacency, nodeEdges } from '../lib/observatoryAdjacency'

/**
 * Rail「记忆观测」（FR-7）：只读观测 · Mio 为唯一数据源。
 * 仅调 GET /api/v1/memory/observatory/data（FR-1），不写入、不做权威检索。
 */

// 类型徽标（色阶取 hermes-graph.html palette）
const TYPE_META = {
  rule: { label: '决策', tag: 'rgba(16,185,129,.12)', fg: '#34D399' },
  context: { label: '上下文', tag: 'rgba(167,139,250,.12)', fg: '#C4B5FD' },
  problem: { label: '问题', tag: 'rgba(239,68,68,.12)', fg: '#F87171' },
  experience: { label: '经验', tag: 'rgba(34,211,238,.12)', fg: '#67E8F9' },
  note: { label: '笔记', tag: 'rgba(56,189,248,.12)', fg: '#7DD3FC' },
  log: { label: '日志', tag: 'rgba(71,85,105,.12)', fg: '#94A3B8' },
  source: { label: '来源', tag: 'rgba(100,116,139,.14)', fg: '#94A3B8' },
  project: { label: '项目', tag: 'rgba(59,130,246,.12)', fg: '#60A5FA' },
}
const TYPE_ORDER = ['rule', 'context', 'problem', 'experience', 'note', 'log', 'source', 'project']
const DEF_META = { label: '其他', tag: 'rgba(122,92,26,.12)', fg: '#c4a87a' }
const typeMeta = (t) => TYPE_META[t] || DEF_META

// 复用热度阈值（对齐 hermes-graph.html reuseTier：≥8 高 / ≥3 中 / 其余低）；
// 基于复用证据的呈现信号，非权威价值判断（无证据 ≠ 无价值）。
const HIGH = 8
const MID = 3
function reuseTier(score) {
  const s = score || 0
  if (s >= HIGH) return { label: '复用高', bg: 'rgba(16,185,129,.15)', fg: '#34D399' }
  if (s >= MID) return { label: '复用中', bg: 'rgba(245,158,11,.15)', fg: '#FBBF24' }
  return { label: '复用低', bg: 'rgba(100,116,139,.16)', fg: '#94A3B8' }
}

const firstContent = (e) => (e.obs && (e.obs[1] || e.obs[0])) || ''

// eslint-disable-next-line complexity, max-lines-per-function
export default function MemoryObservatoryView() {
  const [data, setData] = useState(null)
  const [showLogs, setShowLogs] = useState(false)
  const [typeFilter, setTypeFilter] = useState('all')
  const [query, setQuery] = useState('')
  const [selectedId, setSelectedId] = useState(null)
  const [aggTab, setAggTab] = useState('project')
  const [fragTab, setFragTab] = useState(false)
  const [err, setErr] = useState(null)
  const [loading, setLoading] = useState(true)
  const [reloadKey, setReloadKey] = useState(0)
  const [fragFb, setFragFb] = useState('')
  const fbTimer = useRef(null)

  useEffect(() => {
    const ac = new AbortController()
    setLoading(true)
    setErr(null)
    authFetch(`/api/v1/memory/observatory/data${showLogs ? '?logs=1' : ''}`, { signal: ac.signal })
      .then((r) => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`)
        return r.json()
      })
      .then((d) => { setData(d); setLoading(false) })
      .catch((e) => {
        if (e && e.name === 'AbortError') return
        setErr(e?.message || String(e))
        setLoading(false)
      })
    return () => ac.abort()
  }, [showLogs, reloadKey])

  const entities = useMemo(() => data?.entities || [], [data])
  const meta = data?.meta || null
  const adj = useMemo(() => buildAdjacency(data?.relations || []), [data])
  const byId = useMemo(() => {
    const m = new Map()
    for (const e of entities) m.set(e.id, e)
    return m
  }, [entities])

  const typeCounts = useMemo(() => {
    const c = {}
    for (const e of entities) c[e.type] = (c[e.type] || 0) + 1
    return c
  }, [entities])

  const visible = useMemo(() => {
    const q = query.trim().toLowerCase()
    return entities.filter((e) => {
      if (typeFilter !== 'all' && e.type !== typeFilter) return false
      if (!q) return true
      if ((e.title || e.name || '').toLowerCase().includes(q)) return true
      return (e.obs || []).join('\n').toLowerCase().includes(q)
    })
  }, [entities, typeFilter, query])

  const selected = selectedId != null ? byId.get(selectedId) || null : null

  const aggregates = useMemo(() => {
    const key = aggTab === 'source' ? 'source' : 'project'
    return entities
      .filter((e) => e.type === key)
      .map((node) => {
        const { inc } = nodeEdges(adj, node.id)
        const mems = inc.map((i) => byId.get(i.from)).filter((e) => e && e.type !== key)
        return {
          node,
          memCount: mems.length,
          ruleCount: mems.filter((m) => m.type === 'rule').length,
          highCount: mems.filter((m) => (m.reuse_score || 0) >= HIGH).length,
        }
      })
      .sort((a, b) => b.memCount - a.memCount || a.node.title.localeCompare(b.node.title))
  }, [entities, byId, adj, aggTab])

  const fragments = useMemo(
    () => entities
      .filter((e) => e.type === 'rule' || e.type === 'experience')
      .slice()
      .sort((a, b) => (b.reuse_score || 0) - (a.reuse_score || 0)),
    [entities],
  )

  function fragmentsMarkdown() {
    let md = `# 提示词片段\n\n共 ${fragments.length} 条\n\n`
    for (const f of fragments) {
      const line = firstContent(f)
      md += `- ${f.title || f.name}（${typeMeta(f.type).label} · ${reuseTier(f.reuse_score).label}）：${line}（来源：${f.name}）\n`
    }
    return md
  }

  function flash(msg) {
    setFragFb(msg)
    if (fbTimer.current) clearTimeout(fbTimer.current)
    fbTimer.current = setTimeout(() => setFragFb(''), 3000)
  }

  async function copyFragments() {
    if (!fragments.length) return
    try {
      await navigator.clipboard.writeText(fragmentsMarkdown())
      flash(`✓ 已复制 ${fragments.length} 条`)
    } catch {
      flash('✗ 复制失败')
    }
  }

  function downloadFragments() {
    if (!fragments.length) return
    const blob = new Blob([fragmentsMarkdown()], { type: 'text/markdown;charset=utf-8' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = 'mio-observatory-fragments.md'
    document.body.appendChild(a)
    a.click()
    document.body.removeChild(a)
    URL.revokeObjectURL(url)
    flash(`✓ mio-observatory-fragments.md 已下载（${fragments.length} 条）`)
  }

  const reload = () => setReloadKey((k) => k + 1)
  const ev = meta?.evidence || { memTotal: 0, memWithEvidence: 0, reuseRecords: 0 }
  const chips = TYPE_ORDER.filter((t) => typeCounts[t])

  return (
    <div className="obs-view">
      <div className="obs-head">
        <h2 className="obs-title">记忆观测</h2>
        <span className="detail-muted">只读观测 · Mio 为唯一数据源</span>
        <span className="obs-ev">
          复用证据 {ev.memWithEvidence}/{ev.memTotal}
          <span className="detail-muted">（无复用证据 ≠ 无价值）</span>
        </span>
        <span className="detail-muted">{ev.reuseRecords} 次复用记录</span>
        <button
          className="btn btn--ghost btn--xs"
          onClick={() => setShowLogs((v) => !v)}
          title={showLogs ? '收起 task-outcome 日志实体' : '展开 task-outcome 日志实体'}
        >
          日志 {showLogs ? '开' : '关'}
        </button>
        <button className="btn btn--ghost btn--xs" onClick={reload}>刷新</button>
      </div>

      {err && (
        <div className="obs-err">
          加载失败：{err}
          <button className="btn btn--ghost btn--xs" onClick={reload}>重试</button>
        </div>
      )}

      <div className="obs-tools">
        <div className="obs-chips" role="tablist" aria-label="类型筛选">
          <button
            className={`obs-chip${typeFilter === 'all' ? ' is-active' : ''}`}
            onClick={() => setTypeFilter('all')}
          >
            全部 {entities.length}
          </button>
          {chips.map((t) => (
            <button
              key={t}
              className={`obs-chip${typeFilter === t ? ' is-active' : ''}`}
              style={typeFilter === t ? { background: typeMeta(t).tag, color: typeMeta(t).fg } : undefined}
              onClick={() => setTypeFilter(t)}
            >
              {typeMeta(t).label} {typeCounts[t]}
            </button>
          ))}
        </div>
        <label className="obs-filter">
          <input
            value={query}
