              <button className={`obs-agg__tab${aggTab === 'source' ? ' is-active' : ''}`} onClick={() => setAggTab('source')}>按来源</button>
            </div>
            <table className="obs-agg__table">
              <thead>
                <tr>
                  <th>{aggTab === 'source' ? '来源' : '项目'}</th>
                  <th>记忆数</th>
                  <th>决策数</th>
                  <th>高复用数</th>
