                  <tr key={a.node.id}>
                    <td>
                      <button className="obs-link" onClick={() => setSelectedId(a.node.id)}>
                        {a.node.title || a.node.name}
                      </button>
                    </td>
                    <td>{a.memCount}</td>
                    <td>{a.ruleCount}</td>
                    <td>{a.highCount}</td>
