                  {fragFb && <span className="obs-frag__fb">{fragFb}</span>}
                </span>
              )}
            </div>
            {fragTab && (
              <ul className="obs-frag__list">
                {fragments.length === 0 && <li className="detail-muted">无 rule/experience 实体</li>}
                {fragments.map((f) => (
                  <li key={f.id} className="obs-frag__item">
                    <div className="obs-frag__row">
                      <span className="obs-frag__title">{f.title || f.name}</span>
                      <span className="obs-card__tier" style={{ background: reuseTier(f.reuse_score).bg, color: reuseTier(f.reuse_score).fg }}>
                        {reuseTier(f.reuse_score).label}
                      </span>
                    </div>
                    <div className="obs-frag__line">{firstContent(f)}</div>
                    <button className="obs-link mono" onClick={() => setSelectedId(f.id)}>↗ {f.name}</button>
                  </li>
                ))}
              </ul>
            )}
          </div>

          <p className="detail-muted obs-foot">
            数据只读自 MIO_HOME（memory.jsonl / experience_reuse.jsonl），由 mio-agent-runtime 维护；
            本地过滤仅作用于已加载数据（非权威检索），不写回记忆、不改动任务/文档数据。
            {meta?.skipped && (meta.skipped.mio > 0 || meta.skipped.reuse > 0)
              ? ` 坏行跳过 mio=${meta.skipped.mio} reuse=${meta.skipped.reuse}。`
              : ''}
          </p>
        </>
      )}
    </div>
  )
}

/** 详情面板出入边（ego view）：只渲染相邻节点，不渲染全图。 */
function DetailEdges({ adj, byId, node, onJump }) {
  const { out, inc } = nodeEdges(adj, node.id)
  if (!out.length && !inc.length) {
    return <p className="detail-muted obs-edges__empty">无关联边</p>
  }
  const renderItem = (entity, rel, key) => {
    if (!entity) return null
    const tm = typeMeta(entity.type)
    return (
      <li key={key}>
        <span className="obs-edge__rel">{rel}</span>
        <button className="obs-link" onClick={() => onJump(entity.id)}>
          {entity.title || entity.name}
        </button>
        <span className="obs-card__type" style={{ background: tm.tag, color: tm.fg }}>{tm.label}</span>
      </li>
    )
  }
  return (
    <div className="obs-edges">
      <h4 className="obs-sec">出边 {out.length}</h4>
      <ul>
        {out.map((e, i) => renderItem(byId.get(e.to), e.rel, `o${i}`))}
      </ul>
      <h4 className="obs-sec">入边 {inc.length}</h4>
      <ul>
        {inc.map((e, i) => renderItem(byId.get(e.from), e.rel, `i${i}`))}
      </ul>
    </div>
  )
}

import { useEffect, useState, useCallback } from 'react'
import { api } from '../api'
import { authFetch } from '../auth'
import { Skeleton, SkeletonField, SkeletonList } from './Skeleton'
import MemoryObservatoryView from './MemoryObservatoryView'

const TONE = {
  ok: 'var(--accent)',
  live: 'var(--accent)',
  warn: 'var(--warn)',
  danger: 'var(--danger)',
  muted: 'var(--ink-faint)',
}

function HealthField({ label, value, tone = 'muted', mono = true }) {
  const display = value === null || value === undefined ? '—' : String(value)
  return (
    <div className="memory-field">
      <span className="memory-field__label">{label}</span>
      <span className="memory-field__value" style={{ color: TONE[tone] || TONE.muted }}>
        <span style={{ fontFamily: mono ? 'var(--font-mono)' : 'inherit' }}>{display}</span>
      </span>
    </div>
  )
}

function StatusDot({ ok }) {
  return (
    <span className={`memory-dot${ok ? ' is-live' : ' is-down'}`} aria-label={ok ? '正常' : '不可达'} />
  )
}

function ToolBar({ name, count }) {
  return (
    <div className="memory-toolbar">
      <div className="memory-toolbar__head">
        <span className="memory-toolbar__name">{name}</span>
        <span className="memory-toolbar__total mono">{count}</span>
      </div>
    </div>
  )
}

function EventRow({ ev }) {
  const tone =
    ev.type === 'memory_record' ? 'live' :
    ev.type === 'memory_observer_ingest' ? 'warn' :
    ev.type === 'memory_experience_reuse' ? 'ok' : 'muted'
  return (
    <div className="memory-event" data-type={ev.type}>
      <div className="memory-event__row">
        <span className="memory-event__type" style={{ color: TONE[tone] }}>{ev.type}</span>
        <span className="memory-event__seq mono">#{ev.seq}</span>
        <span className="memory-event__time mono">{new Date(ev.at).toLocaleTimeString()}</span>
      </div>
      <div className="memory-event__entity mono">{ev.entity_id}</div>
      {ev.payload && (
        <div className="memory-event__payload mono">
          {ev.payload.tool || ''} {ev.payload.params ? JSON.stringify(ev.payload.params).slice(0, 80) : ''}
        </div>
      )}
    </div>
  )
}

function QueryPanel() {
  const [keyword, setKeyword] = useState('')
  const [kind, setKind] = useState('')
  const [results, setResults] = useState(null)
  const [loading, setLoading] = useState(false)

  const doQuery = useCallback(async () => {
    setLoading(true)
    try {
      const params = new URLSearchParams()
      if (keyword) params.set('keyword', keyword)
      if (kind) params.set('kind', kind)
      params.set('limit', '50')
      const r = await authFetch(`/api/v1/memory/query?${params}`)
      if (!r.ok) throw new Error(`HTTP ${r.status}`)
      setResults(await r.json())
    } catch (e) {
      setResults({ error: e.message })
    } finally {
      setLoading(false)
    }
  }, [keyword, kind])

  return (
    <div className="memory-query">
      <div className="memory-query__bar">
        <input
          className="memory-query__input"
          placeholder="搜索关键词…"
          value={keyword}
          onChange={e => setKeyword(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && doQuery()}
        />
        <select className="memory-query__select" value={kind} onChange={e => setKind(e.target.value)}>
          <option value="">全部类型</option>
          <option value="decision">决策 (decision)</option>
          <option value="context">上下文 (context)</option>
          <option value="problem">问题 (problem)</option>
          <option value="note">笔记 (note)</option>
          <option value="experience">经验 (experience)</option>
        </select>
        <button className="memory-btn" onClick={doQuery} disabled={loading}>
          {loading ? '查询中…' : '查询'}
        </button>
      </div>
      {results && (
        <div className="memory-query__results">
          {results.error ? (
            <div className="memory-error" role="alert">▲ {results.error}</div>
          ) : results.total === 0 ? (
            <div className="memory-empty">无匹配结果</div>
          ) : (
            <>
              <div className="memory-query__count mono">{results.total} 条结果</div>
              {results.entities.map((ent, i) => (
                <div key={i} className="memory-entity">
                  <div className="memory-entity__head">
                    <span className="memory-entity__name">{ent.name}</span>
                    <span className="memory-entity__type mono">{ent.entityType}</span>
                    {ent._score > 0 && <span className="memory-entity__score mono">score:{ent._score}</span>}
                  </div>
                  <div className="memory-entity__obs">
                    {ent.observations.map((obs, j) => (
                      <div key={j} className="memory-entity__obs-line">{obs}</div>
                    ))}
                  </div>
                </div>
              ))}
            </>
          )}
        </div>
      )}
    </div>
  )
}

// eslint-disable-next-line complexity
export default function MemoryView({ liveEvent }) {
  const [tab, setTab] = useState('observatory')
  const [health, setHealth] = useState(null)
  const [metrics, setMetrics] = useState(null)
  const [events, setEvents] = useState([])
  const [loading, setLoading] = useState(true)
  const [err, setErr] = useState(null)

  const reload = useCallback(async () => {
    setLoading(true)
    setErr(null)
    try {
      const [h, m, e] = await Promise.allSettled([
        api.memoryHealth(),
        api.metrics(),
        api.memoryEvents(200),
      ])
      if (h.status === 'fulfilled') setHealth(h.value)
      else setErr('health: ' + h.reason.message)
      if (m.status === 'fulfilled') setMetrics(m.value)
      if (e.status === 'fulfilled') setEvents(e.value)
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    if (tab !== 'gateway') return
    reload()
    // 网关面板轮询改 30s（任务 613bc0ca · FR-5）：非主视图，5s 一次徒增服务端负载。
    const t = setInterval(reload, 30000)
    return () => clearInterval(t)
  }, [reload, tab])

  useEffect(() => {
    if (!liveEvent) return
    const ev = liveEvent.event || liveEvent
    if (typeof ev?.type === 'string' && ev.type.startsWith('memory_')) {
      setEvents(prev => [ev, ...prev].slice(0, 30))
    }
  }, [liveEvent])

  // 解析 metrics
  const callsTotal = metrics?.taskhub_memory_calls_total
  const perTool = {}
  if (Array.isArray(callsTotal)) {
    for (const row of callsTotal) {
      const tool = row.label === 'tool' ? row.value : null
      const outcome = row.label === 'outcome' ? row.value : null
      if (tool && outcome) {
        // eslint-disable-next-line max-depth
        if (!perTool[tool]) perTool[tool] = { ok: 0, error: 0 }
        perTool[tool][outcome] = row.count
      }
    }
  }
  if (health?.mcp?.per_tool_5m) {
    for (const [tool, count] of Object.entries(health.mcp.per_tool_5m)) {
      if (!perTool[tool]) perTool[tool] = { ok: 0, error: 0 }
      perTool[tool].ok = count
    }
  }

  const mcp = health?.mcp || {}
  const storeAlive = mcp.available === true

  return (
    <div className={`memory-view${tab === 'observatory' ? ' memory-view--obs' : ''}`}>
      <div className="memory-tabs" role="tablist" aria-label="记忆视图切换">
        <button
          className={`memory-tab${tab === 'observatory' ? ' is-on' : ''}`}
          role="tab" aria-selected={tab === 'observatory'}
          onClick={() => setTab('observatory')}
        >记忆观测</button>
        <button
          className={`memory-tab${tab === 'gateway' ? ' is-on' : ''}`}
          role="tab" aria-selected={tab === 'gateway'}
          onClick={() => setTab('gateway')}
        >记忆网关</button>
      </div>
      {tab === 'observatory' ? (
        <MemoryObservatoryView />
      ) : (
      <>
      <div className="memory-header">
        <h2>Memory Store</h2>
        <div className="memory-header__sub">
          {health === null ? <Skeleton variant="circle" width="8px" height="8px" /> : <StatusDot ok={storeAlive} />}
          <span>{health === null ? '加载中…' : `${mcp.store_type || 'jsonl'} · ${mcp.entity_count ?? 0} entities`}</span>
          <button className="memory-btn" onClick={reload} disabled={loading}>
            {loading ? '刷新中…' : '刷新'}
          </button>
        </div>
      </div>

      {err && <div className="memory-error" role="alert">▲ {err}</div>}

      <section className="memory-section">
        <h3>存储状态</h3>
        {health === null ? <SkeletonField count={4} /> : (
          <div className="memory-grid">
            <HealthField label="store_type" value={mcp.store_type} tone="ok" />
            <HealthField label="entity_count" value={mcp.entity_count ?? 0} tone="ok" />
            <HealthField label="relation_count" value={mcp.relation_count ?? 0} tone="ok" />
            <HealthField label="data_file" value={mcp.data_file || '—'} tone="muted" />
          </div>
        )}
      </section>

      <section className="memory-section">
        <h3>查询记忆</h3>
        <QueryPanel />
      </section>

      {Object.keys(perTool).length > 0 && (
        <section className="memory-section">
          <h3>调用统计</h3>
          <div className="memory-tools">
            {Object.entries(perTool).map(([tool, stats]) => (
              <ToolBar key={tool} name={tool} count={stats.ok + stats.error} />
            ))}
          </div>
        </section>
      )}

      <section className="memory-section">
        <h3>
          实时事件
          <span className="memory-section__hint mono">WS · {events.length} 条</span>
        </h3>
        {events.length === 0 ? (
          health === null
            ? <SkeletonList count={5} />
            : <div className="memory-empty">尚无 memory_* 事件。可通过 /api/v1/memory/record 等端点写入。</div>
        ) : (
          <div className="memory-events">
            {events.map(ev => (
              <EventRow key={ev.seq} ev={ev} />
            ))}
          </div>
        )}
      </section>
      </>
      )}
    </div>
  )
}

import { useEffect, useState } from 'react'
import { api } from '../api'

/** Mio Agent Runtime 只读面板（低耦合：数据来自 MIO_HOME，不写入、不改任务/文档数据）。 */

const fmtBytes = (n) => n == null ? '' : n < 1024 ? `${n} B`
  : n < 1048576 ? `${(n / 1024).toFixed(1)} KB` : `${(n / 1048576).toFixed(1)} MB`

const fmtTime = (t) => {
  if (!t) return '—'
  const d = typeof t === 'number' ? new Date(t * 1000) : new Date(t)
  return isNaN(d.getTime()) ? String(t) : d.toLocaleString()
}

const clip = (s, n = 200) => {
  const str = s == null ? '' : String(s)
  return str.length > n ? str.slice(0, n) + '…' : str
}

// eslint-disable-next-line complexity, max-lines-per-function
export default function MioRuntimeView() {
  const [st, setSt] = useState(null)
  const [traces, setTraces] = useState([])
  const [mem, setMem] = useState([])
  const [crea, setCrea] = useState(null)
  const [pending, setPending] = useState(null)
  const [confirming, setConfirming] = useState('')
  const [err, setErr] = useState(null)
  const [starting, setStarting] = useState(false)

  async function load() {
    try {
      const [s, t, m, c, p] = await Promise.all([
        api.mioStatus(), api.mioTraces(15), api.mioMemory(15), api.mioCreativity(15),
        api.mioExperiencePending('', 20).catch(() => null),
      ])
      setSt(s)
      setTraces(t.items || [])
      setMem(m.items || [])
      setCrea(c)
      setPending(p)
      setErr(null)
    } catch (e) {
      setErr(e?.message || String(e))
    }
  }

  useEffect(() => { load() }, [])

  // 观测守护一键拉起（幂等）：观察器 + 研究调度器，成功后刷新状态
  async function startDaemons() {
    setStarting(true)
    try {
      await api.mioObserverStart()
      await load()
    } catch (e) {
      setErr(e?.message || String(e))
    } finally {
      setStarting(false)
    }
  }

  // TH-01（FR-9）：确认一条待复用经验。确认只调用 runtime 真实逻辑，
  // 失败来源（outcome 未改善）在按钮层即禁用。
  async function confirmExp(id) {
    setConfirming(id)
    try {
      await api.mioExperienceConfirm(id)
      setPending(await api.mioExperiencePending('', 20).catch(() => null))
      setErr(null)
    } catch (e) {
      setErr(e?.message || String(e))
    } finally {
      setConfirming('')
    }
  }

  if (err) return <div className="mio-view"><p className="detail-muted">加载失败：{err}</p></div>
  if (!st) return <div className="mio-view"><p className="detail-muted">加载中…</p></div>

  if (!st.available) {
    return (
      <div className="mio-view">
        <h2 className="mio-title">Mio 运行时</h2>
        <p className="detail-muted">
          未检测到 MIO_HOME（<span className="mono">{st.home}</span>）。安装并初始化
          <span className="mono"> mio-agent-runtime </span>后此处会自动显示。
        </p>
      </div>
    )
  }

  const daemonsOff = ((st.observer && !st.observer.running)
    || (st.research && !st.research.running))
  const agents = Object.keys(st.config?.agents || {})

  return (
    <div className="mio-view">
      <div className="mio-head">
        <h2 className="mio-title">Mio 运行时</h2>
        <span className="detail-muted mono">{st.home}</span>
        {daemonsOff && (
          <button className="btn btn--primary btn--xs" disabled={starting}
                  onClick={startDaemons}
                  title="拉起观察器（mio observe --start）与研究调度器（mio observer serve）">
            {starting ? '拉起中…' : '⚠ 一键拉起守护'}
          </button>
        )}
        <button className="btn btn--ghost btn--xs" onClick={load}>刷新</button>
      </div>

      <div className="mio-cards">
        <div className="mio-card">
          <div className="mio-card__t">观察器</div>
          <div className={`mio-status${st.observer?.running ? ' is-ok' : ' is-off'}`}>
            {st.observer?.running ? `运行中 · pid ${st.observer.pid}` : '未运行'}
          </div>
          {!st.observer?.running && (
            <p className="detail-muted">采集断供中——点右上「一键拉起守护」
              （等价 <span className="mono">mio observe --start</span>）</p>
          )}
        </div>
        <div className="mio-card">
          <div className="mio-card__t">研究调度器</div>
          <div className={`mio-status${st.research?.running ? ' is-ok' : ' is-off'}`}>
            {st.research?.running
              ? `运行中${st.research.pid ? ` · pid ${st.research.pid}` : ' · 活动探测'}`
              : '未运行'}
          </div>
          {st.research?.running && st.research.source === 'recent-activity' && (
            <p className="detail-muted">由近期观测活动推断（外部启动，未写 pid）</p>
          )}
          {st.research?.running && st.research.source === 'hub' && (
            <p className="detail-muted">由 taskhub 托管</p>
          )}
