        )}

        {draftAgents.length === 0 && !showAdd && (
          <div style={{ padding: '12px', textAlign: 'center', fontFamily: 'var(--font-mono)', fontSize: '11px', color: 'var(--warn)', border: '1px dashed var(--line)', borderRadius: '8px' }}>
            未配置任何 agent — 点击「添加 Agent」开始配置
          </div>
        )}

        {draftAgents.map((a, i) => (
          <div key={i} className="np-agent-row">
            {editingIdx === i ? (
              <>
                <input style={{ width: '80px' }} value={editForm.agent || ''} onChange={e => setEditForm(f => ({ ...f, agent: e.target.value }))} placeholder="名称" />
                <input style={{ width: '80px' }} value={editForm.agent_type || ''} onChange={e => setEditForm(f => ({ ...f, agent_type: e.target.value }))} placeholder="类型" />
                <input style={{ flex: 1, minWidth: '120px' }} value={editForm.command || ''} onChange={e => setEditForm(f => ({ ...f, command: e.target.value }))} placeholder="command" />
                <input style={{ width: '80px' }} value={editForm.cwd || ''} onChange={e => setEditForm(f => ({ ...f, cwd: e.target.value }))} placeholder="cwd" />
                <div className="np-agent-row__actions">
                  <button className="btn btn--accent btn--xs" onClick={() => applyEdit(i)}>✓</button>
                  <button className="btn btn--ghost btn--xs" onClick={cancelEdit}>✕</button>
                </div>
              </>
            ) : (
              <>
                <span className="np-agent-row__name">{a.agent || a.agent_type || '?'}</span>
                <span className="np-agent-row__type">{a.agent_type || '-'}</span>
                <span className="np-agent-row__cmd" title={a.command}>{a.command}</span>
                {a.cwd && <span className="np-agent-row__cwd" title={a.cwd}>{a.cwd}</span>}
                <div className="np-agent-row__actions">
                  <button className="btn btn--ghost btn--xs" onClick={() => startEdit(i)} title="编辑">✎</button>
                  <button className="btn btn--ghost btn--xs" onClick={() => deleteAgent(i)} title="删除" style={{ color: 'var(--warn)' }}>✕</button>
                </div>
              </>
            )}
          </div>
        ))}
      </div>

      <div className="np-scope">
        <span className="np-scope__label">项目范围（不选 = 全部项目）</span>
        <div className="np-scope__list">
          {(projects || []).length === 0 && <span className="detail-muted">未发现项目</span>}
          {(projects || []).map(p => (
            <label key={p} className={`np-scope__item${scopeProjects.includes(p) ? ' is-on' : ''}`}>
              <input type="checkbox" checked={scopeProjects.includes(p)}
                     onChange={e => setScopeProjects(list => e.target.checked
                       ? [...list, p] : list.filter(x => x !== p))} />
              {p}
            </label>
          ))}
        </div>
        <p className="np-scope__hint">
          只领取所选项目的任务（避免把不适合空闲做的项目丢进来）；命令模板里用
          <span className="mono"> {'{project}'} </span>占位符把范围传给 worker。
        </p>
      </div>
    </div>
  )
}

// eslint-disable-next-line complexity
function StatusPanel({ status, config, onRefresh, refreshing, onStop, onSpawnNow, spawnMsg }) {
  const running = status?.running_agents || {}
  const runningCount = Object.keys(running).length
  const inWindow = status?.in_window
  const windowDisplay = status?.window || `${config?.window_start || DEFAULT_START} – ${config?.window_end || DEFAULT_END}`

  return (
    <div className="np-status">
      <div className={`np-status__window${inWindow ? ' is-active' : ''}`}>
        <div className={`np-status__dot${inWindow ? ' is-live' : ''}`} />
        <div className="np-status__window-info">
          {inWindow ? '窗口内 — 自动执行已配置的 agent' : '窗口外 — 等待入窗'}
        </div>
        <div className="np-status__window-time">{windowDisplay}</div>
        <button className="btn btn--ghost btn--xs" onClick={onRefresh} disabled={refreshing} title="刷新状态" style={{ marginLeft: '8px' }}>
          {refreshing ? '⏳' : '🔄'}
        </button>
      </div>

      {runningCount > 0 && (
        <div>
          <div style={{ fontFamily: 'var(--font-mono)', fontSize: '10px', letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--ink-faint)', marginBottom: '6px' }}>
            运行中进程 ({runningCount})
          </div>
          <div className="np-procs">
            {Object.entries(running).map(([name, pid]) => (
              <div key={name} className="np-proc">
                <span className="np-proc__name">{name}</span>
                <span className="np-proc__pid">PID {pid}</span>
                <span className="np-proc__uptime">
                  <span style={{ color: 'var(--ok, #3ecf8e)' }}>●</span> 运行中
                </span>
                <button className="btn btn--ghost btn--xs np-proc__kill" onClick={() => onStop && onStop(name)} title="停止此进程">■</button>
              </div>
            ))}
          </div>
        </div>
      )}

      {runningCount === 0 && (
        <div style={{ padding: '12px', textAlign: 'center', fontFamily: 'var(--font-mono)', fontSize: '11px', color: 'var(--ink-faint)', border: '1px dashed var(--line)', borderRadius: '8px' }}>
          当前无运行中的 agent 进程
        </div>
      )}

      <div style={{ display: 'flex', gap: '8px', marginTop: '4px' }}>
        <button className="btn btn--ghost" onClick={onSpawnNow} disabled={!config?.agents?.length} title="立即按当前配置 spawn（测试用，不受窗口限制）">
          ⚡ 手动触发 Spawn
        </button>
        <button className="btn btn--ghost" onClick={onStop} disabled={runningCount === 0} title="停止所有运行中的 agent">
          ■ 全部停止
        </button>
      </div>

      {spawnMsg && (
        <div className="np-spawn-msg">
          {spawnMsg.__error
            ? <div className="np-spawn-msg__row is-err"><span>试跑失败：{spawnMsg.__error}</span></div>
            : Object.entries(spawnMsg).map(([name, r]) => (
                <div key={name} className={`np-spawn-msg__row${r && r.ok ? ' is-ok' : ' is-err'}`}>
                  <span className="mono np-spawn-msg__name">{name}</span>
                  {r && r.ok
                    ? <span>已拉起 · pid {r.pid}</span>
                    : <span>{r?.hint || r?.error || '启动失败（原因未知）'}</span>}
                </div>
              ))}
        </div>
      )}
    </div>
  )
}

function CronTasksPanel({ tasks, loading, onRefresh }) {
  return (
    <div className="np-cron">
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '6px' }}>
        <span style={{ fontFamily: 'var(--font-mono)', fontSize: '10px', letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--ink-faint)' }}>
          定时任务 ({tasks.length})
        </span>
        <button className="btn btn--ghost btn--xs" onClick={onRefresh}>{loading ? '⏳' : '🔄'}</button>
      </div>

      {tasks.length === 0 && !loading && (
        <div className="np-cron__empty">暂无定时任务 — 创建任务时设置 cron_expr 或 run_at</div>
      )}

      {tasks.map(t => {
        const nextRun = t.cron_expr ? parseNextCron(t.cron_expr) : (t.run_at ? parseUtc(t.run_at).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : null)
        return (
          <div key={t.id} className="np-cron-row">
            <span className="np-cron-row__cron" title={t.cron_expr || t.run_at}>
              {t.cron_expr || (t.run_at ? '⏰ 一次性' : '—')}
            </span>
            <span className="np-cron-row__title" title={t.title}>{t.title}</span>
            {nextRun && <span className="np-cron-row__next">下次: {nextRun}</span>}
            <span className={`np-cron-row__state np-cron-row__state--${t.state}`}>{t.state}</span>
          </div>
        )
      })}
    </div>
  )
}

// eslint-disable-next-line complexity, max-lines-per-function
export default function PlanView({ onSchedule }) {
  const [plan, setPlan] = useState(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)
  const [projects, setProjects] = useState([])
  const [selectedProject, setSelectedProject] = useState('')
  const [savedAt, setSavedAt] = useState(null)
  const [loadBusy, setLoadBusy] = useState(false)
  const [nrEnabled, setNrEnabled] = useState(false)
  const [nrSaving, setNrSaving] = useState(false)
  const [nrStatus, setNrStatus] = useState(null)
  const [nrConfig, setNrConfig] = useState(null)
  const [spawnMsg, setSpawnMsg] = useState(null)
  const [refreshing, setRefreshing] = useState(false)
  const [cronTasks, setCronTasks] = useState([])
  const [cronLoading, setCronLoading] = useState(false)

  const loadNrStatus = useCallback(async () => {
    setRefreshing(true)
    try {
      const data = await api.nrLoadFull()
      setNrStatus(data)
      setNrConfig(data)
      setNrEnabled(!!data.enabled)
    } catch { /* silent */ }
    finally { setRefreshing(false) }
  }, [])

  const loadCronTasks = useCallback(async () => {
    setCronLoading(true)
    try {
      const tasks = await api.nrCronTasks()
      setCronTasks(tasks)
    } catch { /* silent */ }
    finally { setCronLoading(false) }
  }, [])

  useEffect(() => {
    api.listProjects().then(setProjects).catch(() => {})
    loadNrStatus()
    loadCronTasks()
    const interval = setInterval(() => { loadNrStatus(); loadCronTasks(); }, 30000)
    return () => clearInterval(interval)
  }, [loadNrStatus, loadCronTasks])

  const saveNrConfig = async (cfg) => {
    setNrSaving(true)
    try {
      await api.nrSaveConfig({ ...cfg, enabled: nrEnabled })
      await loadNrStatus()
    } catch { /* silent */ }
    finally { setNrSaving(false) }
  }

  const toggleNrEnabled = () => setNrEnabled(e => !e)

  const handleSpawnNow = async () => {
    setSpawnMsg(null)
    try {
      const r = await api.nrSpawnNow()
      setSpawnMsg(r?.spawned || {})
      await loadNrStatus()
    } catch (e) {
      setSpawnMsg({ __error: e?.message || String(e) })
    }
  }

  const handleStopAll = async () => {
    const ok = await confirm('确定停止所有运行中的 agent？',
                             { title: '停止全部 agent', danger: true, okText: '全部停止' })
    if (!ok) return
    try { await api.nrStop(); await loadNrStatus(); } catch { /* silent */ }
  }

  const _render = (data) => {
    const items = (data.items ?? []).map((t) => {
      const off = hm2min(t.scheduled_start) - WINDOW_START_MIN
      return {
        ...t,
        id: t.task_id ?? t.id,
        start: off < 0 ? off + 1440 : off,
        dur: Math.min(WINDOW_MIN, Math.max(5, t.est_duration_min ?? 30)),
        agent: t.agent_type || '',
      }
    })
    const lastEnd = items.length ? Math.min(WINDOW_MIN, Math.max(...items.map((i) => i.start + i.dur))) : 0
    setPlan({ items, fitted: items.length, total: items.length, filled: lastEnd, overflow: data.has_overflow ? '⚠' : 0, parallel: data.max_parallel || 1, project: data.project })
    setSavedAt(data.generated_at || null)
    onSchedule && onSchedule({ items, fitted: items.length, total: items.length, filled: lastEnd, overflow: data.has_overflow ? '⚠' : 0 })
  }

  const generate = async () => {
    setLoading(true); setError(null)
    try {
      const data = await api.nightPlan(DEFAULT_START, DEFAULT_END, selectedProject || null)
      _render(data)
    } catch { setError('空闲计划接口调用失败，请稍后重试') }
    finally { setLoading(false) }
  }

  const loadSaved = async () => {
    setLoadBusy(true); setError(null)
    try { _render(await api.nightPlanSaved()) }
    catch (e) { setError('未找到已落盘的计划：' + (e.message || '404')) }
    finally { setLoadBusy(false) }
  }

  const occupancy = plan ? Math.round((plan.filled / WINDOW_MIN) * 100) : 0

  return (
    <div className="np">
      <div className="np__head">
        <div>
          <h2>空闲计划 <span className="np__accent">IDLE SHIFT</span></h2>
          <p className="np__sub">
            {DEFAULT_START} – {DEFAULT_END} · 同 agent 串行 / 跨 agent 并行
            {plan?.parallel > 1 && <span> · 峰值并行 {plan.parallel}</span>}
            {plan?.project && <span> · <b style={{ color: 'var(--accent)' }}>{plan.project}</b></span>}
          </p>
        </div>
        <div className="np__actions">
          <select className="np__project-select" value={selectedProject} onChange={e => setSelectedProject(e.target.value)}>
            <option value="">全部项目</option>
            {projects.map(p => <option key={p} value={p}>{p}</option>)}
          </select>
          <button className="btn btn--accent" onClick={generate} disabled={loading}>
            {loading ? '生成中…' : '⟳ 生成计划'}
          </button>
          <button className="btn btn--ghost" onClick={loadSaved} disabled={loadBusy} title="读取最近一次落盘的计划">
            {loadBusy ? '加载中…' : '⤓ 上次计划'}
          </button>
          {savedAt && (
            <span className="np__saved" title="已落盘到 ~/.mio_taskhub/night_plans/latest.json">
              ✓ {new Date(savedAt).toLocaleTimeString('zh-CN')}
            </span>
          )}
        </div>
      </div>

      {error && <div className="errorbar" role="alert"><span>▲</span><span>{error}</span></div>}

      <div className="np-panels">
        <Section
          title="执行器配置" icon="⚙" badge={nrEnabled ? 'ON' : 'OFF'} badgeClass={nrEnabled ? 'np-section__badge--ok' : ''} defaultOpen={true}
        >
          <ConfigPanel
            config={nrConfig}
            onSave={saveNrConfig}
            onToggleEnabled={toggleNrEnabled}
            enabled={nrEnabled}
            saving={nrSaving}
            agents={nrConfig?.agents}
            projects={projects}
          />
        </Section>

        <Section
          title="运行状态" icon="◉"
          badge={nrStatus ? (Object.keys(nrStatus.running_agents || {}).length > 0 ? `${Object.keys(nrStatus.running_agents).length} 进程` : (nrStatus.in_window ? '窗口内' : '空闲')) : null}
          badgeClass={nrStatus?.in_window ? 'np-section__badge--ok' : ''}
        >
          <StatusPanel
            status={nrStatus}
            config={nrConfig}
            onRefresh={loadNrStatus}
            refreshing={refreshing}
            onStop={handleStopAll}
            onSpawnNow={handleSpawnNow}
            spawnMsg={spawnMsg}
          />
        </Section>

        <Section
          title="定时任务" icon="⏰" badge={cronTasks.length || null}
        >
          <CronTasksPanel tasks={cronTasks} loading={cronLoading} onRefresh={loadCronTasks} />
        </Section>
      </div>

      {plan ? (
        <>
          <div className="np__stats">
            <div className="np-stat np-stat--primary">
              <div className="np-stat__icon">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><rect x="3" y="4" width="18" height="16" rx="3"/><path d="M8 2v4M16 2v4M3 10h18"/></svg>
              </div>
              <div className="np-stat__num">{plan.fitted}<span className="np-stat__den"> / {plan.total}</span></div>
              <div className="np-stat__lbl">已排入</div>
            </div>
            <div className="np-stat">
              <div className="np-stat__bar"><div className="np-stat__bar-fill" style={{ width: `${occupancy}%` }} /></div>
              <div className="np-stat__num">{occupancy}<span className="np-stat__den">%</span></div>
              <div className="np-stat__lbl">窗口占用</div>
            </div>
            <div className={`np-stat ${plan.overflow ? 'np-stat--warn' : ''}`}>
              <div className="np-stat__num">{plan.overflow || '—'}</div>
              <div className="np-stat__lbl">溢出待排</div>
            </div>
            <div className="np-stat">
              <div className="np-stat__time">
                <span>{DEFAULT_START}</span>
                <span className="np-stat__sep">→</span>
                <span>{DEFAULT_END}</span>
              </div>
              <div className="np-stat__lbl">时间窗口</div>
            </div>
          </div>

          <div className="np-gantt">
            <div className="np-gantt__header">
              <div className="np-gantt__label-col">任务</div>
              <div className="np-gantt__time-col">
                {HOURS.map((h, i) => (
                  <span key={h} className="np-gantt__hour" style={{ left: `${(i / (HOURS.length - 1)) * 100}%` }}>{h}</span>
                ))}
                <div className="np-gantt__grid">
                  {HOURS.map((_, i) => (
                    <div key={i} className="np-gantt__gridline" style={{ left: `${(i / (HOURS.length - 1)) * 100}%` }} />
                  ))}
                </div>
              </div>
            </div>
            <div className="np-gantt__body">
              {plan.items.map((t, i) => {
                const p = prio(t.priority)
                const left = (t.start / WINDOW_MIN) * 100
                const width = (t.dur / WINDOW_MIN) * 100
                return (
                  <div key={t.id} className="np-row" style={{ '--i': i }}>
                    <div className="np-row__label">
                      <span className={`np-row__prio np-row__prio--p${p.p}`}>{p.label}</span>
                      <span className="np-row__title" title={t.title}>{t.title}</span>
                      {t.agent && <span className="np-row__agent">{t.agent}</span>}
                      {t.fallback_after != null && t.agent && (() => {
                        const elapsed = t.created_at ? (Date.now() - new Date(t.created_at).getTime()) / 1000 : 0
                        const expired = elapsed >= t.fallback_after
                        return (
                          <span className={`np-row__fb ${expired ? 'np-row__fb--open' : ''}`}
                            title={expired ? `已过 fallback 窗口 (${Math.floor(elapsed/3600)}h ≥ ${Math.floor(t.fallback_after/3600)}h)` : `fallback 等待中 (${Math.floor(elapsed/60)}m / ${Math.floor(t.fallback_after/60)}m)`}>
                            {expired ? '🔓' : '⏰'}
                          </span>
                        )
                      })()}
                    </div>
                    <div className="np-row__bar">
                      <div
                        className={`np-row__fill np-row__fill--p${p.p}`}
                        style={{ left: `${left}%`, width: `${Math.max(width, 2)}%` }}
                        title={`${t.title}\n${min2hm(t.start + WINDOW_START_MIN)} – ${min2hm(t.start + t.dur + WINDOW_START_MIN)} · ${fmtDur(t.dur)}`}
                      >
                        <span className="np-row__time">{fmtDur(t.dur)}</span>
                      </div>
                    </div>
                  </div>
                )
              })}
            </div>
          </div>

          <div className="np__legend">
            {[{ p: 3, t: 'P3 紧急', c: 'accent' }, { p: 2, t: 'P2 高', c: 'warn' }, { p: 1, t: 'P1 中', c: 'dim' }, { p: 0, t: 'P0 低', c: 'faint' }].map(x => (
              <span key={x.p} className={`np-legend np-legend--${x.c}`}><i />{x.t}</span>
            ))}
          </div>
        </>
      ) : (
        <div className="np__empty">
          <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round">
            <path d="M21 12.8A9 9 0 1111.2 3 7 7 0 0021 12.8z" />
          </svg>
          选择项目，点击「生成排期」预览今晚的执行序列
        </div>
      )}
    </div>
  )
}

import { useState, useEffect } from 'react'
import { api } from '../api'
import { fmtAgo, parseUtc } from '../constants'
import { confirm } from '../confirm'

export default function ScheduledJobsView() {
  const [jobs, setJobs] = useState([])
  const [loading, setLoading] = useState(true)
  const [showCreate, setShowCreate] = useState(false)
  const [editJob, setEditJob] = useState(null)
  const [execJob, setExecJob] = useState(null)
  const [executions, setExecutions] = useState([])
  const [tab, setTab] = useState('list')          // list | exec
  const [execFilter, setExecFilter] = useState('all')  // all | ok | error
  const [expanded, setExpanded] = useState({})    // 结果行展开
  const [err, setErr] = useState('')

  const load = () => {
    setLoading(true)
    api.listScheduledJobs().then(d => { setJobs(d); setLoading(false) }).catch(() => setLoading(false))
  }

  useEffect(() => { load() }, [])

  useEffect(() => {
    if (tab === 'exec' && !execJob && jobs.length > 0) setExecJob(jobs[0])
  }, [tab, execJob, jobs])

  useEffect(() => {
    if (execJob) {
      api.listScheduledJobExecutions(execJob.id).then(setExecutions).catch(() => setExecutions([]))
    }
  }, [execJob])

  // 视图级错误（R2 附加）：行内操作失败改用就近错误条，不再 window.alert（阻塞式原生弹窗，
  // 会被浏览器拦成「此页面已阻止弹窗」，且不进入任何可访问的播报通道）。
  const run = async (fn, label, job) => {
    setErr('')
    try {
      await fn()
      load()
    } catch (e) { setErr(`${label}失败${job ? `（${job.name}）` : ''}: ${e.userMessage || e.message}`) }
  }

  const handlePause   = (job) => run(() => api.pauseScheduledJob(job.id), '暂停', job)
  const handleResume  = (job) => run(() => api.resumeScheduledJob(job.id), '恢复', job)
  const handleTrigger = (job) => run(() => api.triggerScheduledJob(job.id), '触发', job)

  const handleDelete = async (job) => {
    if (!(await confirm(`删除定时任务「${job.name}」？该任务的执行记录会一并移除，操作不可撤销。`,
      { title: '删除定时任务', danger: true, okText: '删除' }))) return
    run(() => api.deleteScheduledJob(job.id), '删除', job)
  }

  return (
    <div className="sjv">
      <div className="sjv__head">
        <h2>定时任务</h2>
        <div className="sjv__tabs">
          <button className={`sjv__tab${tab === 'list' ? ' is-on' : ''}`} onClick={() => setTab('list')}>
            任务列表 <span className="sjv__tab-n">{jobs.length}</span>
          </button>
          <button className={`sjv__tab${tab === 'exec' ? ' is-on' : ''}`} onClick={() => setTab('exec')}>
            执行记录
          </button>
        </div>
        <button className="btn btn--accent" onClick={() => { setEditJob(null); setShowCreate(true) }}>
          + 新建定时任务
        </button>
      </div>

      {err && (
        <div className="modal__err sjv__err" role="alert">
          <span>▲</span>
          <span>{err}</span>
          <button className="sjv__err-x" onClick={() => setErr('')} aria-label="关闭错误提示">×</button>
        </div>
      )}

      {tab === 'list' && (loading ? (
        <div className="sjv__empty">加载中…</div>
      ) : jobs.length === 0 ? (
        <div className="sjv__empty">
          <p>暂无定时任务</p>
          <p className="sjv__empty-hint">创建定时任务后，系统会按 cron 表达式自动触发执行。</p>
        </div>
      ) : (
        <table className="sj-table sj-table--jobs">
          <thead>
            <tr>
              <th style={{ width: '30%' }}>任务</th>
              <th style={{ width: '110px' }}>Cron</th>
              <th style={{ width: '90px' }}>动作</th>
              <th style={{ width: '80px' }}>状态</th>
              <th style={{ width: '150px' }}>下次执行</th>
              <th style={{ width: '110px' }}>上次执行</th>
              <th style={{ width: '70px' }}>次数</th>
              <th style={{ width: '300px' }}>操作</th>
            </tr>
          </thead>
          <tbody>
            {jobs.map(job => (
              <tr key={job.id} className={job.enabled ? '' : 'is-disabled'}>
                <td className="sj-jobs__name" title={job.last_error || job.name}>
                  {job.name}
                  {job.last_error && <span className="sj-jobs__err" title={job.last_error}>⚠</span>}
                </td>
                <td><code className="sj-card__code">{job.cron_expr}</code></td>
                <td>{job.action_type === 'webhook' ? 'Webhook' : '创建任务'}</td>
                <td>
                  <span className={`sj-card__badge sj-card__badge--${job.last_status || 'pending'}`}>
                    {job.last_status === 'ok' ? '正常' : job.last_status === 'error' ? '异常' : '待执行'}
                  </span>
                </td>
                <td className="mono">{job.next_run_at ? parseUtc(job.next_run_at).toLocaleString('zh-CN') : '—'}</td>
                <td className="mono">{job.last_run_at ? fmtAgo(job.last_run_at) : '—'}</td>
                <td className="mono">{job.run_count}</td>
                <td className="sj-jobs__ops">
                  <button className="btn btn--ghost btn--sm" onClick={() => handleTrigger(job)}
                    disabled={!job.enabled}>执行</button>
                  {job.enabled ? (
                    <button className="btn btn--ghost btn--sm" onClick={() => handlePause(job)}>暂停</button>
                  ) : (
                    <button className="btn btn--ghost btn--sm" onClick={() => handleResume(job)}>恢复</button>
                  )}
                  <button className="btn btn--ghost btn--sm" onClick={() => { setEditJob(job); setShowCreate(true) }}>编辑</button>
                  <button className="btn btn--ghost btn--sm" onClick={() => { setExecJob(job); setTab('exec') }}>记录</button>
                  <button className="btn btn--ghost btn--sm btn--danger" onClick={() => handleDelete(job)}>删除</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ))}

      {tab === 'exec' && (
        <ExecPanel
          jobs={jobs}
          execJob={execJob}
          setExecJob={setExecJob}
          executions={executions}
          filter={execFilter}
          setFilter={setExecFilter}
          expanded={expanded}
          setExpanded={setExpanded}
        />
      )}

      {showCreate && (
        <ScheduledJobModal
          editJob={editJob}
          onClose={() => { setShowCreate(false); setEditJob(null) }}
          onSaved={() => { setShowCreate(false); setEditJob(null); load() }}
        />
      )}

    </div>
  )
}


// eslint-disable-next-line complexity, max-lines-per-function
function ScheduledJobModal({ editJob, onClose, onSaved }) {
  const [form, setForm] = useState({
    name: editJob?.name || '',
    cron_expr: editJob?.cron_expr || '',
    action_type: editJob?.action_type || 'create_task',
    action_config: editJob?.action_config || {},
    enabled: editJob?.enabled ?? true,
  })
  const [cronPreview, setCronPreview] = useState([])
  const [cronError, setCronError] = useState('')
  const [busy, setBusy] = useState(false)
  // JSON 字段用「文本态 + 提交时校验」，避免 onChange 解析吞掉中间态、光标跳动
  const [headersText, setHeadersText] = useState('')
  const [bodyText, setBodyText] = useState('')
  const [jsonErr, setJsonErr] = useState('')
  const [saveErr, setSaveErr] = useState('')

  useEffect(() => {
    setHeadersText(JSON.stringify(editJob?.action_config?.headers || {}, null, 2))
    setBodyText(JSON.stringify(editJob?.action_config?.body || {}, null, 2))
    setJsonErr('')
  }, [editJob])

  useEffect(() => {
    if (!form.cron_expr.trim()) { setCronPreview([]); setCronError(''); return }
    const timer = setTimeout(() => {
      api.validateCron(form.cron_expr.trim())
        .then(d => { setCronPreview(d.next_runs || []); setCronError('') })
        .catch(e => { setCronPreview([]); setCronError(e.userMessage || e.message) })
    }, 400)
    return () => clearTimeout(timer)
  }, [form.cron_expr])

  const isWebhook = form.action_type === 'webhook'
  const cfg = form.action_config

  // eslint-disable-next-line complexity
  const submit = async (e) => {
    e.preventDefault()
    if (!form.name.trim() || !form.cron_expr.trim()) return
    // Webhook 的 Headers/Body 在此处统一解析（失败明确提示，不再静默）
    let actionCfg = cfg
    if (isWebhook) {
      let headers, bodyObj  // 初值不会被读到（两条路径都先整体赋值再使用）
      try {
        headers = headersText.trim() ? JSON.parse(headersText) : {}
        if (headers === null || typeof headers !== 'object' || Array.isArray(headers)) {
          throw new Error('Headers 必须是 JSON 对象')
        }
      } catch (err) {
        setJsonErr('Headers JSON 无效：' + err.message)
        return
      }
      try {
        bodyObj = bodyText.trim() ? JSON.parse(bodyText) : {}
      } catch (err) {
        setJsonErr('Body JSON 无效：' + err.message)
        return
      }
      setJsonErr('')
      actionCfg = { ...cfg, headers, body: bodyObj }
    }
    setBusy(true)
    try {
      const body = {
        name: form.name.trim(),
        cron_expr: form.cron_expr.trim(),
        action_type: form.action_type,
        action_config: actionCfg,
        enabled: form.enabled,
      }
      if (editJob) {
        await api.updateScheduledJob(editJob.id, body)
      } else {
        await api.createScheduledJob(body)
      }
      onSaved()
    } catch (e) {
      // 浮层内错误条（与 CreateModal / StageAdvanceDialog 一致），不再 alert
      setSaveErr('保存失败: ' + (e.userMessage || e.message))
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className="overlay" onClick={onClose}>
      <div className="modal modal--job" role="dialog" onClick={e => e.stopPropagation()}>
        <div className="modal__head">
          <h3>{editJob ? '编辑定时任务' : '新建定时任务'}</h3>
          <button className="modal__close" onClick={onClose}>×</button>
        </div>
        <form onSubmit={submit}>
          <div className="modal__body">
            {saveErr && (
              <div className="modal__err" role="alert">
                <span>▲</span><span>{saveErr}</span>
                <button type="button" className="sjv__err-x" onClick={() => setSaveErr('')} aria-label="关闭错误提示">×</button>
              </div>
            )}
            <div className="sj-form__grid">
            <div className="field">
              <label className="field__label">名称 <b>*</b></label>
              <input autoFocus value={form.name} onChange={e => setForm({ ...form, name: e.target.value })}
                placeholder="例如：每日数据同步" />
            </div>
            <div className="field">
              <label className="field__label">Cron 表达式 <b>*</b></label>
              <input value={form.cron_expr} onChange={e => setForm({ ...form, cron_expr: e.target.value })}
                placeholder="分 时 日 月 周，如 0 9 * * 1-5" className={cronError ? 'field--error' : ''} />
              <div className="sj-cron-presets">
                {[['每小时', '0 * * * *'], ['每天 9 点', '0 9 * * *'],
                  ['工作日 9 点', '0 9 * * 1-5'], ['每周一', '0 9 * * 1'], ['每月 1 号', '0 9 1 * *']].map(([label, expr]) => (
                  <button key={expr} type="button"
                          className={`sj-cron-pre${form.cron_expr.trim() === expr ? ' is-on' : ''}`}
                          onClick={() => setForm({ ...form, cron_expr: expr })}>{label}</button>
                ))}
              </div>
              {cronError && <span className="field__err">{cronError}</span>}
              {cronPreview.length > 0 && (
                <div className="cron-preview">
                  <span className="cron-preview__label">下次执行：</span>
                  {cronPreview.map((t, i) => (
                    <span key={i} className="cron-preview__time">
                      {parseUtc(t).toLocaleString('zh-CN', { month:'numeric', day:'numeric', hour:'2-digit', minute:'2-digit' })}
                    </span>
                  ))}
                </div>
              )}
            </div>
            <div className="field">
              <label className="field__label">动作类型</label>
              <div className="sched-row">
                <button type="button" className={`sched-btn ${!isWebhook ? 'is-on' : ''}`}
                  onClick={() => setForm({ ...form, action_type: 'create_task', action_config: {} })}>创建任务</button>
                <button type="button" className={`sched-btn ${isWebhook ? 'is-on' : ''}`}
                  onClick={() => setForm({ ...form, action_type: 'webhook', action_config: { url: '', method: 'POST' } })}>Webhook</button>
              </div>
            </div>
            {isWebhook ? (
              <>
                <div className="field">
                  <label className="field__label">URL</label>
                  <input value={cfg.url || ''} onChange={e => setForm({ ...form, action_config: { ...cfg, url: e.target.value } })}
                    placeholder="http://127.0.0.1:48620/api/v1/..." />
                </div>
                <div className="field">
                  <label className="field__label">Method</label>
                  <select value={cfg.method || 'POST'} onChange={e => setForm({ ...form, action_config: { ...cfg, method: e.target.value } })}>
                    <option value="POST">POST</option>
                    <option value="PUT">PUT</option>
                    <option value="GET">GET</option>
                  </select>
                </div>
                <div className="field sj-form__full">
                  <label className="field__label">Headers (JSON，留空为 {})</label>
                  <textarea className="sj-json-ta" value={headersText} onChange={e => setHeadersText(e.target.value)}
                    spellCheck={false} rows={2} placeholder='{"Content-Type":"application/json"}' />
                </div>
                <div className="field sj-form__full">
                  <label className="field__label">Body (JSON，留空为 {})</label>
                  <textarea className="sj-json-ta sj-body-ta" value={bodyText} onChange={e => setBodyText(e.target.value)}
                    spellCheck={false} rows={8} placeholder='{"template_id":"exploration","values":{"title":"…"},"sync_to_hub":true}' />
                </div>
                {jsonErr && <div className="field sj-form__full"><span className="field__err">{jsonErr}</span></div>}
              </>
            ) : (
              <>
                <div className="field">
                  <label className="field__label">任务标题</label>
                  <input value={cfg.title || ''} onChange={e => setForm({ ...form, action_config: { ...cfg, title: e.target.value } })}
                    placeholder="留空则使用定时任务名称" />
                </div>
                <div className="field sj-form__full">
                  <label className="field__label">任务描述</label>
                  <textarea value={cfg.description || ''} onChange={e => setForm({ ...form, action_config: { ...cfg, description: e.target.value } })}
                    rows={4} placeholder="任务详细说明…" />
                </div>
                <div className="field">
                  <label className="field__label">优先级</label>
                  <select value={cfg.priority || 0} onChange={e => setForm({ ...form, action_config: { ...cfg, priority: +e.target.value } })}>
                    <option value={0}>P0 低</option>
                    <option value={1}>P1 中</option>
                    <option value={2}>P2 高</option>
                    <option value={3}>P3 紧急</option>
                  </select>
                </div>
                <div className="field">
                  <label className="field__label">目标 Agent</label>
                  <input value={cfg.target_agent_type || ''} onChange={e => setForm({ ...form, action_config: { ...cfg, target_agent_type: e.target.value } })}
                    placeholder="留空任意" />
                </div>
                <div className="field">
                  <label className="field__label">项目</label>
                  <input value={cfg.project || ''} onChange={e => setForm({ ...form, action_config: { ...cfg, project: e.target.value } })} />
                </div>
                <div className="field">
                  <label className="field__label">工作区</label>
                  <input value={cfg.workspace || ''} onChange={e => setForm({ ...form, action_config: { ...cfg, workspace: e.target.value } })} />
                </div>
                <div className="field">
                  <label className="field__label">标签</label>
                  <input value={(cfg.labels || []).join(', ')} onChange={e => setForm({ ...form, action_config: { ...cfg, labels: e.target.value.split(',').map(s => s.trim()).filter(Boolean) } })}
                    placeholder="tag1, tag2" />
                </div>
              </>
            )}
          </div>
            </div>
          <div className="modal__foot">
            <button type="button" className="btn btn--ghost" onClick={onClose}>取消</button>
            <button type="submit" className="btn btn--accent" disabled={busy || !form.name.trim() || !form.cron_expr.trim()}>
              {busy ? '保存中…' : (editJob ? '保存修改' : '创建定时任务')}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}


/** 执行记录 Tab：任务选择 + 成功/失败统计 + 全宽表格（结果不截断，可展开）。 */
function ExecPanel({ jobs, execJob, setExecJob, executions, filter, setFilter, expanded, setExpanded }) {
  const okCount = executions.filter(e => e.status === 'ok').length
  const errCount = executions.filter(e => e.status !== 'ok').length
  const rows = executions.filter(e => filter === 'all' ? true : (filter === 'ok' ? e.status === 'ok' : e.status !== 'ok'))

  return (
    <div className="sj-exec">
      <div className="sj-exec__bar">
        <div className="sj-exec__picker">
          {jobs.map(j => (
            <button key={j.id}
                    className={`sj-exec__job${execJob && execJob.id === j.id ? ' is-on' : ''}`}
                    onClick={() => setExecJob(j)}>
              {j.name}
            </button>
          ))}
        </div>
        <div className="sj-exec__stats">
          <span className="sj-exec__stat is-ok">成功 {okCount}</span>
          <span className="sj-exec__stat is-err">失败 {errCount}</span>
          <div className="sj-exec__filter">
            {[['all', '全部'], ['ok', '成功'], ['error', '失败']].map(([k, label]) => (
              <button key={k} className={`sj-exec__fbtn${filter === k ? ' is-on' : ''}`}
                      onClick={() => setFilter(k)}>{label}</button>
            ))}
          </div>
        </div>
      </div>

      {rows.length === 0 ? (
        <p className="sjv__empty">暂无执行记录</p>
      ) : (
        <table className="sj-table sj-table--wide">
          <thead>
            <tr>
              <th style={{ width: '170px' }}>时间</th>
              <th style={{ width: '80px' }}>状态</th>
              <th>结果 / 原因</th>
            </tr>
          </thead>
          <tbody>
            {rows.map(e => {
              const text = e.error || e.result || '—'
              const long = text.length > 120
              const open = !!expanded[e.id]
              return (
                <tr key={e.id} className={e.status === 'ok' ? '' : 'is-err'}>
                  <td className="mono">{parseUtc(e.started_at).toLocaleString('zh-CN')}</td>
                  <td><span className={`sj-badge sj-badge--${e.status}`}>{e.status === 'ok' ? '成功' : '失败'}</span></td>
                  <td className="sj-table__result sj-table__result--full">
                    <div className={open || !long ? '' : 'sj-exec__clamp'}>{text}</div>
                    {long && (
                      <button className="sj-exec__more" onClick={() => setExpanded(x => ({ ...x, [e.id]: !open }))}>
                        {open ? '收起' : '展开全部'}
                      </button>
                    )}
                  </td>
                </tr>
              )
            })}
          </tbody>
        </table>
      )}
    </div>
  )
}

/** 设置面板：应用信息与软件更新。 */
import { useEffect, useState, useMemo } from 'react'
import { motionEnabled, setMotion } from '../motion'
import { api } from '../api'
import { marked } from 'marked'
import DOMPurify from 'dompurify'

const fmtUptime = (s) => {
  if (s == null) return '—'
  const d = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600)
  const m = Math.floor((s % 3600) / 60)
  if (d) return `${d} 天 ${h} 时`
  if (h) return `${h} 时 ${m} 分`
  return `${m} 分`
}

// eslint-disable-next-line complexity
export default function SettingsView() {
  const [st, setSt] = useState(null)
  const [proc, setProc] = useState(null)
  const [busy, setBusy] = useState('')
  const [err, setErr] = useState('')
  const [hint, setHint] = useState('')
  const [motionOn, setMotionOn] = useState(motionEnabled())

  async function refresh() {
    try {
      const [s, p] = await Promise.all([
        api.updateStatus().catch(() => null),
        api.processInfo().catch(() => null),
      ])
      if (s) setSt(s)
      if (p) setProc(p)
    } catch (e) { setErr(e?.message || String(e)) }
  }

  useEffect(() => { refresh() }, [])

  async function run(name, fn, onOk) {
    setBusy(name); setErr(''); setHint('')
    try {
      await fn()
      if (onOk) onOk()
      await refresh()
    } catch (e) {
      setErr(e?.message || String(e))
    } finally { setBusy('') }
  }

  const state = st?.state || 'idle'

  // 版本说明是 Markdown 源文，必须渲染后再显示（此前直接 <pre> 输出，会露出 ** 与 ##）
  const html = useMemo(() => {
    if (!st?.notes) return ''
    try {
      return DOMPurify.sanitize(marked.parse(st.notes), { ADD_ATTR: ['target'] })
    } catch {
      return ''
    }
  }, [st?.notes])

  const label = {
    checking: '正在检查更新…',
    up_to_date: `已是最新版本（v${st?.current}）`,
    available: `发现新版本 v${st?.latest}`,
    downloading: `正在下载 ${st?.progress || 0}%`,
    ready: `已下载 v${st?.latest}，可重启更新`,
    needs_manual: `v${st?.latest} 需手动更新（跨代不兼容）`,
    dismissed: `新版本 v${st?.latest} 已忽略`,
    check_failed: `检查更新失败${st?.error ? '：' + st.error : ''}`,
    failed: `更新失败：${st?.error || '见 apply.log'}`,
  }[state] || `当前版本 v${st?.current || '—'}`

  return (
    <div className="mio-view settings-view">
      <div className="mio-head">
        <h2 className="mio-title">设置</h2>
        <button className="btn btn--ghost btn--xs" onClick={refresh}>刷新</button>
      </div>

      {err && <p className="update-banner__err">操作失败：{err}</p>}
      {hint && <p className="detail-muted">{hint}</p>}

      <h3 className="mio-sec">软件更新</h3>
      <div className="mio-cards">
        <div className="mio-card">
          <div className="mio-card__t">当前版本</div>
          <div className="mio-status is-ok mono">v{st?.current || '—'}</div>
        </div>
        <div className="mio-card">
          <div className="mio-card__t">状态</div>
          <div className="mio-status">{label}</div>
        </div>
        <div className="mio-card">
          <div className="mio-card__t">更新通道</div>
          <div className="mio-status mono">stable</div>
        </div>
      </div>

      <div className="settings-actions">
        <button className="btn btn--primary" disabled={!!busy || state === 'checking' || state === 'downloading'}
                onClick={() => run('check', () => api.updateCheck())}>
          {state === 'checking' ? '检查中…' : '检查更新'}
        </button>

        {state === 'available' && (
          <button className="btn btn--primary" disabled={!!busy}
                  onClick={() => run('download', () => api.updateDownload())}>
            下载 v{st?.latest}
          </button>
        )}
        {state === 'ready' && (
          <button className="btn btn--primary" disabled={!!busy}
                  onClick={() => run('apply', () => api.updateApply(),
                                     () => setHint('正在重启应用…'))}>
            重启并更新
          </button>
        )}
        {state === 'failed' && (
          <button className="btn btn--primary" disabled={!!busy}
                  onClick={() => run('download', () => api.updateDownload())}>
            重试下载
          </button>
        )}
        {['available', 'ready', 'needs_manual'].includes(state) && (
          <button className="btn btn--ghost" disabled={!!busy}
                  onClick={() => run('dismiss', () => api.updateDismiss())}>
            忽略此版本
          </button>
        )}
      </div>

      {st && st.notes && html && (
        <>
          <h3 className="mio-sec">版本说明</h3>
          <div className="md settings-notes" dangerouslySetInnerHTML={{ __html: html }} />
        </>
      )}
      {st && st.notes && !html && (
        <>
          <h3 className="mio-sec">版本说明</h3>
          <pre className="settings-notes">{st.notes}</pre>
        </>
      )}


      <h3 className="mio-sec">界面</h3>
      <table className="mio-table">
        <tbody>
          <tr>
            <td>动效（呼吸光圈 / 扫描条 / 过渡）</td>
            <td>
              <label style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}>
                <input
                  type="checkbox"
                  checked={motionOn}
                  onChange={(e) => { const v = e.target.checked; setMotion(v); setMotionOn(v) }}
                />
                <span>{motionOn ? '开' : '关'}</span>
              </label>
            </td>
          </tr>
        </tbody>
      </table>
      <p style={{ fontSize: 11.5, opacity: .6, margin: '6px 0 0', lineHeight: 1.6 }}>
        在没有 GPU 加速的环境（远程桌面 / 虚拟显示器 / 禁用硬件加速）下，持续动效会让界面每帧重绘，
        实测仅 2 个状态点就能占用一个多核。界面卡顿或 CPU 飙高时请关闭。
      </p>

      <h3 className="mio-sec">运行信息</h3>
      <table className="mio-table">
        <tbody>
          <tr><td>进程 PID</td><td className="mono">{proc?.pid ?? '—'}</td></tr>
          <tr><td>运行时长</td><td>{fmtUptime(proc?.uptime_seconds)}</td></tr>
          <tr><td>内存 (RSS)</td><td>{proc?.memory_rss_mb != null ? `${proc.memory_rss_mb} MB` : '—'}</td></tr>
          <tr><td>线程数</td><td>{proc?.threads ?? '—'}</td></tr>
        </tbody>
      </table>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { api } from '../api'

// eslint-disable-next-line complexity
export default function SideStatus() {
  const [summary, setSummary] = useState(null)
  const [collapsed, setCollapsed] = useState(false)
  useEffect(() => {
    let cancelled = false
    const fetch = () => api.boardSummary().then(d => { if (!cancelled) setSummary(d) }).catch(() => {})
    fetch()
    // 看板汇总改 30s（任务 613bc0ca · FR-5）：理由同 MissionBar。
    const t = setInterval(fetch, 30000)
    return () => { cancelled = true; clearInterval(t) }
  }, [])

  const q = summary?.ready_queue || []
  const running = summary?.running || []
  const alerts = summary?.alerts || []

  return (
    <aside className={`side-status${collapsed ? ' is-collapsed' : ''}`} aria-label="调度队列">
      <div className="side-status__head">
        <span className="side-status__title">调度队列</span>
        <button className="side-status__toggle" onClick={() => setCollapsed(v => !v)} aria-label={collapsed ? '展开' : '收起'}>
          {collapsed ? '›' : '‹'}
        </button>
      </div>
      {!collapsed && (
        <div className="side-status__body">
          {q.length > 0 ? (
            <div className="side-status__section">
              <div className="side-status__label">按优先级 · {q.length}</div>
              <ol className="side-status__list">
                {q.slice(0, 8).map(item => (
                  <li key={item.id} className="side-status__item" title={`${item.title} [P${item.priority}]`}>
                    <span className="side-status__p">P{item.priority}</span>
                    <span className="side-status__name">{item.title}</span>
                  </li>
                ))}
              </ol>
              {q.length > 8 && <div className="side-status__more">…还有 {q.length - 8} 个</div>}
            </div>
          ) : (
            <div className="side-status__empty">暂无排队</div>
          )}

          {running.length > 0 && (
            <div className="side-status__section">
              <div className="side-status__label">执行中 · {running.length}</div>
              <ul className="side-status__list">
