/**
 * 阶段推进对话框 —— 替代 window.prompt（Phase 2 C-4 / A3）。
 *
 * 原生 prompt 的问题：不可样式化、单行、无格式说明、无校验、无法展示任务上下文、
 * 移动端/键盘用户无焦点管理，且错误只能靠 alert 二次打断。
 *
 * 本组件负责：
 *  1. 展示「当前阶段 → 目标阶段」的上下文，说清这个阶段为什么必须提供产出物；
 *  2. 预填该阶段已有产出物（stageDocs.currentArtifact）；
 *  3. 行内校验与**浮层内**错误显示（不再由 App 层 ErrorBar 代劳，避免被遮罩盖住）；
 *  4. Esc 取消（走 overlayStack，只由栈顶响应）；打开即聚焦输入框。
 *
 * 2026-11-04 改版（用户反馈「不能让我去翻文件目录」）：
 *  5. done 阶段给「直接写结论 / 填文档路径」二选一——没有文档的任务不再被迫手填路径；
 *  6. 路径模式下把 GET /tasks/{id}/documents 的结果做成可点 chip（登记 + 工作区扫描），
 *     点一下自动填入；无候选时给出明确原因（未设置工作区 / 工作区无同类文档）。
 */
import { useEffect, useRef, useState } from 'react'
import { useOverlayStack } from '../lib/overlayStack'
import { STAGE_META } from '../constants'
import { api } from '../api'
import { REVIEW_PRESETS } from '../stageDocs'

// eslint-disable-next-line complexity
export default function StageAdvanceDialog({ task, nextStage, spec, onCancel, onConfirm, busy, error }) {
  const [value, setValue] = useState(() => spec?.initial || '')
  const inputRef = useRef(null)
  const [localErr, setLocalErr] = useState('')
  // 候选文档：来自 GET /tasks/{id}/documents（登记 doc_paths + 工作区扫描），免去翻目录
  const [docs, setDocs] = useState([])
  const [docsLoaded, setDocsLoaded] = useState(false)
  // 模式：'text' 写结论 / 'path' 填路径（仅 acceptsText 的阶段可切换）
  const [mode, setMode] = useState(spec?.acceptsText ? 'text' : 'path')
  const modeTouched = useRef(false)

  useOverlayStack(onCancel)
  useEffect(() => { inputRef.current?.focus() }, [])

  useEffect(() => {
    let alive = true
    if (!task?.id) { setDocsLoaded(true); return }
    api.getTaskDocuments(task.id)
      .then(d => { if (alive) setDocs((d && d.documents) || []) })
      .catch(() => { /* 拉不到就退回手填 */ })
      .finally(() => { if (alive) setDocsLoaded(true) })
    return () => { alive = false }
  }, [task?.id])

  const wantKind = spec?.kind
  const pickMatched = docs.filter(d => d.exists !== false && d.kind === wantKind).slice(0, 6)
  // 只在没有同类候选时才兜底展示其他文档，避免一屏无关文件
  const pickOthers = pickMatched.length === 0
    ? docs.filter(d => d.exists !== false && d.kind !== wantKind).slice(0, 4)
    : []

  // 有同类文档时默认切到「填路径」（点一下就有），用户手动切过就不再干预
  useEffect(() => {
    if (!spec?.acceptsText || modeTouched.current || !docsLoaded) return
    if (pickMatched.length > 0) setMode('path')
  }, [docsLoaded, pickMatched.length, spec?.acceptsText])

  const switchMode = (m) => {
    modeTouched.current = true
    setMode(m)
    setLocalErr('')
    if (m === 'text') inputRef.current?.focus()
  }

  const pick = (path) => { setValue(path); setLocalErr('') }

  // 后端可能返回的校验错误由外部传入，显示在浮层内部
  const shownError = localErr || error || ''

  // eslint-disable-next-line complexity
  const submit = (e) => {
    e?.preventDefault?.()
    const v = value.trim()
    if (!v) {
      setLocalErr(mode === 'text' ? '请先写审查结论' : '请填写或点选一份产出物')
      inputRef.current?.focus()
      return
    }
    if (spec?.acceptsText && mode === 'text' && v.length < 8) {
      setLocalErr('审查结论至少需要 8 个字符，请写清结论依据')
      inputRef.current?.focus()
      return
    }
    if (mode === 'path' && !/[\\/]/.test(v) && !/\.(md|markdown|txt|pdf)$/i.test(v)) {
      setLocalErr('这看起来不像文档路径；如果你是在写结论，请切到「直接写审查结论」')
      inputRef.current?.focus()
      return
    }
    setLocalErr('')
    onConfirm(v, mode)
  }

  const cur = STAGE_META[task?.stage]?.label || task?.stage || '当前阶段'
  const next = STAGE_META[nextStage]?.label || nextStage
  const hasWorkspace = !!(task?.workspace || '').trim()

  return (
    <div className="overlay" onMouseDown={(e) => { if (e.target === e.currentTarget) onCancel() }}>
      <div className="modal stage-advance" role="dialog" aria-modal="true" aria-label={`推进到${next}`}>
        <div className="modal__head">
          <h3 className="modal__title">推进到「{next}」</h3>
          <button className="modal__close" onClick={onCancel} aria-label="关闭">×</button>
        </div>

        <div className="stage-advance__ctx">
          <span className="chip chip--muted">{cur}</span>
          <span className="stage-advance__arrow" aria-hidden="true">→</span>
          <span className="chip chip--ok-soft">{next}</span>
          <span className="stage-advance__task" title={task?.title}>{task?.title}</span>
        </div>

        <form onSubmit={submit}>
          <label className="stage-advance__label" htmlFor="stage-artifact">
            此阶段要求产出物：{spec?.label}
          </label>

          {spec?.acceptsText && (
            <div className="stage-advance__modes" role="tablist" aria-label="产出物方式">
              <button
                type="button"
                role="tab"
                aria-selected={mode === 'text'}
                className={`stage-advance__mode${mode === 'text' ? ' is-on' : ''}`}
                onClick={() => switchMode('text')}
              >
                直接写审查结论
              </button>
              <button
                type="button"
                role="tab"
                aria-selected={mode === 'path'}
                className={`stage-advance__mode${mode === 'path' ? ' is-on' : ''}`}
                onClick={() => switchMode('path')}
              >
                填写 / 点选文档路径
              </button>
            </div>
          )}

          {spec?.acceptsText && mode === 'text' && (
            <div className="stage-advance__pick-row" style={{ marginBottom: 8 }}>
              {REVIEW_PRESETS.map((p, i) => (
                <button
                  key={i}
                  type="button"
                  className="stage-advance__pick"
                  onClick={() => { setValue(p.text); setLocalErr(''); inputRef.current?.focus() }}
                >
                  {p.label}
                </button>
              ))}
            </div>
          )}

          <textarea
            id="stage-artifact"
            ref={inputRef}
            className="stage-advance__input"
            rows={3}
            value={value}
            placeholder={mode === 'text'
              ? '点上方选项直接填，或自己写一句（≥8 字）'
              : (spec?.ph || '')}
            onChange={(e) => { setValue(e.target.value); setLocalErr('') }}
            onKeyDown={(e) => {
              if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') submit(e)
            }}
          />
          <p className="stage-advance__hint">
            {mode === 'text'
              ? '点选项自动填好结论（可再改），或自己写（≥8 字）。Ctrl+Enter 提交。'
              : '从下方已有文档点选，或手填仓库内路径。Ctrl+Enter 提交。'}
          </p>

          {mode === 'path' && (
            <div className="stage-advance__picks">
              {pickMatched.length > 0 || pickOthers.length > 0 ? (
                <>
                  <div className="stage-advance__picks-title">已有文档（点选填入，免翻目录）</div>
                  {pickMatched.length > 0 && (
                    <div className="stage-advance__pick-row">
                      {pickMatched.map(d => (
                        <button
                          key={d.rel_path}
                          type="button"
                          className={`stage-advance__pick${value === d.rel_path ? ' is-on' : ''}`}
                          title={d.rel_path}
                          onClick={() => pick(d.rel_path)}
                        >
                          <span className="stage-advance__pick-kind">{d.kind}</span>
                          <span className="stage-advance__pick-path">{d.rel_path}</span>
                        </button>
                      ))}
                    </div>
                  )}
                  {pickMatched.length === 0 && (
                    <>
                      <div className="stage-advance__picks-empty">
                        工作区里没找到「{wantKind}」类文档，下面是从其他类型里挑的，可借用。
                      </div>
                      <div className="stage-advance__pick-row" style={{ marginTop: 8 }}>
                        {pickOthers.map(d => (
                          <button
                            key={d.rel_path}
                            type="button"
                            className={`stage-advance__pick${value === d.rel_path ? ' is-on' : ''} is-dim`}
                            title={d.rel_path}
                            onClick={() => pick(d.rel_path)}
                          >
                            <span className="stage-advance__pick-kind">{d.kind}</span>
                            <span className="stage-advance__pick-path">{d.rel_path}</span>
                          </button>
                        ))}
                      </div>
                    </>
                  )}
                </>
              ) : docsLoaded ? (
                <div className="stage-advance__picks-empty">
                  {hasWorkspace
                    ? `工作区里没有可用的「${wantKind}」类文档。`
                    : '该任务未设置工作区，无法扫描已有文档。'}
                  {spec?.acceptsText
                    ? '建议切到「直接写审查结论」——一句话就能推进。'
                    : '请手填仓库内路径（需在 workspace 内，或填绝对路径）。'}
                </div>
              ) : null}
            </div>
          )}

          {shownError && <p className="stage-advance__err" role="alert">{shownError}</p>}

          <div className="stage-advance__actions">
            <button type="button" className="btn btn--ghost" onClick={onCancel}>取消</button>
            <button type="submit" className="btn btn--primary" disabled={busy}>
              {busy ? '推进中…' : '确认推进'}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { api } from '../api'
import { COMPOSITE_LABELS, LANES, STAGES, parseUtc } from '../constants'
import { Skeleton } from './Skeleton'

// 语义色唯一来源：ledger.css 的 CSS 变量（phase1 C3）。
// JS 只引用 var()，不写字面色值 —— light / 高对比档自动跟随。
const TONE_COLORS = {
  live: 'var(--live)',
  ok: 'var(--ok)',
  'ok-soft': 'color-mix(in srgb, var(--ok) 62%, var(--ink-faint))',
  warn: 'var(--warn)',
  danger: 'var(--danger)',
  info: 'var(--info)',
  neutral: 'var(--neutral)',
  muted: 'var(--ink-ghost)',
  dim: 'var(--ink-faint)',
}

/* ---------- 展示组件 ---------- */

// KPI 卡：数字默认中性，只有「异常结论」才上色（R2 V1）。
// sub 副行给上下文，让数字可解释，而不是孤立的大数。
function MetricCard({ label, value, tone, sub }) {
  return (
    <div className={`stats-metric stats-metric--${tone || 'dim'}`}>
      <span className="stats-metric__value">{value}</span>
      <span className="stats-metric__label">{label}</span>
      {sub && <span className="stats-metric__sub">{sub}</span>}
    </div>
  )
}

// 状态分布：单行堆叠条 + 图例。比 N 条独立横条紧凑得多，
// 且能一眼看出各状态占比；零值项不进条，但保留在图例里。
function StateStack({ entries }) {
  const total = entries.reduce((s, e) => s + e.value, 0)
  const visible = entries.filter(e => e.value > 0)
  return (
    <div className="stats-stack">
      <div className="stats-stack__bar" role="img"
           aria-label={`状态分布，共 ${total} 个任务`}>
        {visible.length === 0 && <div className="stats-stack__empty">暂无任务</div>}
        {visible.map(e => (
          <div key={e.label} className="stats-stack__seg"
               style={{ flexGrow: e.value, background: TONE_COLORS[e.tone] || 'var(--ink-faint)' }}
               title={`${e.label} ${e.value}（${total ? Math.round((e.value / total) * 100) : 0}%）`} />
        ))}
      </div>
      <ul className="stats-stack__legend">
        {entries.map(e => (
          <li key={e.label}>
            <i style={{ background: TONE_COLORS[e.tone] || 'var(--ink-faint)' }} />
            <span className="stats-stack__name">{e.label}</span>
            <span className="stats-stack__num mono">{e.value}</span>
          </li>
        ))}
      </ul>
    </div>
  )
}

// 离散统计项：label + 数字的小胶囊。用于阶段 / 复合状态 / 事件类型这类
// 「类目多、单值小」的数据 —— 全宽横条在这种数据下会变成一排灰线。
function Pill({ label, value, tone }) {
  return (
    <span className={`stats-pill stats-pill--${tone || 'dim'}`}>
      <span className="stats-pill__label">{label}</span>
      <span className="stats-pill__num mono">{value}</span>
    </span>
  )
}

// Catmull-Rom 转三次贝塞尔：硬折线在稀疏数据上是「三角形山峰」，
// 平滑后才像一条趋势。y 值 clamp 在绘图区内，避免贴底的 0 值序列被平滑出下凹。
function smoothPath(pts, minY, maxY) {
  const cl = (v) => Math.max(minY, Math.min(maxY, v))
  if (pts.length < 3) return pts.map((p, i) => `${i ? 'L' : 'M'}${p[0].toFixed(1)},${cl(p[1]).toFixed(1)}`).join(' ')
  let d = `M${pts[0][0].toFixed(1)},${cl(pts[0][1]).toFixed(1)}`
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)]
    const p1 = pts[i]
    const p2 = pts[i + 1]
    const p3 = pts[Math.min(pts.length - 1, i + 2)]
    d += ` C${(p1[0] + (p2[0] - p0[0]) / 6).toFixed(1)},${cl(p1[1] + (p2[1] - p0[1]) / 6).toFixed(1)}`
    d += ` ${(p2[0] - (p3[0] - p1[0]) / 6).toFixed(1)},${cl(p2[1] - (p3[1] - p1[1]) / 6).toFixed(1)}`
    d += ` ${p2[0].toFixed(1)},${cl(p2[1]).toFixed(1)}`
  }
  return d
}

function TrendChart({ data, outliers, days }) {
  if (!data || data.length === 0) return null

  const W = 640
  const H = 220
  const PAD = { top: 22, right: 20, bottom: 30, left: 40 }
  const iw = W - PAD.left - PAD.right
  const ih = H - PAD.top - PAD.bottom

  const maxVal = Math.max(1, ...data.flatMap(d => [d.created, d.completed, d.failed]))
  const n = data.length
  // 失败线只有真的有失败时才画：全 0 的失败线是一条横穿图表的红线，纯噪音
  const hasFailed = data.some(d => d.failed > 0)

  // 刻度取整到「好看的步长」（批量日已在数据层剔除，这里就是纯线性刻度）
  const rough = Math.max(1, maxVal) / 4
  const pow = Math.pow(10, Math.floor(Math.log10(rough)))
  const niceStep = [1, 2, 5, 10].map(m => m * pow).find(s => s >= rough) || pow * 10
  const tickMax = Math.max(1, Math.ceil(maxVal / niceStep) * niceStep)
  const ticks = Array.from({ length: Math.round(tickMax / niceStep) + 1 }, (_, i) => i * niceStep)

  const x = (i) => PAD.left + (n === 1 ? iw / 2 : (i / (n - 1)) * iw)
  const y = (v) => PAD.top + ih - (v / tickMax) * ih
  const axisY = PAD.top + ih

  const pts = (key) => data.map((d, i) => [x(i), y(d[key])])
  const line = (key) => smoothPath(pts(key), PAD.top, axisY)

  // 「创建」线下方渐变面积 + 平滑：给主系列体量感
  const area = `${line('created')} L${x(n - 1).toFixed(1)},${axisY.toFixed(1)} L${x(0).toFixed(1)},${axisY.toFixed(1)} Z`

  const colors = { created: 'var(--accent)', completed: 'var(--ok)', failed: 'var(--danger)' }

  // x 轴标签按密度采样：7 天全标，30 天隔 5 天，90 天隔 15 天；首尾必标
  const labelEvery = n <= 10 ? 1 : n <= 35 ? 5 : 15
  const showLabel = (i) => i % labelEvery === 0 || i === n - 1
  // hover 热区宽度随数据密度收缩；点只在稀疏时画（密了是一串噪点）
  const hoverW = Math.min(24, iw / n)
  const showDots = n <= 20

  return (
    <div className="stats-trend">
      <svg viewBox={`0 0 ${W} ${H}`} className="stats-trend__svg">
        <defs>
          <linearGradient id="gradCreated" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="var(--accent)" stopOpacity="0.26" />
            <stop offset="100%" stopColor="var(--accent)" stopOpacity="0" />
          </linearGradient>
        </defs>
        {ticks.map((v) => (
          <g key={v}>
            <line x1={PAD.left} x2={W - PAD.right} y1={y(v)} y2={y(v)}
                  stroke={v === 0 ? 'var(--ink-ghost)' : 'var(--line)'}
                  strokeWidth={v === 0 ? 1 : 0.5} opacity={v === 0 ? 0.5 : 1} />
            <text x={PAD.left - 6} y={y(v) + 4} textAnchor="end" fontSize="9" fill="var(--ink-faint)">{v}</text>
          </g>
        ))}
        {data.map((d, i) => (
          <g key={i}>
            <rect x={x(i) - hoverW / 2} y={PAD.top} width={hoverW} height={ih} fill="transparent">
              <title>{`${d.date}: 创建 ${d.created} · 完成 ${d.completed} · 失败 ${d.failed}`}</title>
            </rect>
            {showLabel(i) && (
              <text x={x(i)} y={H - 10} textAnchor="middle" fontSize="9" fill="var(--ink-faint)">{d.date.slice(5)}</text>
            )}
          </g>
        ))}
        <path d={area} fill="url(#gradCreated)" />
        <path d={line('created')} fill="none" stroke={colors.created} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
        <path d={line('completed')} fill="none" stroke={colors.completed} strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" opacity="0.9" />
        {hasFailed && (
          <path d={line('failed')} fill="none" stroke={colors.failed} strokeWidth="1.5"
                strokeDasharray="4 3" strokeLinecap="round" opacity="0.85" />
        )}
        {showDots && data.map((d, i) => (
          ['created', 'completed'].map((key) => (
            <circle key={`${key}-${i}`} cx={x(i)} cy={y(d[key])} r="3" fill={colors[key]} stroke="var(--bg)" strokeWidth="1.5" />
          ))
        ))}
        {hasFailed && data.map((d, i) =>
          d.failed > 0 ? (
            <circle key={`failed-${i}`} cx={x(i)} cy={y(d.failed)} r={showDots ? 2.5 : 2} fill={colors.failed} stroke="var(--bg)" strokeWidth="1.2" />
          ) : null
        )}
      </svg>
      <div className="stats-trend__legend">
        <span><i style={{ background: colors.created }} />创建</span>
        <span><i style={{ background: colors.completed }} />完成</span>
        {hasFailed && <span><i style={{ background: 'transparent', borderTop: `2px dashed ${colors.failed}`, height: 0, width: 12 }} />失败</span>}
        <span className="stats-trend__range-hint">近 {days} 日</span>
      </div>
      {outliers?.length > 0 && (
        <p className="stats-trend__footnote">
          已剔除批量日 {outliers.map(o => `${o.date.slice(5)}（${o.created} 任务）`).join('、')}——非日常节奏，不参与刻度
        </p>
      )}
    </div>
  )
}

