// eslint-disable-next-line complexity
export default function StatsView() {
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [metrics, setMetrics] = useState(null)
  const [trendTasks, setTrendTasks] = useState(null)
  const [trendDays, setTrendDays] = useState(30)
  const [report, setReport] = useState(null)

  useEffect(() => {
    api.statsOverview().then(setData).catch(() => setData(null)).finally(() => setLoading(false))
    api.metrics().then(setMetrics).catch(() => {})
    api.observabilityReport().then(setReport).catch(() => {})
    // 任务列表只拉一次；趋势按 trendDays 在前端重新聚合，切范围不再请求
    api.listTasks({ cancelled: 'true' }).then(setTrendTasks).catch(() => {})
  }, [])

  // 近 N 日创建/完成/失败聚合。
  // 批量日剔除：某天一次性批量创建的任务（如 2026-10-19 历史 creativity 实验
  // 留下的 1483 个「想法评审」）会把 y 轴尺度拉爆，日常节奏全部压平。
  // 单日创建数 > max(30, 次大值×3) 视为批量事件，剔除出趋势序列并在脚注说明。
  // eslint-disable-next-line complexity
  const { series: trendSeries, outliers } = useMemo(() => {
    if (!trendTasks) return { series: null, outliers: [] }
    const days = []
    for (let i = trendDays - 1; i >= 0; i--) {
      const d = new Date()
      d.setDate(d.getDate() - i)
      days.push(d.toISOString().slice(0, 10))
    }
    const agg = days.map((date) => ({ date, created: 0, completed: 0, failed: 0 }))
    const idx = Object.fromEntries(days.map((d, i) => [d, i]))
    for (const t of trendTasks) {
      const cd = t.created_at ? parseUtc(t.created_at)?.toISOString().slice(0, 10) : null
      if (cd && cd in idx) agg[idx[cd]].created++
      const dd = t.completed_at ? parseUtc(t.completed_at)?.toISOString().slice(0, 10) : null
      if (dd && dd in idx) {
        if (t.state === 'completed') agg[idx[dd]].completed++
        if (t.state === 'failed') agg[idx[dd]].failed++
      }
    }
    const createdSorted = agg.map(d => d.created).sort((a, b) => b - a)
    const threshold = Math.max(30, (createdSorted[1] || 0) * 3)
    const outliers = agg.filter(d => d.created > threshold)
    return {
      series: outliers.length ? agg.filter(d => d.created <= threshold) : agg,
      outliers: outliers.map(o => ({ date: o.date, created: o.created })),
    }
  }, [trendTasks, trendDays])

  if (loading) return (
    <div className="stats-view">
      <div className="stats-header">
        <h2>统计</h2>
        <span className="stats-header__total">加载中…</span>
      </div>
      <div className="stats-bars">
        <Skeleton variant="box" height="60px" />
        <Skeleton variant="box" height="60px" />
        <Skeleton variant="box" height="60px" />
      </div>
    </div>
  )
  if (!data) return <div className="stats-loading">无法加载统计</div>

  const { composite_counts, by_state, by_stage, event_by_type, total_tasks, task_events_count } = data

  const compositeEntries = Object.entries(composite_counts)
    .map(([key, count]) => {
      const [state, stage] = key.split(',')
      const meta = COMPOSITE_LABELS[key] || { label: key, tone: 'dim' }
      return { key, state, stage, count, ...meta }
    })
    .sort((a, b) => b.count - a.count)

  const scope = report?.tasks?.scope
  const scopeState = Object.fromEntries(
    Object.entries(scope?.by_state || by_state || {})
      .map(([k, v]) => [String(k).toLowerCase(), v])
  )
  const completedNow = scopeState['completed'] || 0
  const scopeTotal = scope?.total ?? 0
  const successRate = scope?.success_rate != null
    ? Math.round(scope.success_rate * 100)
    : scopeTotal > 0
      ? Math.round((completedNow / scopeTotal) * 100)
      : 0
  const asOf = scope?.as_of
    ? new Date(scope.as_of).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    : null
  const agentsOnline = metrics?.taskhub_agents_online?.find(a => a.label === 'online')?.count ?? 0

  const stateEntries = LANES.map(l => ({ label: l.label, value: scopeState[l.id] || 0, tone: l.tone }))

  return (
    <div className="stats-view">
      <header className="stats-header">
        <h2>统计概览</h2>
        <span className="stats-header__total mono">
          当前 {scope?.total ?? '—'} 任务 · 历史 {total_tasks} · {task_events_count} 事件
          {asOf ? ` · as of ${asOf}` : ''}
        </span>
      </header>

      {/* KPI 语义规则（R2 V1）：数字默认中性，只有「数字本身是结论且异常」才上色。
          副行给出可解释的上下文，数字不再是孤立大数。 */}
      <div className="stats-metrics">
        <MetricCard label="当前交付面" value={scope?.total ?? '—'} tone="dim"
                    sub={`历史全量 ${total_tasks}`} />
        <MetricCard label="已完成（当前）" value={completedNow} tone="dim"
                    sub={`${scopeTotal ? Math.round((completedNow / scopeTotal) * 100) : 0}% 交付面`} />
        <MetricCard label="Agent 在线" value={agentsOnline}
                    tone={agentsOnline > 0 ? 'dim' : 'danger'}
                    sub={agentsOnline > 0 ? '调度正常' : '无消费者 · 任务不会被领取'} />
        <MetricCard label="成功率（当前）" value={`${successRate}%`}
                    tone={successRate < 50 ? 'danger' : successRate < 80 ? 'warn' : 'dim'}
                    sub={`${completedNow} / ${scopeTotal || '—'} 完成`} />
      </div>

      {/* 主区：趋势图 + 状态分布并排，消除单列堆叠的纵向空旷 */}
      <div className="stats-main">
        <section className="stats-section stats-section--panel">
          <div className="stats-section__head">
            <h3>任务趋势（历史全量）</h3>
            <div className="seg-range" role="group" aria-label="趋势时间范围">
              {[7, 30, 90].map(d => (
                <button key={d} type="button"
                        className={`seg-range__btn${trendDays === d ? ' is-active' : ''}`}
                        onClick={() => setTrendDays(d)}>{d} 日</button>
              ))}
            </div>
          </div>
          <TrendChart data={trendSeries} outliers={outliers} days={trendDays} />
        </section>
        <section className="stats-section stats-section--panel">
          <h3>状态分布（当前交付面）</h3>
          <StateStack entries={stateEntries} />
        </section>
      </div>

      {/* 类目型数据改用胶囊：全宽横条在「类目多、单值小」时是一排灰线 */}
      <div className="stats-cols">
        <section className="stats-section stats-section--panel">
          <h3>阶段分布</h3>
          <div className="stats-pills">
            {STAGES.filter(s => (by_stage[s.id] || 0) > 0 || ['ready', 'implementing', 'review'].includes(s.id)).map(s => (
              <Pill key={s.id} label={s.label} value={by_stage[s.id] || 0} tone={s.tone} />
            ))}
          </div>
        </section>
        <section className="stats-section stats-section--panel">
          <h3>复合状态 · {compositeEntries.length} 种</h3>
          <div className="stats-pills">
            {compositeEntries.slice(0, 12).map(e => (
              <Pill key={e.key} label={e.label} value={e.count} tone={e.tone} />
            ))}
            {compositeEntries.length > 12 && (
              <span className="stats-pills__more">其余 {compositeEntries.length - 12} 种 · 合计 {compositeEntries.slice(12).reduce((s, e) => s + e.count, 0)}</span>
            )}
          </div>
        </section>
      </div>

      {(Object.keys(event_by_type).length > 0 || metrics) && (
        <section className="stats-section stats-section--panel">
          <h3>系统健康{Object.keys(event_by_type).length > 0 ? ` · ${task_events_count} 事件` : ''}</h3>
          <div className="stats-pills">
            {metrics && (() => {
              const up = metrics.taskhub_uptime_seconds || 0
              return <Pill label="运行时间" value={up >= 3600 ? `${Math.round(up / 3600)}h` : `${Math.max(1, Math.round(up / 60))}m`} tone="dim" />
            })()}
            {(metrics?.taskhub_agents_online || []).filter(a => a.count > 0).map(a => (
              <Pill key={a.label} label={`Agent ${a.label}`} value={a.count} tone={a.label === 'online' ? 'ok' : 'dim'} />
            ))}
            {Object.entries(event_by_type).sort((a, b) => b[1] - a[1]).map(([type, count]) => (
              <Pill key={type} label={type} value={count} tone="dim" />
            ))}
          </div>
        </section>
      )}
    </div>
  )
}

import { useRef } from 'react'
import { prio, fmtDur, fmtAgo, fmtDate, LANES, agMono, agColor, compositeLabel } from '../constants'

// eslint-disable-next-line complexity
export default function TaskCard({ task, index, onCancel, onDragStart, onOpen, onMove, canDrag = true }) {
  const moved = useRef(false)
  const meta = { 'queued': 'dim', 'claimed': 'dim', 'running': 'live', 'retrying': 'warn', 'completed': 'dim', 'failed': 'danger' }[task.state] || 'dim'
  const p = prio(task.priority)
  const attempts = Math.max(1, task.max_retries ?? 3)
  const done = Math.min(attempts, task.attempt ?? 0)
  const ac = task.target_agent_type && agColor(task.target_agent_type)

  const klass = [
    'task',
    'mag',
    canDrag ? '' : 'is-static',
    meta === 'live' ? 'is-running' : '',
    meta === 'warn' ? 'is-retrying' : '',
    meta === 'danger' ? 'is-failed' : '',
  ].filter(Boolean).join(' ')

  const open = () => onOpen && onOpen(task)

  const onKey = (e) => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); open(); return }
    if (!canDrag || !e.altKey || (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight')) return
    const i = LANES.findIndex(l => l.id === task.state)
    const target = e.key === 'ArrowLeft' ? LANES[i - 1] : LANES[i + 1]
    if (target) { e.preventDefault(); onMove && onMove(task.id, target.id) }
  }

  const onMouseMove = (e) => {
    const el = e.currentTarget
    const r = el.getBoundingClientRect()
    el.style.setProperty('--mx', ((e.clientX - r.left) / r.width - 0.5) * 2)
    el.style.setProperty('--my', ((e.clientY - r.top) / r.height - 0.5) * 2)
  }

  const onMouseLeave = (e) => {
    e.currentTarget.style.removeProperty('--mx')
    e.currentTarget.style.removeProperty('--my')
  }

  return (
    <article
      className={klass}
      style={{ '--i': index }}
      draggable={canDrag}
      tabIndex={0}
      role="button"
      aria-label={canDrag
        ? `任务 ${task.title}，状态 ${task.state}。回车查看详情，Alt+方向键移动`
        : `任务 ${task.title}，状态 ${task.state}。回车查看详情`}
      onDragStart={e => { if (!canDrag) return; moved.current = true; e.dataTransfer.effectAllowed = 'move'; onDragStart && onDragStart(task.id) }}
      onDragEnd={() => onDragStart && onDragStart(null)}
      onClick={() => { if (moved.current) { moved.current = false; return } open() }}
      onKeyDown={onKey}
      onMouseMove={onMouseMove}
      onMouseLeave={onMouseLeave}
    >
      <div className="task__top">
        <h4 className="task__title">{task.title}</h4>
        <span className="task__chev" aria-hidden="true">›</span>
        {(task.state === 'queued' || task.state === 'claimed' || task.state === 'retrying') && (
          <button
            className="task__del"
            title="取消任务"
            aria-label={`取消任务 ${task.title}`}
            onClick={e => { e.stopPropagation(); onCancel && onCancel(task.id) }}
          >×</button>
        )}
      </div>

      {task.description && <p className="task__desc">{task.description}</p>}

      <div className="task__meta">
        {/* 主行：只保留 4 个有决策价值的 chip（ID / 复合状态 / 优先级 / agent） */}
        <span className="chip chip--id">{task.id}</span>
        <span className={`chip chip--composite chip--${compositeLabel(task.state, task.stage || 'ready').tone}`}>{compositeLabel(task.state, task.stage || 'ready').label}</span>
        <span className={`chip${p.p >= 3 ? ' chip--p3' : ''}${p.p === 2 ? ' chip--p2' : ''}`}>{p.label}</span>
        {task.target_agent_type ? (
          <span className="task__agent" title={task.target_agent_type}>
            <span className="agent-mono" style={{ background: ac.bg, borderColor: ac.fg, color: ac.fg }}>{agMono(task.target_agent_type)}</span>
            {task.target_agent_type}
          </span>
        ) : (
          <span className="chip chip--agent">任意 agent</span>
        )}
      </div>

      {/* 弱行：项目/标签/依赖/到期为次要信息，去边框、纯文字，不再与状态 chip 抢视觉权重 */}
      {(task.labels?.length > 0 || task.due_at || task.project || task.depends_on) && (
        <div className="task__badges">
          {task.depends_on && <span className="tag-weak" title="依赖任务">↳ {task.depends_on}</span>}
          {task.project && <span className="tag-weak">{task.project}</span>}
          {(() => {
            const ls = (task.labels || []).filter(l => !l.startsWith('cron:'))
            const shown = ls.slice(0, 2)
            const rest = ls.length - shown.length
            return (<>
              {shown.map(l => <span key={l} className="tag-weak">#{l}</span>)}
              {rest > 0 && <span className="tag-weak" title={ls.slice(2).join('、')}>+{rest}</span>}
            </>)
          })()}
          {(task.labels || []).some(l => l.startsWith('cron:')) && (
            <span className="chip chip--cron" title="由定时任务创建">⏱ 定时</span>
          )}
          {task.due_at && <span className="chip chip--due" title="计划完成时间">⏰ {fmtDate(task.due_at)}</span>}
        </div>
      )}

      <div className="task__foot">
        <span>{fmtDur(task.est_duration_min)}<span className="task__ago" title={fmtDate(task.created_at)}> · {fmtAgo(task.created_at)}</span></span>
        <span className="task__attempt" title={`尝试 ${done}/${attempts}`}>
          {Array.from({ length: attempts }).map((_, i) => (
            <span key={i} className={`attempt-dot${i < done ? ' on' : ''}`} />
          ))}
        </span>
      </div>

      {meta === 'live' && <span className="task__live" aria-hidden="true" />}
    </article>
  )
}

import { useEffect, useMemo, useRef, useState } from 'react'
import { STATE_META, STAGE_META, prio, fmtDur, fmtDate, compositeLabel, parseUtc } from '../constants'
import { api } from '../api'
import DependencyGraph from './DependencyGraph'
import WorkstreamPanel from './WorkstreamPanel'
import { useOverlayStack } from '../lib/overlayStack'

const tone = (s) => STATE_META[s]?.tone || 'dim'
const ACTIVE = ['queued', 'claimed', 'running', 'retrying']

const docKindList = (task) => {
  const dp = (task && task.doc_paths) || {}
  const kinds = Object.keys(dp)
  if (!kinds.length && task) {
    if (task.spec_path) kinds.push('spec')
    if (task.plan_path) kinds.push('plan')
  }
  return kinds
}

const DISC_GROUPS = [
  { id: 'brainstorming', label: '需求理解' },
  { id: 'design',        label: '设计评审' },
  { id: 'planning',      label: '计划评审' },
  { id: 'review',        label: '审查验收' },
  { id: 'other',         label: '其他' },
]
const DISC_STAGE_LABEL = {
  brainstorming: '需求理解', design: '设计', planning: '计划',
  ready: '待执行', implementing: '执行中', review: '审查', done: '完成',
}
const discGroupId = (s) => DISC_GROUPS.some(g => g.id === s) ? s : 'other'
const discStageLabel = (s) => DISC_STAGE_LABEL[s] || s || '—'

function scheduleOf(t) {
  if (t.schedule_type === 'cron') return t.cron_expr || 'cron'
  if (t.run_at) return fmtDate(t.run_at)
  return '立即执行'
}

// 执行历史类型 → 中文标签 + 配色（未知类型原样展示）
const HIST_TYPE_META = {
  requirement:  { label: '需求定稿',   tone: 'live' },
  feasibility:  { label: '可行性调研', tone: 'ok-soft' },
  result:       { label: '执行进展',   tone: 'ok' },
  verification: { label: '验证',       tone: 'ok' },
  discussion:   { label: '讨论',       tone: 'muted' },
  review:       { label: '评审',       tone: 'warn' },
  plan:         { label: '计划',       tone: 'muted' },
  design:       { label: '设计',       tone: 'muted' },
  created:      { label: '创建',       tone: 'muted' },
  claimed:      { label: '认领',       tone: 'live' },
  heartbeat:    { label: '心跳',       tone: 'muted' },
  retry:        { label: '重试',       tone: 'warn' },
  error:        { label: '错误',       tone: 'danger' },
  failure:      { label: '失败',       tone: 'danger' },
  done:         { label: '完成',       tone: 'ok' },
  cancelled:    { label: '取消',       tone: 'muted' },
  // 窄门禁（d468e633 FR-5）：提交被拦截
  rejected:     { label: '已拦截',     tone: 'danger' },
}

const HIST_TEXT_KEYS = ['raw', 'content', 'text', 'message', 'summary', 'result', 'detail', 'note']

// payload 落库时是 JSON 字符串，常见形态：
//   '{"raw": "…\\u9700…"}' / '"…中文…"' / 嵌套双层编码 / 纯文本
// 逐层解包 + 解转义，还原成人能直接读的文字。
// eslint-disable-next-line complexity
function histPayload(p) {
  if (p == null) return { text: '', json: false }
  let v = p
  for (let i = 0; i < 4 && typeof v === 'string'; i++) {
    const s = v.trim()
    if (!(s.startsWith('{') || s.startsWith('[') || s.startsWith('"'))) break
    try {
      v = JSON.parse(s)
    } catch {
      break
    }
  }
  if (v && typeof v === 'object' && !Array.isArray(v)) {
    const key = HIST_TEXT_KEYS.find(k => typeof v[k] === 'string' && v[k].trim())
    if (key) {
      v = v[key]
    } else {
      return { text: JSON.stringify(v, null, 2), json: true }
    }
  } else if (Array.isArray(v)) {
    return { text: JSON.stringify(v, null, 2), json: true }
  }
  let s = String(v)
  // JSON 解析失败时残留的 \uXXXX 转义：补引号/换行后再按 JSON 解一次
  if (/\\u[0-9a-fA-F]{4}/.test(s)) {
    try {
      s = JSON.parse(`"${s.replace(/\r/g, '\\r').replace(/\n/g, '\\n').replace(/"/g, '\\"')}"`)
    } catch {
      s = s.replace(/\\u([0-9a-fA-F]{4})/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
    }
  }
  return { text: s.trim(), json: false }
}

// 验收标准按行拆成可扫读列表；单行则整段展示
function acceptanceLines(text) {
  if (!text) return []
  return String(text)
    .split(/\r?\n/)
    .map(s => s.replace(/^[\s]*[-*•·]\s*/, '').replace(/^\d+[.)、]\s*/, '').trim())
    .filter(Boolean)
}

const STAGE_FLOW = ['brainstorming', 'design', 'planning', 'ready', 'implementing', 'review', 'done']

function completionOf(task) {
  const subs = task.subtasks || []
  if (subs.length > 0) {
    const done = subs.filter(s => s.status === 'done').length
    return { pct: Math.round(done / subs.length * 100), label: `${done}/${subs.length}`, source: '子任务' }
  }
  const sidx = STAGE_FLOW.indexOf(task.stage)
  if (sidx >= 0) {
    return {
      pct: Math.round((sidx + 1) / STAGE_FLOW.length * 100),
      label: `${sidx + 1}/${STAGE_FLOW.length}`,
      source: '阶段',
    }
  }
  if (task.state === 'completed') return { pct: 100, label: '完成', source: '状态' }
  if (task.state === 'failed') return { pct: 0, label: '失败', source: '状态' }
  return { pct: 0, label: '—', source: '—' }
}

const TAB_DEFS = [
  { id: 'blockers', label: '就绪度' },
  { id: 'workstream', label: '工作流' },
  { id: 'deps',     label: '依赖' },
  { id: 'subtasks', label: '清单' },
