          </div>
        </div>
      )}

      {loading ? (
        <div className="skeleton" />
      ) : filtered.length === 0 ? (
        <div className="empty-state">暂无模板</div>
      ) : (
        <div className="tpl-grid">
          {/* eslint-disable-next-line complexity */}
          {filtered.map(t => (
            <div key={t.id} className="tpl-card" onClick={() => setDetail(detail?.id === t.id ? null : t)}>
              <div className="tpl-card__head">
                <span className="tpl-card__title">{t.title}</span>
                {t.category && <span className="tpl-card__cat">{t.category}</span>}
              </div>
              {t.description && <div className="tpl-card__desc">{t.description}</div>}
              <div className="tpl-card__meta">
                {t.target_agent_type && <span className="tpl-card__agent">{t.target_agent_type}</span>}
                <span className="tpl-card__dur">{t.est_duration_min}min</span>
                <span className="tpl-card__time">{fmtAgo(t.created_at)}</span>
                <span className="tpl-card__actions">
                  <button className="btn btn--ghost btn--xs" onClick={e => { e.stopPropagation(); openUse(t) }} title="创建任务">＋任务</button>
                  <button className="btn btn--ghost btn--xs" onClick={e => { e.stopPropagation(); setEditing(t); setMode('edit') }} title="编辑">✎</button>
                  <button className="btn btn--ghost btn--xs" onClick={e => { e.stopPropagation(); remove(t.id) }} title="删除">🗑</button>
                </span>
              </div>
              {detail?.id === t.id && (
                <div className="tpl-card__detail">
                  <div className="tpl-card__detail-row"><b>验收标准：</b>{t.acceptance_criteria || '—'}</div>
                  <div className="tpl-card__detail-row"><b>文件模板：</b>{(t.files_template || []).join(', ') || '—'}</div>
                  <div className="tpl-card__detail-row"><b>产出物：</b>{(t.deliverables_template || []).join(', ') || '—'}</div>
                  <div className="tpl-card__detail-row">
                    <b>版本：</b>v{t.version}
                    <button className="btn btn--ghost btn--xs" style={{ marginLeft: 8 }} onClick={e => { e.stopPropagation(); toggleVersions(t) }}>版本历史</button>
                  </div>
                  {versions?.tplId === t.id && (
                    <div className="tpl-versions">
                      {verBusy && <div className="tpl-versions__loading">加载中…</div>}
                      {!verBusy && versions.list.length === 0 && <div className="tpl-versions__empty">暂无历史版本</div>}
                      {!verBusy && versions.list.map(v => (
                        <div key={v.id} className="tpl-version-row">
                          <span className="tpl-version-row__v">v{v.version}</span>
                          <span className="tpl-version-row__desc">{v.description || '—'}</span>
                          <span className="tpl-version-row__by">{v.created_by || '—'}</span>
                          <button className="btn btn--ghost btn--xs" disabled={verBusy} onClick={e => { e.stopPropagation(); restore(t, v.version) }}>回滚</button>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react'
import { prio, fmtDur } from '../constants'
import { computeCPM } from '../cpm'

const STAGE_TONE = {
  done: 'ok', cancelled: 'dim', review: 'live',
  implementing: 'live', ready: 'dim', planning: 'dim',
  design: 'dim', brainstorming: 'dim',
}

const isDone = t => t.state === 'completed' || t.stage === 'done'
const isClosed = t => isDone(t) || t.stage === 'cancelled' || t.state === 'cancelled'
const blockedBy = (t, pool) => (t.depends_on || []).some(d => {
  const dep = pool.find(x => x.id === d)
  return dep && !isClosed(dep)
})

function kahnLayers(tasks) {
  const byId = Object.fromEntries(tasks.map(t => [t.id, t]))
  const succ = {}
  tasks.forEach(t => { succ[t.id] = [] })
  const indegree = {}
  const outdegree = {}
  tasks.forEach(t => { indegree[t.id] = 0; outdegree[t.id] = 0 })
  tasks.forEach(t => {
    ;(t.depends_on || []).forEach(d => {
      if (!byId[d]) return
      indegree[t.id] += 1
      outdegree[d] += 1
      succ[d].push(t.id)
    })
  })
  const depth = {}
  const layers = []
  let frontier = tasks.filter(t => (indegree[t.id] || 0) === 0).map(t => t.id)
  let d = 0
  while (frontier.length) {
    const next = []
    frontier.forEach(id => {
      depth[id] = d
      layers.push(byId[id])
      ;(succ[id] || []).forEach(child => {
        indegree[child] -= 1
        if (indegree[child] === 0) next.push(child)
      })
    })
    frontier = next
    d += 1
  }
  const grouped = {}
  tasks.forEach(t => {
    const dd = depth[t.id]
    if (dd === undefined) return
    ;(grouped[dd] = grouped[dd] || []).push(t)
  })
  const layerList = Object.keys(grouped).sort((a, b) => a - b).map(k => grouped[k])
  return { layers: layerList, meta: { depth, indegree, outdegree } }
}

/** 无向连通分量：共享依赖视为同簇（谁的链和谁的链连在一起）。 */
function connectedComponents(tasks) {
  const byId = Object.fromEntries(tasks.map(t => [t.id, t]))
  const adj = {}
  tasks.forEach(t => { adj[t.id] = adj[t.id] || [] })
  tasks.forEach(t => {
    ;(t.depends_on || []).forEach(d => {
      if (!byId[d]) return
      adj[t.id].push(d)
      adj[d] = adj[d] || []
      adj[d].push(t.id)
    })
  })
  const seen = new Set()
  const out = []
  tasks.forEach(t => {
    if (seen.has(t.id)) return
    seen.add(t.id)
    const stack = [t.id]
    const ids = []
    while (stack.length) {
      const cur = stack.pop()
      ids.push(cur)
      ;(adj[cur] || []).forEach(n => { if (!seen.has(n)) { seen.add(n); stack.push(n) } })
    }
    out.push(ids.map(id => byId[id]))
  })
  return out
}

function clusterStat(ts) {
  const sorted = [...ts].sort((a, b) => String(a.id).localeCompare(String(b.id)))
  const cpm = computeCPM(ts)
  const { layers } = kahnLayers(ts)
  const roots = ts.filter(t => !(t.depends_on || []).some(d => ts.some(x => x.id === d)))
  return {
    key: sorted[0].id,
    tasks: ts,
    cpm,
    layerCount: layers.length,
    doneCount: ts.filter(isDone).length,
    blocked: ts.filter(t => blockedBy(t, ts)).length,
    roots,
  }
}

// eslint-disable-next-line complexity, max-lines-per-function
export default function TopoView({ tasks, onOpen }) {
  const [hoveredId, setHoveredId] = useState(null)
  const [showAll, setShowAll] = useState(false)
  const [focusId, setFocusId] = useState(null)
  const [hideIsolated, setHideIsolated] = useState(true)
  const [clusterKey, setClusterKey] = useState(null)
  const [query, setQuery] = useState('')
  const wrapRef = useRef(null)
  const nodeRefs = useRef(new Map())
  const [edges, setEdges] = useState([])

  // 有依赖关系（有前置或有后继）的任务
  const linkedIds = useMemo(() => {
    const s = new Set()
    tasks.forEach(t => {
      if ((t.depends_on || []).length) s.add(t.id)
      ;(t.depends_on || []).forEach(d => s.add(d))
    })
    return s
  }, [tasks])

  const visibleTasks = useMemo(
    () => (hideIsolated ? tasks.filter(t => linkedIds.has(t.id)) : tasks),
    [tasks, hideIsolated, linkedIds])

  const clusters = useMemo(() => {
    const cs = connectedComponents(visibleTasks).map(clusterStat)
    cs.sort((a, b) => b.tasks.length - a.tasks.length)
    return cs
  }, [visibleTasks])

  const active = clusterKey
    ? (clusters.find(c => c.key === clusterKey) || null)
    : (clusters.length === 1 ? clusters[0] : null)
  // 必须 memo：否则 [] 每次渲染都是新引用 → useLayoutEffect 反复触发 → setEdges 死循环（React #185）
  const detailTasks = useMemo(() => (active ? active.tasks : []), [active])

  const { layers } = useMemo(() => kahnLayers(detailTasks), [detailTasks])
  const cpm = useMemo(() => computeCPM(detailTasks), [detailTasks])
  const critIds = useMemo(() => {
    const s = new Set()
    const paths = showAll ? cpm.allCriticalPaths : cpm.allCriticalPaths.slice(0, 1)
    paths.forEach(p => p.forEach(id => s.add(id)))
    return s
  }, [cpm, showAll])

  const placed = useMemo(() => new Set(layers.flat().map(t => t.id)), [layers])
  const dropped = detailTasks.filter(t => !placed.has(t.id))
  const depCount = tasks.filter(t => (t.depends_on || []).length > 0).length

  // 聚焦/悬停链路（上下游闭包，限本簇）
  const activeId = focusId || hoveredId
  const chain = useMemo(() => {
    if (!activeId) return null
    const byId = Object.fromEntries(detailTasks.map(t => [t.id, t]))
    const out = new Set()
    const up = [activeId]
    while (up.length) {
      const cur = byId[up.pop()]
      ;((cur && cur.depends_on) || []).forEach(d => {
        if (d !== activeId && byId[d] && !out.has(d)) { out.add(d); up.push(d) }
      })
    }
    const kids = {}
    detailTasks.forEach(t => (t.depends_on || []).forEach(d => { (kids[d] = kids[d] || []).push(t.id) }))
    const down = [activeId]
    while (down.length) {
      const cur = down.pop()
      ;(kids[cur] || []).forEach(c => {
        if (c !== activeId && !out.has(c)) { out.add(c); down.push(c) }
      })
    }
    return out
  }, [activeId, detailTasks])

  // 连线测量
  const measure = () => {
    const wrap = wrapRef.current
    if (!wrap) return
    const base = wrap.getBoundingClientRect()
    const byId = Object.fromEntries(detailTasks.map(t => [t.id, t]))
    const es = []
    detailTasks.forEach(t => {
      const el = nodeRefs.current.get(t.id)
      if (!el) return
      const r = el.getBoundingClientRect()
      ;(t.depends_on || []).forEach(did => {
        if (!byId[did]) return
        const de = nodeRefs.current.get(did)
        if (!de) return
        const dr = de.getBoundingClientRect()
        es.push({
          key: `${did}->${t.id}`,
          from: did, to: t.id,
          x1: dr.left - base.left + dr.width / 2, y1: dr.bottom - base.top,
          x2: r.left + r.width / 2, y2: r.top - base.top,
        })
      })
    })
    setEdges(es)
  }

  useLayoutEffect(() => { measure() }, [detailTasks, showAll])
  useEffect(() => {
    const wrap = wrapRef.current
    if (!wrap) return undefined
    let ro = null
    if (typeof ResizeObserver !== 'undefined') {
      ro = new ResizeObserver(() => measure())
      ro.observe(wrap)
    }
    const onWin = () => measure()
    window.addEventListener('resize', onWin)
    return () => {
      if (ro) ro.disconnect()
      window.removeEventListener('resize', onWin)
    }
  }, [detailTasks])

  // 聚焦后滚动到该节点
  useEffect(() => {
    if (!focusId) return
    const el = nodeRefs.current.get(focusId)
    if (el && el.scrollIntoView) el.scrollIntoView({ block: 'center', behavior: 'smooth' })
  }, [focusId, active && active.key])

  const critChain = useMemo(() => {
    const p = (cpm.allCriticalPaths || [])[0] || []
    const byId = Object.fromEntries(detailTasks.map(t => [t.id, t]))
    return p.map(id => byId[id]).filter(Boolean)
  }, [cpm, detailTasks])

  // 搜索：按标题匹配（≤5 建议）→ 切到所在簇 + 聚焦 + 滚动
  const suggestions = useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return []
    return tasks.filter(t => (t.title || '').toLowerCase().includes(q)).slice(0, 5)
  }, [query, tasks])

  const pickSearch = (t) => {
    const owner = clusters.find(c => c.tasks.some(x => x.id === t.id))
    if (owner) setClusterKey(owner.key)
    else setClusterKey(null)
    setFocusId(t.id)
    setQuery('')
  }

  return (
    <div className="topo" ref={wrapRef}>
      <div className="topo__head">
        <h2 className="topo__title">依赖拓扑</h2>
        {active && clusters.length > 1 && (
          <button className="btn btn--ghost topo__toggle" onClick={() => { setClusterKey(null); setFocusId(null) }}>
            ← 链簇列表（{clusters.length}）
          </button>
        )}
        <button className={`btn btn--ghost topo__toggle${hideIsolated ? ' is-active' : ''}`}
          onClick={() => { setHideIsolated(v => !v); setClusterKey(null); setFocusId(null) }}
          aria-pressed={hideIsolated}
          title="隐藏既无前置也无后继的孤立任务，只看依赖链">
          只看有依赖 {linkedIds.size}/{tasks.length}
        </button>
        <button className={`btn btn--ghost topo__toggle${showAll ? ' is-active' : ''}`}
          onClick={() => setShowAll(s => !s)} aria-pressed={showAll}>
          {showAll ? `全部关键路径 (${cpm.allCriticalPaths.length})` : '单条关键路径'}
        </button>
        {(focusId || hoveredId) && (
          <button className="btn btn--ghost topo__toggle" onClick={() => setFocusId(null)}>清除聚焦</button>
        )}
        <input className="inp inp--xs topo__search" placeholder="搜索任务定位…" value={query}
               onChange={e => setQuery(e.target.value)} />
        <span className="topo__count">
          {active ? `${detailTasks.length} 任务 · ${layers.length} 层` : `${clusters.length} 个链簇 · ${visibleTasks.length}/${tasks.length} 任务`}
        </span>
      </div>

      {suggestions.length > 0 && (
        <div className="topo__search-list">
          {suggestions.map(t => (
            <button key={t.id} className="btn btn--ghost btn--xs" onClick={() => pickSearch(t)}>
              {t.title}
            </button>
          ))}
        </div>
      )}

      {/* 链簇列表：路径多了先分组，一簇一卡 */}
      {!active && clusters.length > 1 && (
        <>
          {tasks.length > 0 && depCount === 0 && (
            <div className="topo__hint">
              当前任务之间<b>还没有依赖关系</b> —— 拓扑是平的，关键路径与阻塞都显示不出来。
              依赖的三种来源：① 想法详情「行为拆解」；② agent 建任务带 <span className="mono">depends_on</span>；
              ③ 打开任务 →「依赖」区 →「编辑依赖」。
            </div>
          )}
          <div className="topo__clusters">
            {clusters.map(c => (
              <button key={c.key} className="topo-cluster" onClick={() => { setClusterKey(c.key); setFocusId(null) }}>
                <div className="topo-cluster__title">
                  {c.roots.length > 1 ? `${c.roots.length} 条起始链` : (c.roots[0]?.title || '链簇')}
                </div>
                <div className="topo-cluster__stats">
                  <span>{c.tasks.length} 任务</span>
                  <span>完成 {c.doneCount}/{c.tasks.length}</span>
                  <span>{c.layerCount} 层</span>
                  <span>总工期 {fmtDur(c.cpm.total)}</span>
                  <span>关键路径 {c.cpm.allCriticalPaths.length}</span>
                  {c.blocked > 0 && <span className="topo-cluster__warn">阻塞 {c.blocked}</span>}
                </div>
                <div className="topo-cluster__sub">
                  {c.tasks.slice(0, 4).map(t => t.title).join(' · ')}{c.tasks.length > 4 ? ' …' : ''}
                </div>
              </button>
            ))}
          </div>
        </>
      )}

      {/* 簇详情：层级图 + 连线 + 图例 + 关键路径摘要 */}
      {active && (
        <>
          <div className="topo__metrics">
            <span>总工期 {fmtDur(cpm.total)}</span>
            <span>关键路径 {cpm.allCriticalPaths.length} 条</span>
            <span>并行度 {cpm.parallel}</span>
            <span>冲突 {cpm.resourceConflicts.length} 段</span>
            <span>阻塞 {detailTasks.filter(t => blockedBy(t, detailTasks)).length}</span>
          </div>

          <div className="topo__legend">
            <span><i className="lg lg--crit" /> 关键路径（无浮动，拖一天整体拖一天）</span>
            <span><i className="lg lg--block" /> 阻塞（前置未完成）</span>
            <span><i className="lg lg--norm" /> 普通（浮动 N = 可延迟 N）</span>
            <span>L1…Ln = 依赖层，同层可并行</span>
            <span className="detail-muted">单击聚焦 · 双击打开</span>
          </div>

          {critChain.length > 1 && (
            <div className="topo__chain">
              关键路径：{critChain.map((t, i) => (
                <span key={t.id}>{i > 0 ? ' → ' : ''}{t.title}</span>
              ))}
              <span className="detail-muted"> · 共 {fmtDur(cpm.total)} · 并行度 {cpm.parallel}</span>
            </div>
          )}

          {dropped.length > 0 && (
            <div className="topo__hint topo__hint--warn">
              ⚠ {dropped.length} 个任务因依赖成环未参与分层（L 序列里看不到）——
              请打开这些任务检查依赖：{dropped.slice(0, 3).map(t => t.title).join('、')}
              {dropped.length > 3 ? ' 等' : ''}
            </div>
          )}

          <svg className="topo__edges" aria-hidden="true">
            {edges.map(e => {
              const inChain = chain && chain.has(e.from) && chain.has(e.to)
              const touches = activeId && (e.from === activeId || e.to === activeId)
              const hl = !!(touches || (focusId && inChain))
              const dim = !!(activeId && !hl)
              const crit = critIds.has(e.from) && critIds.has(e.to)
              const my = (e.y1 + e.y2) / 2
              return (
                <path key={e.key}
                  d={`M ${e.x1} ${e.y1} C ${e.x1} ${my}, ${e.x2} ${my}, ${e.x2} ${e.y2}`}
                  className={`topo__edge${hl ? ' is-hl' : ''}${crit ? ' is-crit' : ''}${dim ? ' is-dim' : ''}`} />
              )
            })}
          </svg>

          {layers.map((layer, i) => (
            <div key={i} className="topo__layer">
              <div className="topo__layer-tag">L{i + 1}</div>
              <div className="topo__layer-nodes">
                {/* eslint-disable-next-line complexity */}
                {layer.map(t => {
                  const p = prio(t.priority)
                  const blocked = blockedBy(t, detailTasks)
                  const tone = blocked ? 'danger' : (STAGE_TONE[t.stage] || 'dim')
                  const inChain = chain && chain.has(t.id)
                  const hl = !!(activeId && (activeId === t.id || inChain))
                  const dim = !!(activeId && activeId !== t.id && !inChain)
                  const crit = critIds.has(t.id)
                  const flt = cpm.float[t.id]
                  return (
                    <button key={t.id}
                      ref={el => { if (el) nodeRefs.current.set(t.id, el); else nodeRefs.current.delete(t.id) }}
                      className={`topo-node topo-node--${tone}${hl ? ' is-hovered' : ''}${crit ? ' is-critical' : ''}${dim ? ' is-dim' : ''}${focusId === t.id ? ' is-focus' : ''}`}
                      role="button" tabIndex={0}
                      title="单击聚焦链路 · 双击打开任务"
                      onMouseEnter={() => setHoveredId(t.id)}
                      onMouseLeave={() => setHoveredId(null)}
                      aria-label={`任务 ${t.title}，阶段 ${t.stage}。回车查看详情`}
                      onClick={() => setFocusId(cur => (cur === t.id ? null : t.id))}
                      onDoubleClick={() => onOpen && onOpen(t)}
                      onKeyDown={e => { if (e.key === 'Enter' && onOpen) onOpen(t) }}>
                      <div className="topo-node__title">{t.title}</div>
                      <div className="topo-node__meta">
                        <span className={`chip${p.p >= 3 ? ' chip--p3' : ''}${p.p === 2 ? ' chip--p2' : ''}`}>{p.label}</span>
                        <span className="topo-node__stage">{t.stage}</span>
                      </div>
                      <div className="topo-node__stats">
                        <span>{fmtDur(t.est_duration_min)}</span>
                        <span>{blocked ? '阻塞' : (crit ? '关键' : `浮动 ${fmtDur(flt)}`)}</span>
                      </div>
                    </button>
                  )
                })}
              </div>
            </div>
          ))}
        </>
      )}

      {!active && clusters.length === 0 && (
        <div className="topo__empty">
          {tasks.length === 0 ? '还没有任务。' : '当前筛选下没有带依赖关系的任务（可关闭「只看有依赖」查看全部）。'}
        </div>
      )}
    </div>
  )
}

/** 顶部更新提示条：仅在有新版可操作时出现（检查/设置在「设置」面板）。 */
import { useEffect, useState } from 'react'
import { api } from '../api'

const ACTIONABLE = ['available', 'downloading', 'ready', 'applying', 'done', 'needs_manual', 'failed']

// eslint-disable-next-line complexity
export default function UpdateBanner({ eventTick, onOpenSettings }) {
  const [st, setSt] = useState(null)
  const [busy, setBusy] = useState(false)
  const [err, setErr] = useState('')
  const [hint, setHint] = useState('')

  async function refresh() {
    try { setSt(await api.updateStatus()); setErr('') } catch { /* ignore */ }
  }

  useEffect(() => { refresh() }, [eventTick])

  if (!st) return null
  const state = st.state
  if (!ACTIONABLE.includes(state)) return null

  async function onPrimary() {
    setBusy(true)
    try {
      if (state === 'available') {
        try { await api.updateDownload() }
        catch (e) { setErr(`下载失败：${e?.message || e}`) }
        await refresh()
      } else if (state === 'ready') {
        try { await api.updateApply() }
        catch { setHint('正在重启应用…') }
      }
    } finally { setBusy(false) }
  }

  async function onDismiss() {
    setBusy(true)
    try {
      try { await api.updateDismiss() }
      catch (e) { setErr(`操作失败：${e?.message || e}`) }
      await refresh()
    } finally { setBusy(false) }
  }

  const label = {
    available: `发现新版本 v${st.latest}`,
    downloading: `正在下载 ${st.progress || 0}%`,
    ready: `已下载 v${st.latest}，重启应用更新`,
    applying: '正在应用更新，即将自动重启…',
    done: '更新完成，正在重启…',
    needs_manual: `v${st.latest} 需手动更新（跨代不兼容）`,
    failed: `更新失败：${st.error || '见 apply.log'}`,
  }[state]

  const tone = state === 'available' || state === 'ready'
      || state === 'applying' || state === 'done' ? 'is-active'
    : state === 'failed' ? 'is-error' : ''

  return (
    <div className={`update-banner ${tone}`} role="status" aria-live="polite">
      <span className="update-banner__text">{label}</span>
      {hint && <span>{hint}</span>}
      {err && <span className="update-banner__err">{err}</span>}
      {state === 'available' && (
        <button className="btn btn--primary btn--sm" disabled={busy} onClick={onPrimary}>立即更新</button>
      )}
      {state === 'ready' && (
        <button className="btn btn--primary btn--sm" disabled={busy} onClick={onPrimary}>重启并更新</button>
      )}
      {state === 'available' && (
        <button className="btn btn--ghost btn--sm" disabled={busy} onClick={onDismiss}>忽略</button>
      )}
      <button className="btn btn--ghost btn--sm" disabled={busy}
              onClick={() => onOpenSettings && onOpenSettings()} title="在设置面板中查看">
        设置
      </button>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { api } from '../api'
import { STAGE_META, fmtDur } from '../constants'

// eslint-disable-next-line complexity
export default function WorkstreamPanel({ task, onOpen }) {
  const [data, setData] = useState(null)
  const [error, setError] = useState(null)

  useEffect(() => {
    let dead = false
    setData(null)
    setError(null)
    api.getWorkstream(task.id)
      .then(d => { if (!dead) setData(d) })
      .catch(e => { if (!dead) setError(e.message || String(e)) })
    return () => { dead = true }
  }, [task.id])

  if (error) return <p className="detail-muted">工作流加载失败：{error}</p>
  if (!data) return <p className="detail-muted">加载工作流…</p>

  const nodes = data.nodes || []
  if (!nodes.length) {
    const cancelled = data.stats?.cancelled || 0
    return (
      <div className="ws-empty">
        <p className="detail-muted">
          {cancelled > 0
            ? `该工作流有 ${cancelled} 个已取消任务，当前没有进行中的成员。`
            : <>这个任务还没有工作流成员。建平级任务时加
              {' '}<code>labels=["part-of:{task.id}"]</code>{' '}
              并用 <code>depends_on</code> 连依赖，就会出现在这里。</>}
        </p>
      </div>
    )
  }

  const byId = Object.fromEntries(nodes.map(n => [n.id, n]))
  const blocked = new Set((data.blocked || []).map(b => b.id))
  const st = data.stats || {}

  return (
    <div className="ws">
      <div className="ws-stats">
        <span><b>{st.done || 0}/{st.total || 0}</b> 完成</span>
        <span className={st.blocked ? 'ws-stat--warn' : ''}>
          <b>{st.blocked || 0}</b> 阻塞
        </span>
        <span>预估 <b>{fmtDur(st.estimate_min)}</b></span>
        <span>关键路径 <b>{st.critical_path || 0}</b> 步</span>
        {data.owner_title && <span className="ws-owner">组：{data.owner_title}</span>}
      </div>

      {data.cycle && (
        <div className="ws-alert">检测到依赖环：{JSON.stringify(data.cycle_path || [])}</div>
      )}

      <div className="ws-layers">
        {(data.layers || []).map((layer, i) => (
          <div className="ws-layer" key={i}>
            <div className="ws-layer__head">第 {i + 1} 层</div>
            {layer.map(id => {
              const n = byId[id]
              if (!n) return null
              const meta = STAGE_META[n.stage] || { label: n.stage, tone: 'dim' }
              return (
                <button
                  key={id}
                  className={`ws-card${blocked.has(id) ? ' is-blocked' : ''}`}
                  onClick={() => onOpen({ id })}
                  title={n.title}
                >
                  <span className="ws-card__title">{n.title}</span>
                  <span className="ws-card__meta">
                    <span className={`chip chip--${meta.tone}`}>{meta.label}</span>
                    <span>{fmtDur(n.est_duration_min)}</span>
                    {blocked.has(id) && <span className="ws-card__blocked">阻塞</span>}
                  </span>
                  {(n.depends_on || []).length > 0 && (
                    <span className="ws-card__deps">
                      {(n.depends_on || []).map(d => (
                        <span key={d} className="ws-dep">{byId[d]?.title || d}</span>
                      ))}
                    </span>
                  )}
                </button>
              )
            })}
          </div>
        ))}
      </div>

      {(data.external || []).length > 0 && (
        <div className="ws-extra">
          <span className="ws-extra__label">外部前置</span>
          {data.external.map((e, i) => (
            <span key={i} className={`ws-dep${e.closed ? '' : ' is-open'}`}>
              {e.from_title || e.from} → {byId[e.to]?.title || e.to}
            </span>
          ))}
        </div>
      )}
      {(data.missing || []).length > 0 && (
        <div className="ws-extra ws-extra--bad">
          <span className="ws-extra__label">缺失依赖</span>
          {data.missing.map((e, i) => (
            <span key={i} className="ws-dep is-open">{e.from} → {e.to}</span>
          ))}
        </div>
      )}
    </div>
  )
}

// web/src/cpm.js
// 独立纯函数：关键路径法（CPM）。不依赖 React/DOM，TopoView/FlowView/Dashboard 可复用。
export const DEFAULT_DURATION = 60

// 关键路径 float 容差；criticalPath（精确 float==0）与 critical（容差内）在 float∈(0,0.5] 时可能不一致
export const EPSILON = 0.5

// 任务时长（分钟）：已完成=0，进行中按剩余时间退化，其余用 est_duration
export function taskDuration(task) {
  const stage = task.stage
  const state = task.state
  const parsed = Number(task.est_duration_min)
  const est = Number.isFinite(parsed) ? parsed : DEFAULT_DURATION
  if (state === 'completed' || stage === 'done' || stage === 'cancelled') return 0
  if (stage === 'implementing') return Math.round(est * 0.5)
  if (stage === 'review') return Math.round(est * 0.25)
  return est
}

// eslint-disable-next-line complexity, max-statements
export function computeCPM(tasks, opts = {}) {
  const byId = Object.fromEntries(tasks.map(t => [t.id, t]))
  const dur = {}
  tasks.forEach(t => { dur[t.id] = taskDuration(t) })

  // 拓扑序（Kahn）
  const deps = Object.fromEntries(tasks.map(t => [t.id, (t.depends_on || []).filter(d => byId[d])]))
  const succ = {}
  tasks.forEach(t => { succ[t.id] = [] })
  const indegree = {}
  tasks.forEach(t => { indegree[t.id] = 0 })
  tasks.forEach(t => {
    deps[t.id].forEach(d => { indegree[t.id] += 1; succ[d].push(t.id) })
  })
  const order = []
  const queue = tasks.filter(t => indegree[t.id] === 0).map(t => t.id)
  const seen = new Set(queue)
  while (queue.length) {
    const id = queue.shift()
    order.push(id)
    succ[id].forEach(c => {
      indegree[c] -= 1
      if (indegree[c] === 0 && !seen.has(c)) { seen.add(c); queue.push(c) }
    })
  }
  // 环检测：order 未覆盖的节点属于环（含自环）。CPM 假定 DAG，
  // 环节点 es/ef/float 是垃圾值，后面从关键路径计算中防御性忽略。
  const inOrder = new Set(order)

  // 正向：ES / EF
  const es = {}, ef = {}
  tasks.forEach(t => { es[t.id] = 0; ef[t.id] = 0 })
  order.forEach(id => {
    const s = deps[id].length ? Math.max(...deps[id].map(d => ef[d])) : 0
    es[id] = s
    ef[id] = s + dur[id]
  })
  const total = tasks.length ? Math.max(...tasks.map(t => ef[t.id])) : 0

  // 反向：LF / LS
  const ls = {}, lf = {}
  tasks.forEach(t => { lf[t.id] = total; ls[t.id] = total - dur[t.id] })
  ;[...order].reverse().forEach(id => {
    const l = succ[id].length ? Math.min(...succ[id].map(c => ls[c])) : total
    lf[id] = l
    ls[id] = l - dur[id]
  })

  // 浮动
  const float = {}
  tasks.forEach(t => { float[t.id] = ls[t.id] - es[t.id] })

  // 单条关键路径：从 EF==total 的终节点回溯，逐级取 EF 最大的前驱。
  // 仅从拓扑序内终节点回溯（环节点已在 order 中排除，防死循环）
  const terminals = tasks.filter(t => inOrder.has(t.id) && ef[t.id] === total)
  const start = terminals.length ? terminals[0].id : null
  const criticalPath = []
  let cur = start
  const seenPath = new Set()
  while (cur && !seenPath.has(cur)) {
    seenPath.add(cur)  // 环防护
    criticalPath.push(cur)
    const preds = deps[cur]
    if (!preds.length) break
    cur = preds.reduce((a, b) => (ef[b] > ef[a] ? b : a))
  }
  criticalPath.reverse()
  const critical = {}

  // 并行度：max 拓扑层宽
  const layer = {}
  tasks.forEach(t => { layer[t.id] = 0 })
  order.forEach(id => {
    deps[id].forEach(d => { layer[id] = Math.max(layer[id], layer[d] + 1) })
  })
  const layerWidth = {}
  tasks.forEach(t => { layerWidth[layer[t.id]] = (layerWidth[layer[t.id]] || 0) + 1 })
  const parallel = Object.keys(layerWidth).length
    ? Math.max(...Object.values(layerWidth))
    : 0

  // 多关键路径：float≈0 节点子图的 DFS，收集全部 root→terminal 路径
  const crit = {}
  tasks.forEach(t => { crit[t.id] = float[t.id] <= EPSILON })
  // 环节点不在拓扑序中，float 为垃圾值；从关键路径计算中排除
  // （CPM 假定 DAG，环输入被防御性忽略）
  if (order.length < tasks.length) {
    tasks.forEach(t => { if (!inOrder.has(t.id)) crit[t.id] = false })
  }
  const isRoot = id => deps[id].length === 0
  const isTerminal = id => (succ[id] || []).length === 0
  const allCriticalPaths = []
  const dfs = (id, path, onPath) => {
    if (onPath.has(id)) return  // 环防护
    const cur = path.concat(id)
    if (isTerminal(id)) { allCriticalPaths.push(cur); return }
    const nextOn = new Set(onPath).add(id)
    ;(succ[id] || []).forEach(c => { if (crit[c]) dfs(c, cur, nextOn) })
  }
  tasks.forEach(t => { if (crit[t.id] && isRoot(t.id)) dfs(t.id, [], new Set()) })

  // critical 标志 = 在任一关键路径上
  const onAny = new Set()
  allCriticalPaths.forEach(p => p.forEach(id => onAny.add(id)))
  tasks.forEach(t => { critical[t.id] = onAny.has(t.id) })

  // 并行度曲线：扫描线 [ES, EF) 区间覆盖计数
  const ev = []
  tasks.forEach(t => {
    if (dur[t.id] <= 0) return
    ev.push({ t: es[t.id], d: +1 })
    ev.push({ t: ef[t.id], d: -1 })
  })
  ev.sort((a, b) => a.t - b.t || a.d - b.d)
  const parallelProfile = []
  let curCount = 0
  let prevT = null
  ev.forEach(e => {
    if (prevT !== null && curCount > 0 && e.t > prevT) {
      parallelProfile.push({ start: prevT, end: e.t, count: curCount })
    }
    curCount += e.d
    prevT = e.t
  })

  // 资源冲突：超阈值区间（默认阈值 = target_agent_type 去重数，无则不标注）
  // 全局并行度告警启发式：并行任务总数超过可用 agent 数，而非同一 agent 争用检测（spec A3 已确认）
  const agentSet = new Set(tasks.map(t => t.target_agent_type).filter(Boolean))
  const maxParallel = opts.maxParallel !== undefined ? opts.maxParallel : (agentSet.size || null)
  const conflicts = maxParallel != null ? parallelProfile.filter(s => s.count > maxParallel) : []
  const resourceConflicts = conflicts.reduce((acc, s) => {
    const last = acc[acc.length - 1]
    if (last && last.end === s.start && last.count === s.count) last.end = s.end
    else acc.push({ start: s.start, end: s.end, count: s.count })
    return acc
  }, [])

  return {
    total,
    es, ef, ls, lf, float,
    criticalPath,
    critical,
    parallel,
    allCriticalPaths,
    parallelProfile,
    resourceConflicts,
  }
}
